CREATE OR REPLACE FUNCTION "admin"."move_category"("p_kind" "text", "p_key" "text", "p_from_parent" "text", "p_parent" "text", "p_before" "text", "p_actor" "uuid") RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  old_parent text;
  parent_level integer := 0;
  siblings text[];
  pos integer;
begin
  if not exists(select 1 from public.profiles where id=p_actor and role='admin' and banned_at is null) then raise exception 'NOT_ADMIN'; end if;
  perform pg_advisory_xact_lock(hashtextextended('shotviva.category_tree',0));
  select parent_id into old_parent from public.template_categories where key=p_key and kind=p_kind and not is_system;
  if not found or old_parent is distinct from p_from_parent then raise exception 'CATEGORY_CHANGED'; end if;
  if p_parent is not null then
    select level into parent_level from public.template_categories where key=p_parent and kind=p_kind and not is_system;
    if not found or p_key='art-styles' then raise exception 'INVALID_PARENT'; end if;
  end if;
  if old_parent is distinct from p_parent then
    -- Include descendants when checking the three-level limit and prohibit cycles before firing move triggers.
    if exists(with recursive subtree(key,depth) as (
      select p_key,1 union all select c.key,s.depth+1 from public.template_categories c join subtree s on c.parent_id=s.key
    ) select 1 from subtree where key=p_parent or depth+parent_level>3) then raise exception 'INVALID_PARENT'; end if;
    update public.template_categories set parent_id=p_parent where key=p_key;
  end if;
  select coalesce(array_agg(key order by sort_order,key),'{}') into siblings from public.template_categories
    where kind=p_kind and not is_system and parent_id is not distinct from p_parent and key<>p_key;
  pos := case when p_before is null then cardinality(siblings)+1 else array_position(siblings,p_before) end;
  if pos is null then raise exception 'CATEGORY_CHANGED'; end if;
  siblings := siblings[1:pos-1] || array[p_key] || siblings[pos:cardinality(siblings)];
  update public.template_categories c set sort_order=o.n*10 from unnest(siblings) with ordinality o(key,n)
    where c.key=o.key and c.sort_order<>o.n*10;
end $$;


ALTER FUNCTION "admin"."move_category"("p_kind" "text", "p_key" "text", "p_from_parent" "text", "p_parent" "text", "p_before" "text", "p_actor" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "admin"."move_category_subtree"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare root text;
begin
  -- The BEFORE trigger derives each child's level. A descendant reaching level 4
  -- (including an attempted cycle) rolls the entire move back.
  update public.template_categories set level=new.level+1 where parent_id=new.key;
  if new.kind='template' then
    select root_key into strict root from public.template_category_paths where key=new.key;
    update public.templates set category_key=root,
      subcategory_key=case when new.key<>root then new.key end
    where coalesce(subcategory_key,category_key)=new.key and
      (category_key<>root or subcategory_key=root);
  end if;
  return null;
end $$;


ALTER FUNCTION "admin"."move_category_subtree"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "admin"."partner_image_aspects"("public"."templates") RETURNS "text"[]
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
  select array(select r.ratio from public.templates t
    left join public.template_sale_approvals s on s.template_id=t.id
    left join public.ai_providers p on p.module='image' and p.is_active
    cross join lateral jsonb_array_elements_text(t.fields->'aspectRatios') with ordinality r(ratio, ord)
    where t.id=$1.id and t.is_active and t.visible_in @> array['partner']
      and not('1k'=any(coalesce(s.unpriced_resolutions,'{}')))
      and (p.id is null or '1k'=any(p.resolutions)) and (p.adapter is distinct from 'openrouter_images'
        or ((p.capabilities->'resolutions') ? '1k' and coalesce(p.capabilities->'providerAspectRatios',p.capabilities->'aspectRatios') ? r.ratio))
    order by r.ord)
$_$;


ALTER FUNCTION "admin"."partner_image_aspects"("public"."templates") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "admin"."prepare_category_node"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare p public.template_categories;
begin
  perform pg_advisory_xact_lock(hashtextextended('shotviva.category_tree',0));
  if tg_op='UPDATE' and (new.key<>old.key or new.kind<>old.kind or new.is_system<>old.is_system) then
    raise exception 'CATEGORY_IDENTITY_IMMUTABLE';
  end if;
  if tg_op='INSERT' and new.slug='' then new.slug:=new.key; end if;
  new.level:=1;
  if new.parent_id is not null then
    select kind,is_system,level,key into strict p.kind,p.is_system,p.level,p.key
      from public.template_categories where key=new.parent_id;
    if p.kind<>new.kind or p.is_system or new.is_system or new.key='art-styles' or new.key=p.key then raise exception 'INVALID_PARENT'; end if;
    new.level:=p.level+1;
  end if;
  return new;
end $$;


ALTER FUNCTION "admin"."prepare_category_node"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "admin"."pricing_activity_fingerprint"() RETURNS "text"
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  select md5(jsonb_build_array(
    (select jsonb_agg(jsonb_build_array(id,credits,free_credits,paid_until) order by id) from public.profiles),
    (select coalesce(max(id),0) from public.credit_ledger),
    (select jsonb_agg(to_jsonb(p) order by id) from public.payments p),
    -- A duplicate callback can refresh updated_at without changing contract terms.
    (select jsonb_agg(to_jsonb(s)-'updated_at' order by id) from public.subscriptions s),
    (select jsonb_agg(to_jsonb(d) order by stripe_dispute_id) from public.payment_disputes d),
    (select max(created_at) from public.generation_jobs)
  )::text)
$$;


ALTER FUNCTION "admin"."pricing_activity_fingerprint"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "admin"."pricing_checkpoint_v2"("p_rollback" boolean) RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare current_digest text;
begin
  perform pg_advisory_xact_lock(hashtextextended('shotviva.template_catalog',0));
  lock table public.profiles,public.generation_jobs,public.credit_ledger,public.payments,public.subscriptions,public.payment_disputes in share row exclusive mode;
  current_digest := admin.pricing_activity_fingerprint();
  if p_rollback then
    delete from admin.pricing_release_checkpoint where version='v2' and fingerprint=current_digest;
    if not found then raise exception 'ECONOMIC_ACTIVITY_AFTER_CUTOVER'; end if;
  else
    insert into admin.pricing_release_checkpoint values('v2',current_digest) on conflict do nothing;
  end if;
end;
$$;


