CREATE OR REPLACE FUNCTION "public"."_affiliate_snapshot"("p_payment" "public"."payments") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    SET "TimeZone" TO 'UTC'
    AS $$
  select jsonb_build_object('owner',a.user_id,'inactive',a.status<>'active',
    'parent',case when a.status='active' and parent.team_enabled and parent.status='active' then parent.user_id end,
    'rate',coalesce(o.l1_bp,r.l1_bp),'bonus',coalesce(po.l2_bp,r.l2_bp),
    'same_ip',coalesce(customer.signup_ip=referrer.signup_ip,false),
    'confirm_after',p_payment.created_at+make_interval(days=>s.hold_days))
    from public.profiles customer join public.affiliates a on a.user_id=customer.referred_by
    join public.profiles referrer on referrer.id=a.user_id
    cross join public.affiliate_settings s
    join admin.catalog_products sku on sku.product_id=p_payment.product_id
    join public.affiliate_rates r on r.product_kind=sku.kind
    left join public.affiliates parent on parent.user_id=a.parent_user_id
    left join public.affiliate_rate_overrides o on (o.user_id,o.product_kind)=(a.user_id,r.product_kind)
    left join public.affiliate_rate_overrides po on (po.user_id,po.product_kind)=(parent.user_id,r.product_kind)
    where s.singleton and customer.id=p_payment.user_id
      and (s.commission_months is null or case
        -- A term extending beyond the payment year always covers this sale. Avoid overflowing
        -- timestamp arithmetic for long terms accepted by the integer setting.
        when s.commission_months > 12 * (1 + extract(year from p_payment.created_at) - extract(year from customer.referred_at)) then true
        else p_payment.created_at <= customer.referred_at + make_interval(months => s.commission_months)
      end);
$$;


ALTER FUNCTION "public"."_affiliate_snapshot"("p_payment" "public"."payments") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_affiliate_write_commission"("p_payment" "public"."payments", "p_snapshot" "jsonb", "p_level" smallint, "p_open" boolean, "p_lost" boolean, "p_release" boolean DEFAULT false) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_old public.affiliate_commissions; v_id bigint; v_amount bigint; v_status text; v_reason text;
  v_owner uuid; v_rate integer; v_confirm timestamptz; v_flags text[]; v_void text;
begin
  select c.* into v_old from public.affiliate_commissions c where c.payment_id=p_payment.id and c.level=p_level for update;
  if not found then
    v_owner:=(p_snapshot->>case p_level when 1 then 'owner' else 'parent' end)::uuid;
    if v_owner is null then return; end if;
    v_rate:=(p_snapshot->>case p_level when 1 then 'rate' else 'bonus' end)::integer;
    v_confirm:=(p_snapshot->>'confirm_after')::timestamptz;
    v_flags:=case when (p_snapshot->>'same_ip')::boolean then array['same_ip'] else '{}' end;
    if p_level=1 and (p_snapshot->>'inactive')::boolean then v_void:='affiliate_inactive'; end if;
  else
    v_owner:=v_old.affiliate_user_id; v_rate:=v_old.rate_bp; v_confirm:=v_old.confirm_after; v_flags:=v_old.flags;
    if v_old.void_reason in ('affiliate_inactive','admin_void') then v_void:=v_old.void_reason; end if;
  end if;
  v_amount:=public._affiliate_due(p_payment.amount_total,p_payment.amount_tax,p_payment.amount_refunded,v_rate);
  if v_old.payout_retained is not null then
    v_amount:=public._affiliate_retained_cents(v_old.payout_retained,v_amount);
  end if;
  if v_void is not null or p_lost then
    v_void:=coalesce(v_void,'dispute_lost'); v_amount:=0;
  elsif v_amount=0 then
    v_void:=case when p_payment.amount_refunded=p_payment.amount_total then 'refunded' else 'zero' end;
  end if;
  v_status:=case when v_amount=0 then 'void' when p_open or (cardinality(v_flags)>0 and v_old.released_by is null and not p_release)
    then 'on_hold' when now()>=v_confirm then 'confirmed' else 'pending' end;
  if not p_release and v_old.id is not null and (v_amount,v_status,v_void) is not distinct from (v_old.amount,v_old.status,v_old.void_reason) then return; end if;
  v_reason:=case when p_release then 'admin_release' when v_void is not null then v_void
    when p_open then 'dispute_open' when v_status='on_hold' then 'same_ip'
    when v_old.status='on_hold' then 'dispute_won'
    when v_amount<v_old.amount then 'partial_refund' when v_status='confirmed' and v_old.id is not null then 'confirmed'
    else 'payment' end;
  insert into public.affiliate_commissions(payment_id,affiliate_user_id,level,product_id,rate_bp,base_usd,amount,status,
    confirm_after,confirmed_at,void_reason,flags,created_at)
  values(p_payment.id,v_owner,p_level,p_payment.product_id,v_rate,p_payment.amount_total-p_payment.amount_tax,v_amount,v_status,
    v_confirm,case when v_status='confirmed' then now() end,v_void,v_flags,p_payment.created_at)
  on conflict(payment_id,level) do update set amount=excluded.amount,status=excluded.status,
    confirmed_at=case when excluded.status='confirmed' then coalesce(affiliate_commissions.confirmed_at,now()) end,
    void_reason=excluded.void_reason,updated_at=now() returning id into v_id;
  insert into public.affiliate_commission_changes(commission_id,old_amount,new_amount,old_status,new_status,reason)
    values(v_id,v_old.amount,v_amount,v_old.status,v_status,v_reason);
end;
$$;


ALTER FUNCTION "public"."_affiliate_write_commission"("p_payment" "public"."payments", "p_snapshot" "jsonb", "p_level" smallint, "p_open" boolean, "p_lost" boolean, "p_release" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_apply_credit_change"("p_user_id" "uuid", "p_pool" "text", "p_kind" "text", "p_delta" integer, "p_reason" "text", "p_idempotency_key" "text", "p_job_id" "uuid" DEFAULT NULL::"uuid", "p_product_id" "text" DEFAULT NULL::"text", "p_paid_days" integer DEFAULT NULL::integer) RETURNS "public"."credit_change"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_profile public.profiles;
  v_existing public.credit_ledger;
  v_result public.credit_change;
  v_paid boolean := p_pool = 'paid';
begin
  if p_idempotency_key is null or length(p_idempotency_key) = 0 then
    raise exception 'INVALID_INPUT' using detail = 'idempotency key is required';
  end if;
  if p_pool is null or p_pool not in ('free', 'paid') then
    raise exception 'INVALID_INPUT' using detail = 'pool must be free or paid';
  end if;

  select * into v_profile from public.profiles where id = p_user_id for update;
  if not found then
    raise exception 'PROFILE_NOT_FOUND';
  end if;

  select * into v_existing from public.credit_ledger where idempotency_key = p_idempotency_key;
  if found then
    if v_existing.user_id <> p_user_id
      or v_existing.kind <> p_kind
      or v_existing.pool <> p_pool
      or v_existing.product_id is distinct from p_product_id then
      raise exception 'IDEMPOTENCY_CONFLICT';
    end if;
    v_result := row(false, v_profile.credits, v_profile.free_credits, v_profile.paid_until);
    return v_result;
  end if;

  if (case when v_paid then v_profile.credits else v_profile.free_credits end) + p_delta < 0 then
    raise exception 'CREDITS_INSUFFICIENT';
  end if;

  update public.profiles
     set credits = credits + case when v_paid then p_delta else 0 end,
         free_credits = free_credits + case when v_paid then 0 else p_delta end,
         -- greatest() skips nulls: an expired or empty window restarts from now.
         paid_until = case
           when p_paid_days is null then paid_until
           else greatest(paid_until, now()) + make_interval(days => p_paid_days)
         end
   where id = p_user_id
  returning credits, free_credits, paid_until
       into v_result.credits, v_result.free_credits, v_result.paid_until;

  insert into public.credit_ledger
    (user_id, pool, kind, delta, balance_after, paid_until_after, reason, idempotency_key, job_id, product_id)
  values
    (p_user_id, p_pool, p_kind, p_delta,
     case when v_paid then v_result.credits else v_result.free_credits end,
     case when p_paid_days is null then null else v_result.paid_until end,
     p_reason, p_idempotency_key, p_job_id, p_product_id);

  v_result.applied := true;
  return v_result;
end;
$$;


ALTER FUNCTION "public"."_apply_credit_change"("p_user_id" "uuid", "p_pool" "text", "p_kind" "text", "p_delta" integer, "p_reason" "text", "p_idempotency_key" "text", "p_job_id" "uuid", "p_product_id" "text", "p_paid_days" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_end_membership_after_refund"("p_user_id" "uuid", "p_payment" "public"."payments") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_current timestamptz;
  v_end timestamptz;
  v_moved boolean := false;
  v_own record;
begin
  select paid_until into v_current from public.profiles where id = p_user_id for update;
  if v_current > now() then
    v_end := least(v_current, greatest(now(), coalesce(public._membership_end_without_refunded(p_user_id), now())));
    if v_end < v_current then
      update public.profiles set paid_until = v_end where id = p_user_id;
      v_moved := true;
    end if;
  end if;
  if v_moved then
    return true;
  end if;

  -- Not moved back (or already moved by an earlier delivery): still ended if this payment's own
  -- period is the one running now, so a redelivery retries the subscription cancel.
  select l.idempotency_key, l.created_at, l.paid_until_after, pr.days into v_own
    from public.credit_ledger l
    join public.products pr on pr.id = l.product_id
   where l.user_id = p_user_id
     and l.kind = 'purchase'
     and l.idempotency_key in ('purchase:' || p_payment.stripe_session_id, 'renewal:' || p_payment.stripe_invoice_id, 'purchase:' || p_payment.waffo_payment_id);
  if not found or v_own.days is null then
    return false;
  end if;
  return now() < case
    when v_own.idempotency_key like 'renewal:%' then least(v_own.paid_until_after, v_own.created_at + make_interval(days => v_own.days + 3))
    else v_own.created_at + make_interval(days => v_own.days)
  end;
end;
$$;


ALTER FUNCTION "public"."_end_membership_after_refund"("p_user_id" "uuid", "p_payment" "public"."payments") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_enforce_code_gift_policy"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  policy jsonb;
  max_credits numeric;
begin
  if new.invitee_credits is null then return new; end if;
  if tg_op = 'UPDATE' then
    if row(old.invitee_credits, old.invitee_pool, old.max_redemptions) is not distinct from
       row(new.invitee_credits, new.invitee_pool, new.max_redemptions) then return new; end if;
  end if;

  select value into policy from public.system_settings where key = 'code_gift_policy' for share;
  if jsonb_typeof(policy->'maxCreditsPerCode') is distinct from 'number'
    or jsonb_typeof(policy->'requirePaidGiftCap') is distinct from 'boolean' then
    raise exception 'INVALID_CODE_GIFT_POLICY';
  end if;
  max_credits := (policy->>'maxCreditsPerCode')::numeric;
  if max_credits <= 0 or max_credits <> trunc(max_credits) or max_credits > 2147483647 then
    raise exception 'INVALID_CODE_GIFT_POLICY';
  end if;
  if new.invitee_credits > max_credits then raise exception 'CODE_GIFT_LIMIT'; end if;
  if new.invitee_pool = 'paid' and new.max_redemptions is null and (policy->>'requirePaidGiftCap')::boolean then
    raise exception 'CODE_GIFT_CAP_REQUIRED';
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."_enforce_code_gift_policy"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_link_early_payment_disputes"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  d public.payment_disputes;
  claw jsonb;
  closed_rows public.payment_disputes[] := '{}';
begin
  perform pg_advisory_xact_lock(hashtextextended(new.stripe_charge_id, 914));
  for d in select * from public.payment_disputes
            where stripe_charge_id = new.stripe_charge_id and payment_id is null
            order by created_at, stripe_dispute_id for update
  loop
    -- Replay the open and (if present) close within this subtransaction. T71
    -- applies closing effects only on the first transition from an open row.
    update public.payment_disputes set payment_id = new.id, user_id = new.user_id,
                                      closed_at = null, closed_status = null
     where stripe_dispute_id = d.stripe_dispute_id;
    update public.payments set status = 'disputed' where id = new.id and status <> 'disputed';
    claw := public.clawback_payment_credits(new.id, 'dispute:' || d.stripe_dispute_id, '拒付扣回 ' || d.stripe_dispute_id);
    update public.payment_disputes set credits_clawed_back = (claw ->> 'taken')::integer,
                                      clawback_shortfall = (claw ->> 'written_off')::integer
     where stripe_dispute_id = d.stripe_dispute_id;
    if d.closed_at is not null then
      closed_rows := array_append(closed_rows, d);
    end if;
  end loop;
  -- An unrelated charge or a payment with no early dispute resolves nothing.
  if not found then return null; end if;
  -- Attach every case before closing any: T71 transfers the held share to a
  -- sibling open case and restores it only when the last eligible case closes.
  for d in select * from unnest(closed_rows) order by closed_at, stripe_dispute_id loop
    perform public.close_payment_dispute(d.stripe_dispute_id, d.closed_status);
    update public.payment_disputes set closed_at = d.closed_at where stripe_dispute_id = d.stripe_dispute_id;
  end loop;
  update public.payment_dispute_link_errors set resolved_at = now()
   where payment_id = new.id and resolved_at is null;
  return null;
exception when others or query_canceled or assert_failure then
  -- The subtransaction rolls back the link, debit and related commission changes together.
  begin
    insert into public.payment_dispute_link_errors(payment_id, error_code) values (new.id, sqlstate)
      on conflict (payment_id) do update set error_code = excluded.error_code, occurred_at = now(), resolved_at = null;
  exception when others or query_canceled or assert_failure then
    return null;
  end;
  return null;
end;
$$;


ALTER FUNCTION "public"."_link_early_payment_disputes"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_match_dispute_before_insert"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  perform pg_advisory_xact_lock(hashtextextended(new.stripe_charge_id, 914));
  select p.id, p.user_id into new.payment_id, new.user_id from public.payments p
   where p.stripe_charge_id = new.stripe_charge_id for update;
  return new;
end;
$$;


ALTER FUNCTION "public"."_match_dispute_before_insert"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_membership_end_without_refunded"("p_user_id" "uuid") RETURNS timestamp with time zone
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_end timestamptz;
  v_held text;
  r record;
begin
  for r in
    select l.idempotency_key, l.created_at, l.paid_until_after, l.product_id, pr.days
      from public.credit_ledger l
      join public.products pr on pr.id = l.product_id
     where l.user_id = p_user_id
       and l.pool = 'paid'
       and l.kind = 'purchase'
       and l.delta > 0
       and pr.days is not null
       and not exists (
         select 1 from public.payments p
          where p.user_id = p_user_id
            and p.status <> 'paid'
            and l.idempotency_key in ('purchase:' || p.stripe_session_id, 'renewal:' || p.stripe_invoice_id, 'purchase:' || p.waffo_payment_id)
       )
     order by l.created_at, l.id
  loop
    if r.idempotency_key like 'renewal:%' then
      v_end := greatest(v_end, least(r.paid_until_after, r.created_at + make_interval(days => r.days + 3)));
    elsif v_end > r.created_at
          and admin.catalog_membership_rank(r.product_id) > admin.catalog_membership_rank(v_held) then
      v_end := greatest(v_end, r.created_at + make_interval(days => r.days));
    else
      v_end := greatest(v_end, r.created_at) + make_interval(days => r.days);
    end if;
    v_held := r.product_id;
  end loop;
  return v_end;
end;
$$;


ALTER FUNCTION "public"."_membership_end_without_refunded"("p_user_id" "uuid") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."payment_disputes" (
    "stripe_dispute_id" "text" NOT NULL,
    "stripe_charge_id" "text" NOT NULL,
    "payment_id" bigint,
    "user_id" "uuid",
    "amount" integer NOT NULL,
    "currency" "text" NOT NULL,
    "reason" "text" NOT NULL,
    "responder" "text" NOT NULL,
    "due_by" timestamp with time zone,
    "auto_banned_at" timestamp with time zone,
    "evidence_drafted_at" timestamp with time zone,
    "submitted_at" timestamp with time zone,
    "submitted_by" "uuid",
    "reminded_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "credits_clawed_back" integer DEFAULT 0 NOT NULL,
    "clawback_shortfall" integer DEFAULT 0 NOT NULL,
    "closed_status" "text",
    "closed_at" timestamp with time zone,
    "credits_restored" integer DEFAULT 0 NOT NULL,
    CONSTRAINT "payment_disputes_amount_check" CHECK (("amount" >= 0)),
    CONSTRAINT "payment_disputes_check" CHECK ((("submitted_by" IS NULL) OR ("submitted_at" IS NOT NULL))),
    CONSTRAINT "payment_disputes_clawback_shortfall_check" CHECK (("clawback_shortfall" >= 0)),
    CONSTRAINT "payment_disputes_closed_status_check" CHECK (("closed_status" ~ '^[a-z_]{1,40}$'::"text")),
    CONSTRAINT "payment_disputes_credits_clawed_back_check" CHECK (("credits_clawed_back" >= 0)),
    CONSTRAINT "payment_disputes_credits_restored_check" CHECK (("credits_restored" >= 0)),
    CONSTRAINT "payment_disputes_currency_check" CHECK (("currency" ~ '^[a-z]{3}$'::"text")),
    CONSTRAINT "payment_disputes_reason_check" CHECK (("length"("reason") > 0)),
    CONSTRAINT "payment_disputes_responder_check" CHECK (("responder" = ANY (ARRAY['shotviva'::"text", 'stripe'::"text"]))),
    CONSTRAINT "payment_disputes_stripe_charge_id_check" CHECK (("stripe_charge_id" ~ '^(ch|py)_'::"text")),
    CONSTRAINT "payment_disputes_stripe_dispute_id_check" CHECK (("stripe_dispute_id" ~ '^(dp|du)_'::"text"))
);


ALTER TABLE "public"."payment_disputes" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_payment_dispute_answer"("p_row" "public"."payment_disputes", "p_created" boolean) RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select jsonb_build_object(
    'created', p_created,
    'user_id', p_row.user_id,
    'payment_id', p_row.payment_id,
    'responder', p_row.responder,
    'auto_banned', p_row.auto_banned_at is not null,
    'drafted', p_row.evidence_drafted_at is not null,
    'credits_clawed_back', (select p.credits_clawed_back from public.payments p where p.id = p_row.payment_id),
    'clawback_shortfall', (select p.clawback_shortfall from public.payments p where p.id = p_row.payment_id)
  );
$$;


ALTER FUNCTION "public"."_payment_dispute_answer"("p_row" "public"."payment_disputes", "p_created" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_payment_granted_credits"("p_payment" "public"."payments") RETURNS integer
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select coalesce(
    (select l.delta
       from public.credit_ledger l
      where l.idempotency_key = case
              when p_payment.stripe_session_id is not null then 'purchase:' || p_payment.stripe_session_id
              when p_payment.stripe_invoice_id is not null then 'renewal:' || p_payment.stripe_invoice_id
              when p_payment.waffo_payment_id is not null then 'purchase:' || p_payment.waffo_payment_id
            end
        and l.user_id = p_payment.user_id
        and l.kind = 'purchase'
        and l.pool = 'paid'),
    (select pr.credits from public.products pr where pr.id = p_payment.product_id),
    0
  );
$$;


ALTER FUNCTION "public"."_payment_granted_credits"("p_payment" "public"."payments") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_template_has_cover_parts"("p_before" "text", "p_after" "text", "p_locales_json" "jsonb", "p_locales" "text"[]) RETURNS boolean
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select (nullif(btrim(p_before), '') is not null or exists (
            select 1 from unnest(coalesce(p_locales, '{}')) as l(code) where nullif(btrim(p_locales_json -> l.code ->> 'before'), '') is not null))
     and (nullif(btrim(p_after), '') is not null or exists (
            select 1 from unnest(coalesce(p_locales, '{}')) as l(code) where nullif(btrim(p_locales_json -> l.code ->> 'after'), '') is not null))
$$;


ALTER FUNCTION "public"."_template_has_cover_parts"("p_before" "text", "p_after" "text", "p_locales_json" "jsonb", "p_locales" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_validate_code_discount"("p_products" "text"[], "p_percent" integer, "p_catalog" "jsonb", "p_floor_product_id" "text") RETURNS "void"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  entry record;
  v_cents numeric;
  v_credits numeric;
  active_rates jsonb := '{}';
  floor_cents numeric;
  floor_credits numeric;
  invalid_products text[];
begin
  if admin.is_template_catalog_v2() then
    -- Bind the caller's preview and minimum subscription to the same published terms.
    if jsonb_typeof(p_catalog) is distinct from 'array' or
       (select jsonb_agg(value order by value->>'id') from jsonb_array_elements(p_catalog))
       is distinct from (select jsonb_agg(jsonb_build_object('id',id,'priceCents',cents,'credits',credits,
          'subscription',kind<>'pack') order by id) from admin.catalog_candidate(null,null,null,false))
       or not exists(select from admin.catalog_candidate(null,null,null,false) f
         where f.id=p_floor_product_id and f.kind<>'pack' and not exists(
           select from admin.catalog_candidate(null,null,null,false) i
            where i.kind<>'pack' and i.cents*f.credits<f.cents*i.credits)) then
      raise exception 'INVALID_CODE_CATALOG';
    end if;
    select array_agg(t.id order by t.id) into invalid_products from unnest(p_products) t(id)
      where admin.catalog_code_conflict(array[t.id],p_percent,null,null,null,false) is not null;
    if invalid_products is not null then
      raise exception 'CODE_DISCOUNT_PRODUCTS' using detail=to_json(invalid_products)::text;
    end if;
    return;
  end if;
  if jsonb_typeof(p_catalog) is distinct from 'array' or p_floor_product_id is null then
    raise exception 'INVALID_CODE_CATALOG';
  end if;
  if jsonb_array_length(p_catalog) > (select count(*) from public.products) then
    raise exception 'INVALID_CODE_CATALOG';
  end if;

  for entry in
    select data.item, p.id, p.active, (p.days is not null) as subscription
      from jsonb_array_elements(p_catalog) as data(item)
      left join public.products p on p.id = data.item->>'id'
  loop
    if entry.id is null or active_rates ? entry.id
      or jsonb_typeof(entry.item->'priceCents') is distinct from 'number'
      or jsonb_typeof(entry.item->'credits') is distinct from 'number'
      or entry.item->'subscription' is distinct from to_jsonb(entry.subscription) then
      raise exception 'INVALID_CODE_CATALOG';
    end if;
    v_cents := (entry.item->>'priceCents')::numeric;
    v_credits := (entry.item->>'credits')::numeric;
    if v_cents <= 0 or v_cents <> trunc(v_cents) or v_cents > 9007199254740991
      or v_credits <= 0 or v_credits <> trunc(v_credits) or v_credits > 2147483647 then
      raise exception 'INVALID_CODE_CATALOG';
    end if;
    -- Keep an inactive ID as JSON null so duplicates are still rejected but the product
    -- cannot be either a floor or a discount target.
    active_rates := active_rates || jsonb_build_object(entry.id, case when entry.active then entry.item end);
  end loop;

  floor_cents := (active_rates->p_floor_product_id->>'priceCents')::numeric;
  floor_credits := (active_rates->p_floor_product_id->>'credits')::numeric;
  if active_rates->p_floor_product_id->'subscription' is distinct from 'true'::jsonb
     or exists (select 1 from public.products p where p.active and p.days is not null and
          (not (active_rates ? p.id) or
           (active_rates->p.id->>'priceCents')::numeric * floor_credits
             < floor_cents * (active_rates->p.id->>'credits')::numeric)) then
    raise exception 'INVALID_CODE_CATALOG';
  end if;

  select array_agg(t.id order by t.id) into invalid_products from unnest(p_products) t(id)
    where (active_rates->t.id->>'credits') is null
       or (active_rates->t.id->>'priceCents')::numeric * (100 - p_percent) * floor_credits
          < floor_cents * (active_rates->t.id->>'credits')::numeric * 100;
  if invalid_products is not null then
    raise exception 'CODE_DISCOUNT_PRODUCTS' using detail = to_json(invalid_products)::text;
  end if;
end;
$$;


ALTER FUNCTION "public"."_validate_code_discount"("p_products" "text"[], "p_percent" integer, "p_catalog" "jsonb", "p_floor_product_id" "text") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."support_ticket_messages" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "ticket_id" "uuid" NOT NULL,
    "author" "text" NOT NULL,
    "body" "text" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "support_ticket_messages_author_check" CHECK (("author" = ANY (ARRAY['user'::"text", 'admin'::"text"]))),
    CONSTRAINT "support_ticket_messages_body_check" CHECK ((("char_length"("btrim"("body")) >= 1) AND ("char_length"("btrim"("body")) <= 2000)))
);


ALTER TABLE "public"."support_ticket_messages" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."add_ticket_message"("p_ticket_id" "uuid", "p_user_id" "uuid", "p_body" "text", "p_images" "jsonb" DEFAULT '[]'::"jsonb") RETURNS "public"."support_ticket_messages"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_status text;
  v_message public.support_ticket_messages;
begin
  if p_body is null or char_length(btrim(p_body)) not between 1 and 2000 then
    raise exception 'INVALID_INPUT' using detail = 'body must be 1 to 2000 characters';
  end if;

  -- Locked, so an Owner closing the ticket at the same moment is seen either before or after.
  select status into v_status
    from public.support_tickets
   where id = p_ticket_id and user_id = p_user_id
     for update;
  if not found then
    raise exception 'TICKET_NOT_FOUND';
  end if;
  if v_status = 'closed' then
    raise exception 'TICKET_CLOSED';
  end if;

  update public.support_tickets
     set status = 'open', last_message_at = now(), user_seen_at = now()
   where id = p_ticket_id;

  insert into public.support_ticket_messages (ticket_id, author, body)
  values (p_ticket_id, 'user', btrim(p_body))
  returning * into v_message;

  perform public.attach_ticket_images(p_ticket_id, p_user_id, v_message.id, p_images);
  return v_message;
end;
$$;


ALTER FUNCTION "public"."add_ticket_message"("p_ticket_id" "uuid", "p_user_id" "uuid", "p_body" "text", "p_images" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_ack_reference_deletions"("p_actor" "uuid", "p_keys" "text"[]) RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
begin
  perform admin.require_reference_admin(p_actor);
  delete from public.reference_object_deletions where r2_key=any(p_keys) and created_at<=clock_timestamp();
end $$;


ALTER FUNCTION "public"."admin_ack_reference_deletions"("p_actor" "uuid", "p_keys" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_activate_announcement"("p_id" "uuid", "p_active" boolean, "p_actor" "uuid") RETURNS "uuid"[]
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  v_row public.site_announcements;
  v_window tstzrange;
  v_stopped uuid[];
begin
  if p_active is null then
    raise exception 'INVALID_INPUT' using detail = 'active is required';
  end if;

  -- Serialises two switches: each would otherwise scan for overlaps before the other commits.
  -- Plain reads (the banner) are not blocked.
  lock table public.site_announcements in share row exclusive mode;

  select * into v_row from public.site_announcements where id = p_id;
  if not found then
    raise exception 'ANNOUNCEMENT_NOT_FOUND';
  end if;

  if not p_active then
    update public.site_announcements set is_active = false, updated_by = p_actor where id = p_id and is_active;
    return '{}'::uuid[];
  end if;

  v_window := tstzrange(coalesce(v_row.starts_at, '-infinity'::timestamptz), coalesce(v_row.ends_at, 'infinity'::timestamptz));

  with stopped as (
    update public.site_announcements a
       set is_active = false, updated_by = p_actor
     where a.is_active
       and a.id <> p_id
       and tstzrange(coalesce(a.starts_at, '-infinity'::timestamptz), coalesce(a.ends_at, 'infinity'::timestamptz)) && v_window
    returning a.id
  )
  select coalesce(array_agg(id order by id), '{}'::uuid[]) into v_stopped from stopped;

  update public.site_announcements set is_active = true, updated_by = p_actor where id = p_id and not is_active;
  return v_stopped;
end;
$$;


ALTER FUNCTION "public"."admin_activate_announcement"("p_id" "uuid", "p_active" boolean, "p_actor" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_activate_provider"("p_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  v_module text;
begin
  select module into v_module from public.ai_providers where id = p_id;
  if not found then
    raise exception 'PROVIDER_NOT_FOUND';
  end if;

  perform 1 from public.ai_providers where module = v_module order by id for update;

  update public.ai_providers set is_active = false where module = v_module and is_active and id <> p_id;
  update public.ai_providers set is_active = true where id = p_id and not is_active;
end;
$$;


ALTER FUNCTION "public"."admin_activate_provider"("p_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_adjust_credits"("p_user_id" "uuid", "p_amount" integer, "p_reason" "text", "p_pool" "text", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "public"."credit_change"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if p_amount is null or p_amount = 0 then
    raise exception 'INVALID_INPUT' using detail = 'amount must be non-zero';
  end if;
  return public._apply_credit_change(
    p_user_id, p_pool, 'admin_adjust', p_amount, p_reason,
    coalesce(p_idempotency_key, 'admin:' || gen_random_uuid()::text)
  );
end;
$$;


ALTER FUNCTION "public"."admin_adjust_credits"("p_user_id" "uuid", "p_amount" integer, "p_reason" "text", "p_pool" "text", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_affiliate_adjust"("p_actor" "uuid", "p_input" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_user uuid:=(p_input->>'user_id')::uuid; v_request uuid:=(p_input->>'request_id')::uuid;
  v_amount bigint:=(p_input->>'amount')::bigint; v_reason text:=nullif(trim(p_input->>'reason'),''); v_id bigint;
begin
  perform public._affiliate_require_admin(p_actor);
  insert into public.affiliate_adjustments(request_id,affiliate_user_id,amount,reason,created_by)
    values(v_request,v_user,v_amount,v_reason,p_actor) on conflict(request_id) do nothing returning id into v_id;
  if v_id is null then
    if not exists(select from public.affiliate_adjustments where request_id=v_request and affiliate_user_id=v_user
      and amount=v_amount and reason=v_reason and created_by=p_actor) then raise exception 'AFFILIATE_IDEMPOTENCY_CONFLICT'; end if;
    return;
  end if;
  perform public._affiliate_audit(p_actor,'adjust',v_id::text,v_reason);
end;
$$;


ALTER FUNCTION "public"."admin_affiliate_adjust"("p_actor" "uuid", "p_input" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_affiliate_allow_reapply"("p_actor" "uuid", "p_input" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_user uuid:=(p_input->>'user_id')::uuid; v_reason text;
begin
  perform public._affiliate_require_admin(p_actor);
  update public.affiliates set reapply_allowed=true
    where user_id=v_user and status='rejected' and not reapply_allowed
    returning reject_reason into v_reason;
  if not found then raise exception 'AFFILIATE_NOT_REJECTED'; end if;
  -- Keep the prior reason even for rejected rows that predate this workflow.
  perform public._affiliate_audit(p_actor,'decide',v_user::text,concat('allow_reapply: ',v_reason));
end;
$$;


ALTER FUNCTION "public"."admin_affiliate_allow_reapply"("p_actor" "uuid", "p_input" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_affiliate_commission_history"("p_actor" "uuid", "p_user" "uuid", "p_commission" bigint, "p_level" smallint, "p_before_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_before_id" bigint DEFAULT NULL::bigint) RETURNS TABLE("id" bigint, "at" timestamp with time zone, "old_amount" bigint, "new_amount" bigint, "old_status" "text", "new_status" "text", "reason" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  perform public._affiliate_require_admin(p_actor);
  if p_level is null or p_level not in (1,2) or (p_before_at is null)<>(p_before_id is null)
    then raise exception 'INVALID_INPUT'; end if;
  return query select h.id,h.at,h.old_amount,h.new_amount,h.old_status,h.new_status,h.reason
    from public.affiliate_commissions c join public.affiliate_commission_changes h on h.commission_id=c.id
    where c.id=p_commission and c.affiliate_user_id=p_user and c.level=p_level
      and (p_before_at is null or (h.at,h.id)<(p_before_at,p_before_id))
    order by h.at desc,h.id desc limit 31;
end;
$$;


ALTER FUNCTION "public"."admin_affiliate_commission_history"("p_actor" "uuid", "p_user" "uuid", "p_commission" bigint, "p_level" smallint, "p_before_at" timestamp with time zone, "p_before_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_affiliate_commission_release"("p_actor" "uuid", "p_input" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_id bigint:=(p_input->>'commission_id')::bigint; v_decision text:=p_input->>'decision';
  v_reason text:=nullif(trim(p_input->>'reason'),''); v_old public.affiliate_commissions; v_payment public.payments; v_open boolean; v_lost boolean;
begin
  perform public._affiliate_require_admin(p_actor);
  if v_decision is null or v_decision not in ('release','void') or v_reason is null then raise exception 'INVALID_INPUT'; end if;
  -- Same lock order as the trigger and retry: payment, then commission.
  select p.* into strict v_payment from public.payments p join public.affiliate_commissions c on c.payment_id=p.id where c.id=v_id for update of p;
  select c.* into strict v_old from public.affiliate_commissions c where c.id=v_id for update;
  if v_decision='void' then
    if v_old.void_reason='admin_void' then return; end if;
    update public.affiliate_commissions set status='void',amount=0,void_reason='admin_void',updated_at=now() where id=v_id;
    insert into public.affiliate_commission_changes(commission_id,old_amount,new_amount,old_status,new_status,reason)
      values(v_id,v_old.amount,0,v_old.status,'void','admin_void');
  else
    if cardinality(v_old.flags)=0 or v_old.released_by is not null then raise exception 'AFFILIATE_NOT_FLAGGED'; end if;
    update public.affiliate_commissions set released_by=p_actor where id=v_id;
    select is_open,is_lost into strict v_open,v_lost from public._affiliate_dispute_state(v_payment);
    perform public._affiliate_write_commission(v_payment,null,v_old.level,v_open,v_lost,true);
  end if;
  perform public._affiliate_audit(p_actor,'commission_release',v_id::text,v_decision || ': ' || v_reason);
end;
$$;


ALTER FUNCTION "public"."admin_affiliate_commission_release"("p_actor" "uuid", "p_input" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_affiliate_create"("p_actor" "uuid", "p_input" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_user uuid:=(p_input->>'user_id')::uuid; v_invited boolean;
begin
  perform public._affiliate_require_admin(p_actor);
  select u.invited_at is not null and u.email_confirmed_at is null into strict v_invited
    from auth.users u where id=v_user for update;
  insert into public.affiliates(user_id,slug,status,application,approved_at,approved_by)
    values(v_user,p_input->>'slug',case when v_invited then 'pending' else 'active' end,
      case when v_invited then '{"source":"admin_invite"}'::jsonb else '{}' end,
      case when not v_invited then now() end,p_actor);
  perform public._affiliate_overrides(v_user,p_input->'overrides');
  perform public._affiliate_audit(p_actor,'create',v_user::text);
end;
$$;


ALTER FUNCTION "public"."admin_affiliate_create"("p_actor" "uuid", "p_input" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_affiliate_decide"("p_actor" "uuid", "p_input" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_user uuid:=(p_input->>'user_id')::uuid; v_status text:=p_input->>'status'; v_reason text:=nullif(trim(p_input->>'reason'),'');
begin
  perform public._affiliate_require_admin(p_actor);
  if v_status not in ('active','rejected') or v_status is null or (v_status='rejected' and v_reason is null) then raise exception 'INVALID_INPUT'; end if;
  update public.affiliates set status=v_status,slug=coalesce(p_input->>'slug',slug),reject_reason=case when v_status='rejected' then v_reason end,
    approved_by=case when v_status='active' then p_actor end,approved_at=case when v_status='active' then now() end
    where user_id=v_user and status='pending' and application->>'source' is distinct from 'admin_invite';
  if not found then raise exception 'AFFILIATE_NOT_PENDING'; end if;
  perform public._affiliate_audit(p_actor,'decide',v_user::text,coalesce(v_reason,v_status));
end;
$$;


ALTER FUNCTION "public"."admin_affiliate_decide"("p_actor" "uuid", "p_input" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_affiliate_directory"("p_actor" "uuid", "p_query" "text" DEFAULT NULL::"text", "p_review" "text" DEFAULT NULL::"text", "p_parent" "uuid" DEFAULT NULL::"uuid", "p_before_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_before_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("user_id" "uuid", "slug" "text", "status" "text", "source" "text", "name" "text", "email" "text", "phone" "text", "team_enabled" boolean, "team_count" bigint, "created_at" timestamp with time zone, "total" bigint, "confirmed" bigint, "unwithdrawn" bigint, "paid" bigint)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare v_q text:=nullif(lower(btrim(p_query)),''); v_prefix text; v_phone text; v_user uuid;
begin
  perform public._affiliate_require_admin(p_actor);
  if length(v_q)>254 or p_review not in ('pending','rejected') or (p_before_at is null)<>(p_before_id is null)
    then raise exception 'INVALID_INPUT'; end if;
  if v_q ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then v_user:=v_q::uuid; end if;
  if v_q ~ '^\+?[0-9][0-9 ()-]*$' then v_phone:=regexp_replace(v_q,'[^0-9]','','g'); end if;
  v_prefix:=replace(replace(replace(v_q,'\','\\'),'%','\%'),'_','\_')||'%';
  return query with matches as (
    select a.user_id from public.affiliates a where a.user_id=v_user
    union all select a.user_id from public.affiliates a where v_prefix is not null and a.slug like v_prefix
    union all select a.user_id from public.affiliates a
      where v_prefix is not null and lower(left(a.application->>'name',254)) like v_prefix
    union all select u.id from auth.users u where position('@' in v_q)>0 and u.email=v_q
    union all select u.id from auth.users u where v_phone is not null and u.phone in (v_phone,'+'||v_phone,
      case when v_phone ~ '^1[3-9][0-9]{9}$' then '86'||v_phone end)
  ), page as materialized (
    select a.user_id,a.created_at from public.affiliates a
    where (v_q is null or a.user_id in (select m.user_id from matches m))
      and (p_review is null or (a.status=p_review and a.application->>'source' is distinct from 'admin_invite'))
      and (p_parent is null or a.parent_user_id=p_parent)
      and (p_before_at is null or (a.created_at,a.user_id)<(p_before_at,p_before_id))
    order by a.created_at desc,a.user_id desc limit 31
  )
  select r.user_id,r.slug,r.status,r.source,r.name,r.email,r.phone,r.team_enabled,r.team_count,r.created_at,
    r.total,r.confirmed,r.unwithdrawn,r.paid
  from page join admin.affiliate_directory_rows r on r.user_id=page.user_id order by page.created_at desc,page.user_id desc;
end;
$_$;


ALTER FUNCTION "public"."admin_affiliate_directory"("p_actor" "uuid", "p_query" "text", "p_review" "text", "p_parent" "uuid", "p_before_at" timestamp with time zone, "p_before_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_affiliate_dossier"("p_actor" "uuid", "p_user" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_result jsonb;
begin
  perform public._affiliate_require_admin(p_actor);
  select to_jsonb(r)||jsonb_build_object(
    'registered_at',u.created_at,'country',a.country,'parent_user_id',a.parent_user_id,'application',a.application,
    'payout_method',a.payout_method,'payout_details',a.payout_details,'us_person',a.us_person,
    'terms_version',a.terms_version,'terms_accepted_at',a.terms_accepted_at,'admin_note',a.admin_note,
    'approved_at',a.approved_at,'approved_by',a.approved_by,'reject_reason',a.reject_reason,'reapply_allowed',a.reapply_allowed,
    'rates',(select coalesce(jsonb_agg(jsonb_build_object('product_kind',o.product_kind,'l1_bp',o.l1_bp,'l2_bp',o.l2_bp)
      order by o.product_kind),'[]'::jsonb) from public.affiliate_rate_overrides o where o.user_id=r.user_id))
    into v_result from admin.affiliate_directory_rows r join public.affiliates a on a.user_id=r.user_id
      join auth.users u on u.id=r.user_id where r.user_id=p_user;
  return v_result;
end;
$$;


ALTER FUNCTION "public"."admin_affiliate_dossier"("p_actor" "uuid", "p_user" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_affiliate_dossier_log"("p_actor" "uuid", "p_user" "uuid", "p_before_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_before_id" bigint DEFAULT NULL::bigint) RETURNS TABLE("id" bigint, "created_at" timestamp with time zone, "action" "text", "user_id" "uuid", "target_id" "text", "reason" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  perform public._affiliate_require_admin(p_actor);
  if (p_before_at is null)<>(p_before_id is null) then raise exception 'INVALID_INPUT'; end if;
  if not exists(select from public.affiliates a where a.user_id=p_user) then return; end if;
  return query with targets(operation,target) as (
    select unnest(array['affiliate_create','affiliate_decide','affiliate_set']),p_user::text
    union all select 'affiliate_adjust',j.id::text from public.affiliate_adjustments j where j.affiliate_user_id=p_user
    union all select 'affiliate_payout_decide',p.id::text from public.affiliate_payouts p where p.affiliate_user_id=p_user
    union all select 'affiliate_commission_release',c.id::text from public.affiliate_commissions c where c.affiliate_user_id=p_user
    union all select 'affiliate_recompute',c.payment_id::text from public.affiliate_commissions c where c.affiliate_user_id=p_user
  ), events as (
    select l.id,l.created_at,l.action,l.user_id,l.target_id,l.reason
      from targets t join public.admin_audit_log l on (l.action,l.target_id)=(t.operation,t.target)
    union all
    select l.id,l.created_at,l.action,l.user_id,l.target_id,l.reason from public.admin_audit_log l
      where l.action='affiliate_rebind' and array[l.target_id,split_part(l.reason,' ',1),split_part(l.reason,' ',3)] @> array[p_user::text]
  )
  select e.id,e.created_at,e.action,e.user_id,e.target_id,e.reason from events e
    where p_before_at is null or (e.created_at,e.id)<(p_before_at,p_before_id)
    order by e.created_at desc,e.id desc limit 31;
end;
$$;


ALTER FUNCTION "public"."admin_affiliate_dossier_log"("p_actor" "uuid", "p_user" "uuid", "p_before_at" timestamp with time zone, "p_before_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_affiliate_find_user"("p_actor" "uuid", "p_query" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare v_user uuid; v_answer jsonb;
begin
  perform public._affiliate_require_admin(p_actor);
  if p_query ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then v_user:=p_query::uuid;
  else select id into v_user from auth.users where email=lower(trim(p_query)) and is_sso_user=false; end if;
  select jsonb_build_object('user_id',u.id,'email',u.email,'referred_by',pr.referred_by,'referred_at',pr.referred_at,
    'referred_source',pr.referred_source,'slug',a.slug) into v_answer from auth.users u join public.profiles pr on pr.id=u.id
    left join public.affiliates a on a.user_id=pr.referred_by where u.id=v_user;
  return v_answer;
end;
$_$;


ALTER FUNCTION "public"."admin_affiliate_find_user"("p_actor" "uuid", "p_query" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_affiliate_overview"("p_actor" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_answer jsonb;
begin
  perform public._affiliate_require_admin(p_actor);
  select jsonb_build_object('revenue',r.revenue,'pending',c.pending,'confirmed',c.confirmed,'paid',p.paid,
    'applications',(select count(*) from public.affiliates where status='pending' and application->>'source' is distinct from 'admin_invite'),
    'payout_count',p.due_count,'payout_total',p.due_total,'flagged',c.flagged,
    'errors',(select count(*) from public.affiliate_recompute_errors where resolved_at is null)) into v_answer
  from (select coalesce(sum(div((pay.amount_total-pay.amount_tax)::numeric*(pay.amount_total-pay.amount_refunded),nullif(pay.amount_total,0))),0) revenue
    from public.affiliate_commissions ac join public.payments pay on pay.id=ac.payment_id
    where ac.level=1 and pay.currency='usd' and not exists(select from public.payment_disputes d where d.payment_id=pay.id
      and d.closed_status not in ('won','warning_closed'))) r
  cross join (select coalesce(sum(amount) filter(where status='pending'),0) pending,
    coalesce(sum(amount) filter(where status='confirmed'),0) confirmed,count(*) filter(where cardinality(flags)>0) flagged
    from public.affiliate_commissions) c
  cross join (select coalesce(sum(coalesce(payout.paid_amount,payout.amount)) filter(where status='paid'),0) paid,
    count(*) filter(where status='due' and period=date_trunc('month',now() at time zone 'UTC')::date) due_count,
    coalesce(sum(coalesce(public.affiliate_payout_payable(payout),payout.amount)) filter(where status='due' and period=date_trunc('month',now() at time zone 'UTC')::date),0) due_total
    from public.affiliate_payouts payout) p;
  return v_answer;
end;
$$;


ALTER FUNCTION "public"."admin_affiliate_overview"("p_actor" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_affiliate_payout_decide"("p_actor" "uuid", "p_input" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v public.affiliate_payouts; v_status text:=p_input->>'status'; v_note text:=nullif(trim(p_input->>'note'),'');
  v_mode text:=p_input->>'void_mode'; v_method text:=nullif(trim(p_input->>'method'),'');
  v_ref text:=nullif(trim(p_input->>'paid_reference'),''); v_time timestamptz:=(p_input->>'paid_at')::timestamptz;
  v_expected bigint:=(p_input->>'expected_amount')::bigint; v_actual bigint;
begin
  perform public._affiliate_require_admin(p_actor);
  perform pg_advisory_xact_lock(hashtextextended('affiliate_settlement',0));
  select * into strict v from public.affiliate_payouts where id=(p_input->>'payout_id')::bigint for update;
  if (v.status,v_status) not in (('due','held'),('due','paid'),('held','due'),('held','void'))
    or v_status is null then raise exception 'AFFILIATE_INVALID_PAYOUT_TRANSITION'; end if;
  if (v_status in ('held','void') and v_note is null) or (v_status='void' and (v_mode is null or v_mode not in ('return','forfeit')))
    or (v_status='paid' and (v_method is null or v_time is null or coalesce(v_ref,v_note) is null)) then raise exception 'INVALID_INPUT'; end if;
  if v_status='paid' or (v_status='void' and v_mode='forfeit') then
    if v.legacy_review_required then raise exception 'AFFILIATE_PAYOUT_LEGACY_REVIEW'; end if;
    -- Refunds/retries lock payment then commission. The quote now depends on
    -- the entire account, even if the order itself is backed by adjustments.
    perform pay.id from public.payments pay join public.affiliate_commissions c on c.payment_id=pay.id
      where c.affiliate_user_id=v.affiliate_user_id order by pay.id for update of pay;
    -- An adjustment insert takes a foreign-key key-share lock on this owner.
    perform a.user_id from public.affiliates a where a.user_id=v.affiliate_user_id for update;
    perform c.id from public.affiliate_commissions c where c.affiliate_user_id=v.affiliate_user_id
      order by c.payment_id,c.level for update;
    if exists(select from public.affiliate_commissions c join public.affiliate_recompute_errors e
      on e.payment_id=c.payment_id and e.resolved_at is null where c.affiliate_user_id=v.affiliate_user_id)
      then raise exception 'AFFILIATE_PAYOUT_RECOMPUTE_PENDING'; end if;
    if v_status='paid' then
      v_actual:=public.affiliate_payout_payable(v);
      if (v_expected is not null or v_actual<>v.amount) and v_expected is distinct from v_actual then
        raise exception 'AFFILIATE_PAYOUT_AMOUNT_CHANGED'; end if;
      with backed as (
        select i.commission_id,i.prior_amount,greatest(0,least(i.issue_amount,
          case when c.status='confirmed' and c.payout_retained is null then c.amount else 0 end)-i.prior_amount) cents
          from public.affiliate_payout_items i join public.affiliate_commissions c on c.id=i.commission_id where i.payout_id=v.id
      ), ranked as (
        select *,sum(cents) over(order by commission_id,prior_amount rows unbounded preceding)-cents before_slice from backed
      )
      update public.affiliate_payout_items i set settled_amount=r.prior_amount+greatest(0,least(r.cents,v_actual-r.before_slice))
        from ranked r where i.payout_id=v.id and (i.commission_id,i.prior_amount)=(r.commission_id,r.prior_amount);
    else
      perform public._affiliate_payout_forfeit(v,v_note);
    end if;
  end if;
  update public.affiliate_payouts set status=v_status,paid_amount=v_actual,decided_by=p_actor,note=v_note,
    paid_at=case when v_status='paid' then v_time end,paid_method=case when v_status='paid' then v_method end,
    paid_reference=case when v_status='paid' then v_ref end where id=v.id;
  perform public._affiliate_audit(p_actor,'payout_decide',v.id::text,
    concat_ws(': ',v.status||' -> '||v_status,case when v_status='void' then v_mode end,v_actual::text,v_note));
end;
$$;


ALTER FUNCTION "public"."admin_affiliate_payout_decide"("p_actor" "uuid", "p_input" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_affiliate_rebind"("p_actor" "uuid", "p_input" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_user uuid:=(p_input->>'user_id')::uuid; v_owner uuid:=(p_input->>'affiliate_user_id')::uuid;
  v_reason text:=nullif(trim(p_input->>'reason'),''); v_old uuid;
begin
  perform public._affiliate_require_admin(p_actor);
  if v_reason is null or not(p_input ? 'affiliate_user_id') or v_user=v_owner then raise exception 'INVALID_INPUT'; end if;
  select referred_by into strict v_old from public.profiles where id=v_user for update;
  update public.profiles set referred_by=v_owner,referred_source=case when v_owner is not null then 'admin' end,
    referred_at=case when v_owner is not null then now() end where id=v_user;
  perform public._affiliate_audit(p_actor,'rebind',v_user::text,
    concat(coalesce(v_old::text,'∅'),' → ',coalesce(v_owner::text,'∅'),' ',v_reason));
end;
$$;


