CREATE TABLE IF NOT EXISTS "public"."template_categories" (
    "key" "text" NOT NULL,
    "name_en" "text" NOT NULL,
    "name_zh" "text" NOT NULL,
    "intro_en" "text",
    "intro_zh" "text",
    "card_style" "text" DEFAULT 'pair'::"text" NOT NULL,
    "sort_order" integer DEFAULT 0 NOT NULL,
    "is_system" boolean DEFAULT false NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "parent_id" "text",
    "kind" "text" DEFAULT 'template'::"text" NOT NULL,
    "level" smallint DEFAULT 1 NOT NULL,
    "slug" "text" DEFAULT ''::"text" NOT NULL,
    "is_visible" boolean DEFAULT true NOT NULL,
    "seo_title_en" "text",
    "seo_title_zh" "text",
    "seo_description_en" "text",
    "seo_description_zh" "text",
    "name_en_lookup" "text" GENERATED ALWAYS AS ((("kind" || ':'::"text") || "lower"("name_en"))) STORED,
    "name_zh_lookup" "text" GENERATED ALWAYS AS ((("kind" || ':'::"text") || "name_zh")) STORED,
    CONSTRAINT "template_categories_card_style_check" CHECK (("card_style" = ANY (ARRAY['pair'::"text", 'compare'::"text"]))),
    CONSTRAINT "template_categories_intro_en_check" CHECK ((("intro_en" IS NULL) OR (("char_length"("intro_en") >= 1) AND ("char_length"("intro_en") <= 200)))),
    CONSTRAINT "template_categories_intro_zh_check" CHECK ((("intro_zh" IS NULL) OR (("char_length"("intro_zh") >= 1) AND ("char_length"("intro_zh") <= 200)))),
    CONSTRAINT "template_categories_key_check" CHECK ((("key" ~ '^[a-z0-9]+(-[a-z0-9]+)*$'::"text") AND ("char_length"("key") <= 40))),
    CONSTRAINT "template_categories_kind_check" CHECK (("kind" = ANY (ARRAY['template'::"text", 'reference'::"text"]))),
    CONSTRAINT "template_categories_level_check" CHECK ((("level" >= 1) AND ("level" <= 3))),
    CONSTRAINT "template_categories_name_en_check" CHECK ((("char_length"("name_en") >= 1) AND ("char_length"("name_en") <= 32) AND ("name_en" = "btrim"("name_en")))),
    CONSTRAINT "template_categories_name_zh_check" CHECK ((("char_length"("name_zh") >= 1) AND ("char_length"("name_zh") <= 12) AND ("name_zh" = "btrim"("name_zh")))),
    CONSTRAINT "template_category_slug_format" CHECK (("slug" ~ '^[a-z0-9]+(-[a-z0-9]+)*$'::"text"))
);


ALTER TABLE "public"."template_categories" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_assigned_template_count"("public"."template_categories") RETURNS bigint
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $_$
  select case when $1.parent_id is null then
    (select count(*) from public.templates t where t.category_key=$1.key and t.subcategory_key is null)
  else
    (select count(*) from public.templates t where t.subcategory_key=$1.key)
  end
$_$;


ALTER FUNCTION "public"."admin_assigned_template_count"("public"."template_categories") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_ban_user"("p_user_id" "uuid", "p_reason" "text") RETURNS timestamp with time zone
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_banned_at timestamptz;
begin
  if p_reason is null or length(p_reason) = 0 then
    raise exception 'INVALID_INPUT' using detail = 'reason is required';
  end if;

  -- Keep the first ban time when banning twice.
  update public.profiles
     set banned_at = coalesce(banned_at, now())
   where id = p_user_id
  returning banned_at into v_banned_at;
  if not found then
    raise exception 'PROFILE_NOT_FOUND';
  end if;

  update public.partner_links
     set revoked_at = now(), link_code = null, code_expires_at = null
   where user_id = p_user_id
     and revoked_at is null;

  insert into public.admin_audit_log (action, user_id, reason) values ('ban_user', p_user_id, p_reason);
  return v_banned_at;
end;
$$;


ALTER FUNCTION "public"."admin_ban_user"("p_user_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_batch_adjust_credits"("p_actor" "uuid", "p_user_ids" "uuid"[], "p_pool" "text", "p_amount" integer, "p_reason" "text", "p_batch_key" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_reason text := btrim(coalesce(p_reason, ''));
  v_ids uuid[];
  v_bad uuid[];
  v_id uuid;
  v_applied integer := 0;
begin
  if p_actor is null or not exists (select 1 from public.profiles where id = p_actor and role = 'admin') then
    raise exception 'NOT_ADMIN';
  end if;
  if p_pool is null or p_pool not in ('free', 'paid') then
    raise exception 'INVALID_INPUT' using detail = 'pool must be free or paid';
  end if;
  if p_amount is null or p_amount = 0 or abs(p_amount) > 100000 then
    raise exception 'INVALID_INPUT' using detail = 'amount must be a non-zero integer up to 100000';
  end if;
  if length(v_reason) = 0 or length(v_reason) > 500 then
    raise exception 'INVALID_INPUT' using detail = 'reason is required, at most 500 characters';
  end if;
  if p_batch_key is null or length(p_batch_key) = 0 or length(p_batch_key) > 64 then
    raise exception 'INVALID_INPUT' using detail = 'batch key is required';
  end if;
  if p_user_ids is null or cardinality(p_user_ids) = 0 or cardinality(p_user_ids) > 50
     or array_position(p_user_ids, null) is not null then
    raise exception 'INVALID_INPUT' using detail = 'between 1 and 50 users';
  end if;

  select array_agg(distinct i order by i) into v_ids from unnest(p_user_ids) as i;
  if cardinality(v_ids) <> cardinality(p_user_ids) then
    raise exception 'INVALID_INPUT' using detail = 'a user is listed twice';
  end if;

  perform 1 from public.profiles where id = any(v_ids) order by id for update;

  select array_agg(i order by i) into v_bad
    from unnest(v_ids) as i
   where not exists (select 1 from public.profiles p where p.id = i);
  if v_bad is not null then
    raise exception 'PROFILE_NOT_FOUND' using detail = array_to_string(v_bad, ',');
  end if;

  if exists (
    select 1
      from unnest(v_ids) as i
      join public.credit_ledger l on l.idempotency_key = 'admin_batch:' || p_batch_key || ':' || i::text
     where l.user_id <> i or l.kind <> 'admin_adjust' or l.pool <> p_pool or l.delta <> p_amount
  ) then
    raise exception 'IDEMPOTENCY_CONFLICT';
  end if;

  -- Users this batch already adjusted are skipped, so a resubmit never trips over the balance
  -- its own first run produced.
  select array_agg(p.id order by p.id) into v_bad
    from public.profiles p
   where p.id = any(v_ids)
     and not exists (
       select 1 from public.credit_ledger l
        where l.idempotency_key = 'admin_batch:' || p_batch_key || ':' || p.id::text
     )
     and (case when p_pool = 'paid' then p.credits else p.free_credits end) + p_amount < 0;
  if v_bad is not null then
    raise exception 'CREDITS_INSUFFICIENT' using detail = array_to_string(v_bad, ',');
  end if;

  foreach v_id in array v_ids loop
    if (public._apply_credit_change(
          v_id, p_pool, 'admin_adjust', p_amount, v_reason || ' · 操作人 ' || p_actor::text,
          'admin_batch:' || p_batch_key || ':' || v_id::text
        )).applied then
      v_applied := v_applied + 1;
    end if;
  end loop;

  return jsonb_build_object('applied', v_applied, 'repeated', cardinality(v_ids) - v_applied);
end;
$$;


ALTER FUNCTION "public"."admin_batch_adjust_credits"("p_actor" "uuid", "p_user_ids" "uuid"[], "p_pool" "text", "p_amount" integer, "p_reason" "text", "p_batch_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_batch_set_banned"("p_actor" "uuid", "p_user_ids" "uuid"[], "p_banned" boolean, "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_reason text := btrim(coalesce(p_reason, ''));
  v_ids uuid[];
  v_bad uuid[];
  v_id uuid;
  v_changed integer := 0;
begin
  if p_actor is null or not exists (select 1 from public.profiles where id = p_actor and role = 'admin') then
    raise exception 'NOT_ADMIN';
  end if;
  if p_banned is null then
    raise exception 'INVALID_INPUT' using detail = 'banned must be true or false';
  end if;
  if length(v_reason) = 0 or length(v_reason) > 500 then
    raise exception 'INVALID_INPUT' using detail = 'reason is required, at most 500 characters';
  end if;
  if p_user_ids is null or cardinality(p_user_ids) = 0 or cardinality(p_user_ids) > 50
     or array_position(p_user_ids, null) is not null then
    raise exception 'INVALID_INPUT' using detail = 'between 1 and 50 users';
  end if;

  select array_agg(distinct i order by i) into v_ids from unnest(p_user_ids) as i;
  if cardinality(v_ids) <> cardinality(p_user_ids) then
    raise exception 'INVALID_INPUT' using detail = 'a user is listed twice';
  end if;

  perform 1 from public.profiles where id = any(v_ids) order by id for update;

  select array_agg(i order by i) into v_bad
    from unnest(v_ids) as i
   where not exists (select 1 from public.profiles p where p.id = i);
  if v_bad is not null then
    raise exception 'PROFILE_NOT_FOUND' using detail = array_to_string(v_bad, ',');
  end if;

  if p_banned then
    select array_agg(p.id order by p.id) into v_bad
      from public.profiles p
     where p.id = any(v_ids) and (p.role = 'admin' or p.id = p_actor);
    if v_bad is not null then
      raise exception 'PROTECTED_USER' using detail = array_to_string(v_bad, ',');
    end if;
  end if;

  for v_id in
    select p.id from public.profiles p
     where p.id = any(v_ids) and (p.banned_at is null) = p_banned
     order by p.id
  loop
    if p_banned then
      perform public.admin_ban_user(v_id, v_reason || ' · 操作人 ' || p_actor::text);
    else
      perform public.admin_unban_user(v_id, v_reason || ' · 操作人 ' || p_actor::text);
    end if;
    v_changed := v_changed + 1;
  end loop;

  return jsonb_build_object('changed', v_changed, 'unchanged', cardinality(v_ids) - v_changed);
end;
$$;


ALTER FUNCTION "public"."admin_batch_set_banned"("p_actor" "uuid", "p_user_ids" "uuid"[], "p_banned" boolean, "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_begin_prompt_lab_matrix"("p_actor" "uuid", "p_session_id" "uuid", "p_batch_id" "uuid", "p_photos" "uuid"[], "p_versions" "uuid"[], "p_model" "text", "p_resolution" "text", "p_quality" "text", "p_use_style_reference" boolean, "p_estimate_usd" numeric) RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare cells integer; quoted numeric:=round(p_estimate_usd,6); result jsonb; photo_count integer;
begin
  perform admin.require_reference_admin(p_actor);
  cells:=cardinality(p_photos)*cardinality(p_versions);
  if cells is null or cells not between 1 and 12 or p_batch_id is null or p_model is null or length(btrim(p_model)) not between 1 and 300
    or p_resolution is null or p_resolution not in ('1k','2k','3k') or p_quality is null or p_quality not in ('medium','high')
    or p_use_style_reference is null or quoted is null or quoted<=0 or quoted>=10000
    or cardinality(p_photos)<>(select count(distinct id) from unnest(p_photos) id)
    or cardinality(p_versions)<>(select count(distinct id) from unnest(p_versions) id) then raise exception 'INVALID_INPUT'; end if;
  perform admin.lock_prompt_lab(p_session_id);
  perform pg_advisory_xact_lock(hashtextextended(p_batch_id::text,101));
  if exists(select from public.prompt_lab_runs where batch_id=p_batch_id) then
    if cells<>(select count(*) from public.prompt_lab_runs where batch_id=p_batch_id) or exists(
      select from public.prompt_lab_runs r where batch_id=p_batch_id and (
        session_id<>p_session_id or created_by is distinct from p_actor or model<>p_model or resolution<>p_resolution or quality<>p_quality
        or use_style_reference<>p_use_style_reference or estimate_usd<>quoted or photo_id<>p_photos[1+(ordinal-1)/cardinality(p_versions)]
        or version_id<>p_versions[1+(ordinal-1)%cardinality(p_versions)]))
      then raise exception 'IDEMPOTENCY_CONFLICT'; end if;
  else
    if cardinality(p_versions)<>(select count(*) from public.prompt_lab_versions where session_id=p_session_id and id=any(p_versions))
      then raise exception 'PROMPT_VERSION_NOT_FOUND'; end if;
    -- T85 takes the budget lock before inserting a run that references its photo.
    -- Use the same order when T85 and the lab try the same photo concurrently.
    perform admin.reserve_prompt_lab_budget(quoted*cells);
    perform 1 from public.admin_test_photos where id=any(p_photos) order by id for update;
    get diagnostics photo_count=row_count;
    if photo_count<>cardinality(p_photos) then raise exception 'TEST_PHOTO_NOT_FOUND'; end if;
    with batch as (
      insert into public.prompt_lab_runs(session_id,batch_id,ordinal,photo_id,version_id,model,resolution,quality,
        use_style_reference,estimate_usd,created_by)
      select p_session_id,p_batch_id,(ph.n-1)*cardinality(p_versions)+v.n,ph.id,v.id,p_model,p_resolution,p_quality,
        p_use_style_reference,quoted,p_actor from unnest(p_photos) with ordinality ph(id,n)
          cross join unnest(p_versions) with ordinality v(id,n)
      returning id
    )
    insert into public.admin_test_spend(run_id,estimate_usd,provider)
      select id,quoted,p_model from batch;
    update public.admin_test_photos set last_used_at=now() where id=any(p_photos);
    update public.prompt_lab_sessions set updated_at=now() where id=p_session_id;
  end if;
  select jsonb_agg(jsonb_build_object('id',id,'photo_id',photo_id,'version_id',version_id,'status',status) order by ordinal)
    into result from public.prompt_lab_runs where batch_id=p_batch_id;
  return result;
end $$;


ALTER FUNCTION "public"."admin_begin_prompt_lab_matrix"("p_actor" "uuid", "p_session_id" "uuid", "p_batch_id" "uuid", "p_photos" "uuid"[], "p_versions" "uuid"[], "p_model" "text", "p_resolution" "text", "p_quality" "text", "p_use_style_reference" boolean, "p_estimate_usd" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_begin_prompt_lab_reverse"("p_actor" "uuid", "p_session_id" "uuid", "p_request_id" "uuid", "p_model" "text", "p_estimate_usd" numeric, "p_setting_model" "text", "p_instruction" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare req public.prompt_lab_reverse_requests; settings jsonb; quoted numeric:=round(p_estimate_usd,6);
begin
  perform admin.require_reference_admin(p_actor);
  perform admin.lock_prompt_lab(p_session_id);
  perform pg_advisory_xact_lock(hashtextextended(p_request_id::text,101));
  select * into req from public.prompt_lab_reverse_requests where id=p_request_id;
  if found then
    if req.session_id<>p_session_id or req.model is distinct from p_model or req.created_by is distinct from p_actor then
      raise exception 'IDEMPOTENCY_CONFLICT';
    end if;
    return jsonb_build_object('claimed',false,'status',req.status,'version_id',req.version_id);
  end if;
  select value into settings from public.system_settings where key='prompt_lab_reverse' for share;
  if settings->>'model' is distinct from p_setting_model or settings->>'instruction' is distinct from p_instruction
    or nullif(btrim(p_setting_model),'') is null or nullif(btrim(p_instruction),'') is null
    or p_model is null or length(btrim(p_model)) not between 1 and 300 then raise exception 'PROMPT_LAB_SETTINGS_CHANGED'; end if;
  perform admin.reserve_prompt_lab_budget(quoted);
  insert into public.prompt_lab_reverse_requests(id,session_id,model,created_by) values(p_request_id,p_session_id,p_model,p_actor);
  insert into public.admin_test_spend(run_id,provider,estimate_usd,counted_usd,has_openrouter)
    values(p_request_id,p_model,quoted,quoted,exists(select from public.ai_providers
      where id::text=p_setting_model and rtrim(base_url,'/')='https://openrouter.ai/api/v1'));
  return jsonb_build_object('claimed',true,'status','running','version_id',null);
end $$;


ALTER FUNCTION "public"."admin_begin_prompt_lab_reverse"("p_actor" "uuid", "p_session_id" "uuid", "p_request_id" "uuid", "p_model" "text", "p_estimate_usd" numeric, "p_setting_model" "text", "p_instruction" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_begin_test_run"("p_actor" "uuid", "p_run_id" "uuid", "p_template_id" "text", "p_kind" "text", "p_parent_id" "uuid", "p_photo_id" "uuid", "p_batch_id" "uuid", "p_resolution" "text", "p_inputs" "jsonb", "p_prompt_version" integer, "p_provider" "text", "p_estimate_usd" numeric) RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  v_existing public.admin_test_runs;
  v_parent public.admin_test_runs;
  v_photo uuid := p_photo_id;
  v_status jsonb;
  v_row public.admin_test_runs;
begin
  if p_actor is null or p_run_id is null or p_batch_id is null then
    raise exception 'INVALID_INPUT' using detail = 'actor, run id and batch id are required';
  end if;
  if not exists (select 1 from public.profiles p where p.id = p_actor and p.role = 'admin') then
    raise exception 'NOT_ADMIN';
  end if;
  if p_kind is null or p_kind not in ('generate', 'edit', 'translate') then
    raise exception 'INVALID_INPUT' using detail = 'kind must be generate, edit or translate';
  end if;
  if p_estimate_usd is null or p_estimate_usd < 0 then
    raise exception 'INVALID_INPUT' using detail = 'estimate is required';
  end if;

  select * into v_existing from public.admin_test_runs r where r.id = p_run_id;
  if found then
    if v_existing.template_id <> p_template_id then
      raise exception 'IDEMPOTENCY_CONFLICT';
    end if;
    return to_jsonb(v_existing);
  end if;

  if not exists (select 1 from public.templates t where t.id = p_template_id) then
    raise exception 'TEMPLATE_NOT_FOUND';
  end if;

  if p_kind = 'edit' then
    select * into v_parent from public.admin_test_runs r
     where r.id = p_parent_id and r.template_id = p_template_id and r.status = 'succeeded' and r.output_key is not null;
    if not found then
      raise exception 'TEST_RUN_NOT_FOUND';
    end if;
    v_photo := v_parent.photo_id;
  elsif p_parent_id is not null then
    raise exception 'INVALID_INPUT' using detail = 'only an edit has a parent';
  elsif p_kind = 'translate' and v_photo is not null then
    raise exception 'INVALID_INPUT' using detail = 'a cover translation starts from the cover, not a test photo';
  elsif v_photo is not null and not exists (select 1 from public.admin_test_photos ph where ph.id = v_photo) then
    raise exception 'TEST_PHOTO_NOT_FOUND';
  end if;

  -- One budget decision at a time; held until commit, so the next request sees this row.
  perform pg_advisory_xact_lock(hashtext('shotviva.admin_test_budget'));
  v_status := public.admin_test_budget_status();
  if (v_status ->> 'spent_usd')::numeric + p_estimate_usd > (v_status ->> 'budget_usd')::numeric then
    raise exception 'TEST_BUDGET_EXCEEDED';
  end if;

  insert into public.admin_test_runs (
    id, template_id, kind, parent_id, photo_id, batch_id, resolution, inputs, prompt_version, provider, estimate_usd, created_by
  ) values (
    p_run_id, p_template_id, p_kind, p_parent_id, v_photo, p_batch_id, p_resolution, coalesce(p_inputs, '{}'::jsonb),
    p_prompt_version, p_provider, p_estimate_usd, p_actor
  )
  on conflict (id) do nothing
  returning * into v_row;

  if v_row.id is null then
    -- A concurrent request with the same id won; hand back its row.
    select * into v_row from public.admin_test_runs r where r.id = p_run_id;
    return to_jsonb(v_row);
  end if;

  insert into public.admin_test_spend (run_id, template_id, estimate_usd)
  values (p_run_id, p_template_id, p_estimate_usd);

  if v_photo is not null then
    update public.admin_test_photos set last_used_at = now() where id = v_photo;
  end if;
  return to_jsonb(v_row);
end;
$$;


ALTER FUNCTION "public"."admin_begin_test_run"("p_actor" "uuid", "p_run_id" "uuid", "p_template_id" "text", "p_kind" "text", "p_parent_id" "uuid", "p_photo_id" "uuid", "p_batch_id" "uuid", "p_resolution" "text", "p_inputs" "jsonb", "p_prompt_version" integer, "p_provider" "text", "p_estimate_usd" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_bulk_assign_templates"("p_ids" "text"[], "p_patch" "jsonb", "p_floor" "jsonb", "p_actor" "uuid", "p_locales" "text"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  v_node text := p_patch->>'category_key';
  v_root text;
  v_result jsonb;
begin
  if not exists(select from public.profiles where id=p_actor and role='admin' and banned_at is null) then
    raise exception 'NOT_ADMIN';
  end if;
  perform pg_advisory_xact_lock_shared(hashtextextended('shotviva.category_tree',0));
  select p.root_key into v_root from public.template_category_paths p
    join public.template_categories c on c.key=p.key where p.key=v_node and not c.is_system;
  if not found then raise exception 'CATEGORY_NOT_FOUND'; end if;
  v_result:=public.admin_bulk_edit_templates(p_ids,jsonb_set(p_patch,'{category_key}',to_jsonb(v_root)),p_floor,p_actor,p_locales);
  if v_result->'failures'='[]'::jsonb then
    update public.templates set subcategory_key=nullif(v_node,v_root)
      where id=any(p_ids) and subcategory_key is distinct from nullif(v_node,v_root);
  end if;
  return v_result;
end $$;


ALTER FUNCTION "public"."admin_bulk_assign_templates"("p_ids" "text"[], "p_patch" "jsonb", "p_floor" "jsonb", "p_actor" "uuid", "p_locales" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_bulk_edit_templates"("p_ids" "text"[], "p_patch" "jsonb", "p_floor" "jsonb", "p_actor" "uuid") RETURNS "jsonb"
    LANGUAGE "sql"
    SET "search_path" TO ''
    AS $$
  select public.admin_bulk_edit_templates(p_ids,p_patch,p_floor,p_actor,'{}'::text[])
$$;


ALTER FUNCTION "public"."admin_bulk_edit_templates"("p_ids" "text"[], "p_patch" "jsonb", "p_floor" "jsonb", "p_actor" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_bulk_edit_templates"("p_ids" "text"[], "p_patch" "jsonb", "p_floor" "jsonb", "p_actor" "uuid", "p_locales" "text"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $_$
declare
  v_ids text[] := array(select distinct u.id from unnest(coalesce(p_ids, '{}')) as u(id));
  v_patch jsonb := coalesce(p_patch, '{}');
  v_cost jsonb := coalesce(p_patch -> 'credits_cost', '{}');
  v_visible text[];
  change_model boolean := p_patch ? 'provider_id';
  target uuid := (p_patch->>'provider_id')::uuid;
  v_category text := p_patch ->> 'category_key';
  v_failures jsonb;
  catalog_minimums jsonb:=case when admin.is_template_catalog_v2() then admin.template_catalog_minimums() else '{}' end;
  v_changed integer;
begin
  if p_actor is null then
    raise exception 'INVALID_INPUT' using detail = 'actor is required';
  end if;
  if not exists (select 1 from public.profiles p where p.id = p_actor and p.role = 'admin' and p.banned_at is null) then
    raise exception 'NOT_ADMIN';
  end if;
  if cardinality(v_ids) = 0 or cardinality(v_ids) > 200 then
    raise exception 'INVALID_INPUT' using detail = 'between 1 and 200 templates';
  end if;
  if jsonb_typeof(v_patch) <> 'object' or v_patch = '{}' or v_patch - 'credits_cost' - 'visible_in' - 'quality' - 'category_key' - 'provider_id' <> '{}' then
    raise exception 'INVALID_INPUT' using detail = 'patch must name credits_cost, visible_in, quality or category_key';
  end if;
  if v_patch ? 'quality' and (v_patch ->> 'quality') is distinct from 'high' and (v_patch ->> 'quality') is distinct from 'medium' then
    raise exception 'INVALID_INPUT' using detail = 'quality must be high or medium';
  end if;
  if jsonb_typeof(v_cost) <> 'object' then
    raise exception 'INVALID_INPUT' using detail = 'credits_cost must be an object';
  end if;
  if exists (
    select 1 from jsonb_each(v_cost) as e(key, value)
    where e.key not in ('1k', '2k', '3k') or jsonb_typeof(e.value) <> 'number' or e.value::text !~ '^[1-9][0-9]{0,2}$'
  ) then
    raise exception 'INVALID_INPUT' using detail = 'credits_cost tiers must be whole numbers 1..999';
  end if;
  if v_patch ? 'visible_in' then
    if jsonb_typeof(v_patch -> 'visible_in') <> 'array' then
      raise exception 'INVALID_INPUT' using detail = 'visible_in must be an array';
    end if;
    v_visible := array(select distinct x from jsonb_array_elements_text(v_patch -> 'visible_in') as v(x) order by x desc);
    if cardinality(v_visible) = 0 or not (v_visible <@ array['web', 'partner']) then
      raise exception 'INVALID_INPUT' using detail = 'visible_in must be web, partner or both';
    end if;
  end if;
  if v_patch ? 'category_key' then
    -- Held until commit, so the category cannot be deleted under this write.
    perform 1 from public.template_categories c where c.key = v_category and not c.is_system for share;
    if not found then
      raise exception 'CATEGORY_NOT_FOUND' using detail = 'category_key must name a category that is not a system one';
    end if;
  end if;
  if p_floor is null or exists (
    select 1 from unnest(array['high', 'medium']) as q(quality), unnest(array['1k', '2k', '3k']) as r(res)
    where jsonb_typeof(p_floor -> q.quality -> r.res) is distinct from 'number'
  ) then
    raise exception 'INVALID_INPUT' using detail = 'floor table is incomplete';
  end if;

  -- The rows are checked and written under one lock, so no other save slips in between.
  perform 1 from public.templates t where t.id = any (v_ids) order by t.id for update;
  if change_model then
    perform 1 from public.template_prompts where template_id=any(v_ids) order by template_id for update;
    perform 1 from public.ai_providers where module='image' and (id=target or (target is null and is_active)) for share;
    if target is not null and not found then raise exception 'MODEL_CHANGED'; end if;
  end if;

  if admin.is_template_catalog_v2() and (p_floor->>'version') is distinct from 'v2' then
    raise exception 'MODEL_CHANGED' using detail='请刷新模板报价后再保存';
  end if;
  -- A supplier may have switched since the admin action read costs. Re-read the effective
  -- binding under the template lock; a missing/different model requires a fresh preview.
  if p_floor ? 'models' and exists (
    select 1 from public.templates t
      left join public.template_prompts tp on tp.template_id = t.id
      left join public.ai_providers active on active.is_active and active.module = 'image'
      left join public.ai_providers p on p.id = coalesce(case when change_model then target else tp.provider_id end, active.id)
     where t.id = any(v_ids) and (
       not (p_floor->'providers' ? coalesce(p.id::text, 'env'))
       or (p.id is not null and p.model is distinct from (p_floor->'models'->>p.id::text)))
  ) then raise exception 'MODEL_CHANGED'; end if;

  with planned as (
    select a.id, t.id is not null as found, coalesce(t.name, a.id) as name, t.is_active,
           t.description, t.cover_before_url, t.cover_after_url, t.cover_locales, t.visible_in as old_visible,
           coalesce(v_patch ->> 'quality', t.quality) as quality,
           coalesce(p_floor -> 'providers' -> coalesce((case when change_model then target else tp.provider_id end)::text, active.id::text, 'env'), p_floor) as floor,
           admin.template_approved_prices(coalesce(case when change_model then target else tp.provider_id end,active.id))->t.id as approved,
           catalog_minimums->t.id as tariff,
           coalesce(sale.unpriced_resolutions, array(select tier from unnest(array['1k','2k','3k']) tier
             where tier<>all(admin.sale_route_resolutions(previous)))) as unpriced_resolutions,
           t.credits_cost || v_cost as credits_cost,
           coalesce(v_visible, t.visible_in) as visible_in,
           a.id in ('edit', 'freeform') or coalesce(c.is_system, false) as is_builtin,
           case when change_model then admin.bulk_model_problem(t,tp,chosen,v_cost)
                when exists(select from jsonb_object_keys(v_cost) tier where not(tier=any(admin.sale_route_resolutions(chosen))))
                then '所选模型不支持所填积分档位' end model_problem
    from unnest(v_ids) as a(id)
    left join public.templates t on t.id = a.id
    left join public.template_categories c on c.key = t.category_key
    left join public.template_sale_approvals sale on sale.template_id = t.id
    left join public.template_prompts tp on tp.template_id = t.id
    left join public.ai_providers active on active.module = 'image' and active.is_active
    left join public.ai_providers previous on previous.id=coalesce(tp.provider_id,active.id)
    left join public.ai_providers chosen on chosen.id=coalesce(case when change_model then target else tp.provider_id end,active.id)
  ),
  failures as (
    select jsonb_build_object('id', p.id, 'name', p.name, 'reason', case when p.found then 'system' else 'not_found' end) as failure
    from planned p
    where not p.found or p.is_builtin
    union all
    select jsonb_build_object('id',p.id,'name',p.name,'reason','model','detail',p.model_problem)
    from planned p where p.found and not p.is_builtin and p.model_problem is not null
    union all
    select jsonb_build_object(
      'id', p.id, 'name', p.name, 'reason', 'below_floor', 'resolution', r.res,
      'floor', minimum.credits, 'given', (p.credits_cost ->> r.res)::integer
    )
    from planned p
    cross join unnest(array['1k', '2k', '3k']) as r(res)
    cross join lateral (select greatest((p.floor -> p.quality ->> r.res)::integer,
      case when p.tariff->>'quality'=p.quality then (p.tariff->'costs'->>r.res)::integer end) as credits) minimum
    where p.found and not p.is_builtin
      and (v_cost ? r.res or not (r.res=any(p.unpriced_resolutions)))
      and (p.credits_cost ->> r.res)::integer < minimum.credits
      and not coalesce(p.approved->>'quality'=p.quality and p.approved->'costs'->r.res=p.credits_cost->r.res,false)
    union all
    select jsonb_build_object('id', p.id, 'name', p.name, 'reason', 'web_incomplete')
    from planned p
    where p.found and not p.is_builtin and p.is_active
      and 'web' = any (p.visible_in) and not ('web' = any (p.old_visible))
      and (nullif(btrim(p.description), '') is null
           or not (nullif(btrim(p.cover_before_url), '') is not null or exists (
             select 1 from unnest(coalesce(p_locales, '{}')) as l(code)
             where nullif(btrim(p.cover_locales -> l.code ->> 'before'), '') is not null))
           or not (nullif(btrim(p.cover_after_url), '') is not null or exists (
             select 1 from unnest(coalesce(p_locales, '{}')) as l(code)
             where nullif(btrim(p.cover_locales -> l.code ->> 'after'), '') is not null)))
  )
  select coalesce(jsonb_agg(f.failure), '[]'::jsonb) into v_failures from failures f;

  if jsonb_array_length(v_failures) > 0 then
    return jsonb_build_object('failures', v_failures);
  end if;

  -- Capture missing legacy tier markers against the old route before changing a binding.
  if change_model or v_cost <> '{}'::jsonb then
    perform admin.set_template_unpriced_resolutions(t.id, null)
      from public.templates t where t.id=any(v_ids)
        and not exists(select from public.template_sale_approvals s where s.template_id=t.id);
  end if;

  update public.templates t
  set quality = coalesce(v_patch ->> 'quality', t.quality),
      credits_cost = t.credits_cost || v_cost,
      visible_in = coalesce(v_visible, t.visible_in),
      -- templates.category (the English name) follows through T75's trigger.
      category_key = coalesce(v_category, t.category_key),
      featured_rank = case when v_visible is not null and not ('web' = any (v_visible)) then null else t.featured_rank end
  where t.id = any (v_ids);
  get diagnostics v_changed = row_count;

  if change_model then
    update public.template_prompts set provider_id=target where template_id=any(v_ids) and provider_id is distinct from target;
  end if;

  -- A capability expansion or a model change alone never opens a previously unpriced tier.
  if v_cost <> '{}'::jsonb then
    perform admin.set_template_unpriced_resolutions(s.template_id,
      array(select tier from unnest(s.unpriced_resolutions) tier where not (v_cost ? tier)))
    from public.template_sale_approvals s where s.template_id=any(v_ids)
      and exists(select from unnest(s.unpriced_resolutions) tier where v_cost ? tier);
  end if;
  return jsonb_build_object('failures', '[]'::jsonb, 'changed', v_changed);
end;
$_$;


ALTER FUNCTION "public"."admin_bulk_edit_templates"("p_ids" "text"[], "p_patch" "jsonb", "p_floor" "jsonb", "p_actor" "uuid", "p_locales" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_bulk_reference_assets"("p_actor" "uuid", "p_ids" "uuid"[], "p_action" "text", "p_value" "jsonb" DEFAULT NULL::"jsonb") RETURNS integer
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare n integer; labels text[]; dest text;
begin
  perform admin.require_reference_admin(p_actor);
  if p_ids is null or cardinality(p_ids) not between 1 and 200
    or cardinality(p_ids)<>(select count(distinct id) from unnest(p_ids) id) then raise exception 'INVALID_INPUT'; end if;
  perform pg_advisory_xact_lock_shared(hashtextextended('shotviva.category_tree',0));
  perform 1 from public.reference_assets where id=any(p_ids) order by id for update;
  get diagnostics n=row_count;
  if n<>cardinality(p_ids) then raise exception 'REFERENCE_NOT_FOUND'; end if;
  case p_action
    when 'move' then
      dest:=p_value #>> '{}';
      update public.reference_assets set category_id=dest where id=any(p_ids);
    when 'add_tags','remove_tags' then
      if jsonb_typeof(p_value) is distinct from 'array' then raise exception 'INVALID_INPUT'; end if;
      labels:=array(select jsonb_array_elements_text(p_value));
      if cardinality(labels)=0 or not admin.reference_tags_valid(labels) then raise exception 'INVALID_INPUT'; end if;
      update public.reference_assets r set tags=case when p_action='add_tags' then
          array(select distinct t from unnest(r.tags||labels) t order by t)
        else array(select t from unnest(r.tags) t where not(t=any(labels))) end
      where id=any(p_ids);
    when 'archive' then
      update public.reference_assets set status='archived',archived_at=coalesce(archived_at,now()) where id=any(p_ids);
    when 'restore' then
      update public.reference_assets set status='active',archived_at=null where id=any(p_ids);
    when 'delete' then
      -- Reverse completion locks its session before its receipt; keep the same order.
      perform 1 from public.prompt_lab_sessions where asset_id=any(p_ids) order by id for update;
      perform public.admin_expire_prompt_lab_runs(p_actor);
      if exists(select from public.reference_assets where id=any(p_ids) and status<>'archived') then
        raise exception 'REFERENCE_NOT_ARCHIVED';
      end if;
      insert into public.reference_object_deletions(r2_key)
        select r2_key from public.reference_assets where id=any(p_ids);
      delete from public.reference_assets where id=any(p_ids);
    else raise exception 'INVALID_INPUT';
  end case;
  return n;
end $$;


ALTER FUNCTION "public"."admin_bulk_reference_assets"("p_actor" "uuid", "p_ids" "uuid"[], "p_action" "text", "p_value" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_catalog_account"("p_actor" "uuid", "p_id" "uuid") RETURNS "text"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  perform admin.catalog_require_actor(p_actor);
  return (select stripe_account from admin.catalog_publications where id=p_id);
end $$;


ALTER FUNCTION "public"."admin_catalog_account"("p_actor" "uuid", "p_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_catalog_archivable"("p_actor" "uuid", "p_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare r admin.catalog_publications;
begin
  perform admin.catalog_require_actor(p_actor);
  select * into strict r from admin.catalog_publications where id=p_id and status='published';
  if r.published_at+interval '24 hours'>now() then return '[]'; end if;
  return coalesce((select jsonb_agg(distinct old.price_id) from admin.catalog_stripe_prices old
    where old.product_id=r.product_id and old.revision=r.base_revision and old.archived_at is null
    and not exists(select from admin.catalog_stripe_prices s join admin.catalog_products p on p.product_id=s.product_id and p.published_revision=s.revision where s.price_id=old.price_id)
    and not exists(select from admin.catalog_checkout_attempts a where a.price_id=old.price_id and a.expires_at>now() and a.settled_at is null)
    ),'[]');
end $$;


ALTER FUNCTION "public"."admin_catalog_archivable"("p_actor" "uuid", "p_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_catalog_archive"("p_actor" "uuid", "p_id" "uuid", "p_price" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare r admin.catalog_publications;
begin
  perform admin.catalog_require_actor(p_actor);
  r:=admin.catalog_locked_request(p_id);
  if not (public.admin_catalog_archivable(p_actor,p_id) ? p_price) then raise exception 'CATALOG_STILL_IN_USE'; end if;
  update admin.catalog_stripe_prices set archived_at=now() where price_id=p_price;
  perform admin.catalog_audit(p_actor,'catalog_archive',r,jsonb_build_object('price',p_price));
end $$;


ALTER FUNCTION "public"."admin_catalog_archive"("p_actor" "uuid", "p_id" "uuid", "p_price" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_catalog_editor"("p_actor" "uuid", "p_product" "text", "p_before" timestamp with time zone DEFAULT 'infinity'::timestamp with time zone, "p_before_id" "uuid" DEFAULT 'ffffffff-ffff-ffff-ffff-ffffffffffff'::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare result jsonb;
begin
  perform admin.catalog_require_actor(p_actor);
  select jsonb_build_object('product_id',p.product_id,'tier',p.tier,'kind',p.kind,'current',to_jsonb(v),'draft',to_jsonb(d),
    'request',to_jsonb(r),'waffo',(select jsonb_build_object('one_time_id',w.one_time_id,'recurring_id',w.recurring_id)
      from admin.catalog_waffo_bindings w where w.product_id=p.product_id
        and w.revision=case when r.status='prepared' then r.revision else p.published_revision end),
    'budget',admin.catalog_budget(),'fees',admin.catalog_fee_components(p.kind),'discounts',
    coalesce((select jsonb_agg(jsonb_build_object('code',c.code,'percent',c.discount_percent) order by c.code)
      from public.codes c where c.kind='campaign' and p.product_id=any(c.discount_products) and c.discount_percent is not null
      and ((c.active and (c.expires_at is null or c.expires_at>now())) or exists(select from public.code_redemptions x
        where x.code_id=c.id and x.status='ok' and x.discount_used_payment_id is null and x.discount_void_at is null
        and (x.discount_expires_at is null or x.discount_expires_at>now())))),'[]'),'bindings',coalesce((select jsonb_object_agg(s.lookup_key,s.price_id) from admin.catalog_stripe_prices s
    where s.product_id=p.product_id and s.revision=p.published_revision),'{}'),'history',
    coalesce((select jsonb_agg(to_jsonb(h) order by h.created_at desc,h.id desc) from
      (select id,revision,base_revision,reason,status,created_at,actor_id,last_error from admin.catalog_publications where product_id=p_product
       and (created_at,id)<(p_before,p_before_id) order by created_at desc,id desc limit 21) h),'[]')) into result
  from admin.catalog_products p left join admin.catalog_product_versions v on v.product_id=p.product_id and v.revision=p.published_revision
  left join admin.catalog_publications r on r.product_id=p.product_id and r.status in ('draft','prepared')
  left join admin.catalog_product_versions d on d.product_id=p.product_id and d.revision=r.revision where p.product_id=p_product;
  return result;
end $$;


ALTER FUNCTION "public"."admin_catalog_editor"("p_actor" "uuid", "p_product" "text", "p_before" timestamp with time zone, "p_before_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_catalog_page"("p_actor" "uuid", "p_after" "text" DEFAULT ''::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  perform admin.catalog_require_actor(p_actor);
  return coalesce((select jsonb_agg(to_jsonb(rows) order by product_id) from
    (select p.product_id,p.tier,p.kind,p.published_revision,v.name_en,v.name_zh,v.usd_cents,v.credits,v.listed,
     (select status from admin.catalog_publications r where r.product_id=p.product_id and r.status in ('draft','prepared')) as pending
     from admin.catalog_products p left join admin.catalog_product_versions v on v.product_id=p.product_id and v.revision=p.published_revision
     where p.product_id>p_after order by p.product_id limit 31) rows),'[]');
end $$;


ALTER FUNCTION "public"."admin_catalog_page"("p_actor" "uuid", "p_after" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_catalog_prepare"("p_actor" "uuid", "p_id" "uuid", "p_account" "text", "p_live" boolean, "p_prices" "jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare r admin.catalog_publications; v admin.catalog_product_versions;
begin
  perform admin.catalog_require_actor(p_actor);
  perform admin.catalog_lock_publication();
  perform admin.require_catalog_policy();
  r := admin.catalog_locked_request(p_id);
  if r.status='prepared' and r.stripe_account=p_account and r.livemode=p_live then return r.id; end if;
  if r.status<>'draft' then raise exception 'CATALOG_STALE'; end if;
  select * into strict v from admin.catalog_product_versions where product_id=r.product_id and revision=r.revision;
  perform admin.validate_catalog_terms(r.product_id,v.usd_cents,v.credits,v.listed);
  insert into admin.catalog_stripe_environment(stripe_account,livemode) values(p_account,p_live) on conflict(singleton) do nothing;
  if not exists(select from admin.catalog_stripe_environment where stripe_account=p_account and livemode=p_live) then raise exception 'CATALOG_ENVIRONMENT'; end if;
  perform admin.catalog_bind_prices(r.product_id,r.base_revision,p_account,p_live,p_prices);
  update admin.catalog_publications set status='prepared',stripe_account=p_account,livemode=p_live,prepared_at=now(),last_error=null,retry_at=null where id=p_id;
  perform admin.catalog_audit(p_actor,'catalog_prepare',r,p_prices);
  return r.id;
end $$;


ALTER FUNCTION "public"."admin_catalog_prepare"("p_actor" "uuid", "p_id" "uuid", "p_account" "text", "p_live" boolean, "p_prices" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_catalog_publish"("p_actor" "uuid", "p_id" "uuid", "p_account" "text", "p_live" boolean, "p_prices" "jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare r admin.catalog_publications; v admin.catalog_product_versions;
begin
  perform admin.catalog_require_actor(p_actor);
  perform admin.catalog_lock_publication();
  perform admin.require_catalog_policy();
  r := admin.catalog_locked_request(p_id);
  if r.stripe_account is distinct from p_account or r.livemode is distinct from p_live then raise exception 'CATALOG_ENVIRONMENT'; end if;
  if r.status='published' then return r.id; end if;
  if r.status<>'prepared' then raise exception 'CATALOG_STALE'; end if;
  select * into strict v from admin.catalog_product_versions where product_id=r.product_id and revision=r.revision;
  perform admin.validate_catalog_terms(r.product_id,v.usd_cents,v.credits,v.listed);
  perform admin.catalog_bind_prices(r.product_id,r.revision,p_account,p_live,p_prices);
  update admin.catalog_products set published_revision=r.revision where product_id=r.product_id;
  update admin.catalog_publications set status='published',published_at=now(),last_error=null,retry_at=null where id=p_id;
  perform admin.catalog_audit(p_actor,'catalog_publish',r,p_prices);
  return r.id;
end $$;


ALTER FUNCTION "public"."admin_catalog_publish"("p_actor" "uuid", "p_id" "uuid", "p_account" "text", "p_live" boolean, "p_prices" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_catalog_release"("p_actor" "uuid", "p_product" "text", "p_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  perform admin.catalog_require_actor(p_actor);
  return (select jsonb_build_object('id',r.id,'revision',r.revision)
    from admin.catalog_publications r join admin.catalog_products p using(product_id)
    where r.product_id=p_product and r.status='published' and
      (r.id=p_id or (p_id is null and r.revision=p.published_revision)));
end $$;


ALTER FUNCTION "public"."admin_catalog_release"("p_actor" "uuid", "p_product" "text", "p_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_catalog_retry"("p_actor" "uuid", "p_id" "uuid", "p_step" "text", "p_error" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare r admin.catalog_publications;
begin
  perform admin.catalog_require_actor(p_actor);
  if p_step not in ('prepare','publish','archive','waffo') or p_error !~ '^[a-zA-Z0-9_.:-]{1,140}$' then raise exception 'INVALID_INPUT'; end if;
  update admin.catalog_publications set last_error=p_step||':'||p_error,retry_at=now() where id=p_id
    and (p_step in ('archive','waffo') or status in ('draft','prepared')) returning * into r;
  if found then perform admin.catalog_audit(p_actor,'catalog_retry',r,jsonb_build_object('step',p_step,'error',p_error)); end if;
end $_$;


ALTER FUNCTION "public"."admin_catalog_retry"("p_actor" "uuid", "p_id" "uuid", "p_step" "text", "p_error" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_catalog_save"("p_actor" "uuid", "p_product" "text", "p_base" integer, "p_previous" "uuid", "p_terms" "jsonb", "p_reason" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  identity admin.catalog_products; pending admin.catalog_publications; draft admin.catalog_publications;
  item admin.catalog_product_versions; next_rev integer; new_tier text; new_kind text;
begin
  perform admin.catalog_require_actor(p_actor);
  perform admin.catalog_lock_publication();
  perform pg_advisory_xact_lock(hashtextextended('catalog_identity:'||p_product,0));
  item := jsonb_populate_record(null::admin.catalog_product_versions,p_terms);
  if length(trim(item.name_en)) not between 1 and 120 or length(trim(item.name_zh)) not between 1 and 120
    or length(item.benefit_en)>1000 or length(item.benefit_zh)>1000 or item.sort_order not between 0 and 99999
    or length(trim(p_reason)) not between 1 and 500 then raise exception 'INVALID_INPUT'; end if;
  select * into identity from admin.catalog_products where product_id=p_product for update;
  if not found then
    if p_base is not null or p_previous is not null then raise exception 'CATALOG_STALE'; end if;
    if p_product ~ '^pack_[a-z][a-z0-9]{0,47}$' then
      new_tier := 'pack'; new_kind := 'pack';
    elsif p_product ~ '^[a-z][a-z0-9]{0,47}_(monthly|yearly)$' then
      new_tier := p_terms->>'tier';
      if new_tier is null or new_tier not in ('starter','pro','max') then raise exception 'INVALID_INPUT'; end if;
      new_kind := substring(p_product from '(monthly|yearly)$');
    else raise exception 'INVALID_INPUT'; end if;
    insert into public.products(id,credits,price_usd,active,days)
      values(p_product,item.credits,item.usd_cents/100.0,false,case new_kind when 'monthly' then 30 when 'yearly' then 365 end);
    insert into admin.catalog_products(product_id,tier,kind) values(p_product,new_tier,new_kind) returning * into identity;
  end if;
  if p_terms ? 'tier' and p_terms->>'tier' is distinct from identity.tier then raise exception 'INVALID_INPUT'; end if;
  if identity.published_revision is distinct from p_base then raise exception 'CATALOG_STALE'; end if;
  select * into pending from admin.catalog_publications where product_id=p_product and status in ('draft','prepared') for update;
  if pending.id is distinct from p_previous or pending.status='prepared' then raise exception 'CATALOG_STALE'; end if;
  perform admin.validate_catalog_terms(p_product,item.usd_cents,item.credits,item.listed);
  select greatest(coalesce(max(revision),2),2)+1 into next_rev from admin.catalog_product_versions where product_id=p_product;
  insert into admin.catalog_product_versions(product_id,revision,usd_cents,credits,paid_days,listed,sort_order,name_en,name_zh,benefit_en,benefit_zh)
    values(p_product,next_rev,item.usd_cents,item.credits,case identity.kind when 'yearly' then 365 when 'monthly' then 30 end,
      item.listed,item.sort_order,trim(item.name_en),trim(item.name_zh),trim(item.benefit_en),trim(item.benefit_zh));
  update admin.catalog_publications set status='superseded' where id=p_previous;
  insert into admin.catalog_publications(product_id,revision,base_revision,actor_id,reason)
    values(p_product,next_rev,p_base,p_actor,trim(p_reason)) returning * into draft;
  perform admin.catalog_audit(p_actor,'catalog_save',draft,p_terms);
  return draft.id;
end $_$;


ALTER FUNCTION "public"."admin_catalog_save"("p_actor" "uuid", "p_product" "text", "p_base" integer, "p_previous" "uuid", "p_terms" "jsonb", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_catalog_waffo"("p_actor" "uuid", "p_id" "uuid", "p_store" "text", "p_mode" "text", "p_once" "text", "p_recurring" "text", "p_baseline_recurring" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare r admin.catalog_publications; v admin.catalog_product_versions; base admin.catalog_product_versions;
begin
  perform admin.catalog_require_actor(p_actor);
  r:=admin.catalog_locked_request(p_id);
  if r.status not in ('prepared','published') then raise exception 'CATALOG_STALE'; end if;
  select * into strict v from admin.catalog_product_versions where product_id=r.product_id and revision=r.revision;
  select * into base from admin.catalog_product_versions where product_id=r.product_id and revision=2;
  if p_store !~ '^STO_[A-Za-z0-9]+$' or p_once !~ '^PROD_[A-Za-z0-9]+$' or (v.paid_days is null)<>(p_recurring is null)
    or p_recurring !~ '^PROD_[A-Za-z0-9]+$' then raise exception 'INVALID_INPUT'; end if;
  if p_recurring is not null and ((base.usd_cents<>v.usd_cents and p_recurring=p_baseline_recurring)
    or exists(select from admin.catalog_waffo_bindings b where b.recurring_id=p_recurring and
      (b.usd_cents<>v.usd_cents or b.product_id<>r.product_id) and b.store_id=p_store and b.mode=p_mode)) then
    raise exception 'CATALOG_WAFFO_LEGACY_CONTRACT'; end if;
  insert into admin.catalog_waffo_bindings(product_id,revision,store_id,mode,one_time_id,recurring_id,usd_cents)
   values(r.product_id,r.revision,p_store,p_mode,p_once,p_recurring,v.usd_cents) on conflict do nothing;
  if not exists(select from admin.catalog_waffo_bindings b where b.product_id=r.product_id and b.revision=r.revision
    and b.store_id=p_store and b.mode=p_mode and b.one_time_id=p_once and b.recurring_id is not distinct from p_recurring)
    then raise exception 'CATALOG_BINDING_CONFLICT'; end if;
  perform admin.catalog_audit(p_actor,'catalog_waffo',r,jsonb_build_object('mode',p_mode,'one',p_once,'recurring',p_recurring));
end $_$;


ALTER FUNCTION "public"."admin_catalog_waffo"("p_actor" "uuid", "p_id" "uuid", "p_store" "text", "p_mode" "text", "p_once" "text", "p_recurring" "text", "p_baseline_recurring" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_claim_prompt_lab_run"("p_actor" "uuid", "p_run_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
begin
  perform admin.require_reference_admin(p_actor);
  -- A stale queued job must not call a provider on a later budget day.
  perform pg_advisory_xact_lock(hashtext('shotviva.admin_test_budget'));
  update public.prompt_lab_runs set status='running',claimed_at=clock_timestamp() where id=p_run_id and status='queued'
    and started_at>clock_timestamp()-interval '10 minutes'
    and (started_at at time zone 'Asia/Shanghai')::date=(clock_timestamp() at time zone 'Asia/Shanghai')::date;
  if not found then return false; end if;
  update public.admin_test_spend set counted_usd=estimate_usd where run_id=p_run_id;
  return true;
end $$;


ALTER FUNCTION "public"."admin_claim_prompt_lab_run"("p_actor" "uuid", "p_run_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_clawback_payment"("p_payment_id" bigint, "p_actor" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_payment public.payments;
  v_granted integer;
  v_balance integer;
  v_take integer;
  v_key text;
begin
  if p_actor is null or not exists (select 1 from public.profiles where id = p_actor and role = 'admin') then
    raise exception 'NOT_ADMIN';
  end if;

  select * into v_payment from public.payments where id = p_payment_id for update;
  if not found then
    raise exception 'PAYMENT_NOT_FOUND';
  end if;

  v_granted := public._payment_granted_credits(v_payment);
  select credits into v_balance from public.profiles where id = v_payment.user_id for update;
  v_take := greatest(0, least(coalesce(v_balance, 0), v_granted - v_payment.credits_clawed_back - v_payment.clawback_shortfall));

  if v_take > 0 then
    v_key := 'clawback:' || p_payment_id || ':admin:' || (v_payment.credits_clawed_back + v_payment.clawback_shortfall);
    if (public._apply_credit_change(v_payment.user_id, 'paid', 'clawback', -v_take,
          '后台扣回付款 #' || p_payment_id || ' 的剩余积分 · 操作人 ' || p_actor::text, v_key)).applied then
      update public.credit_ledger set payment_id = p_payment_id where idempotency_key = v_key;
      update public.payments set credits_clawed_back = credits_clawed_back + v_take
       where id = p_payment_id
      returning * into v_payment;
      insert into public.admin_audit_log (action, user_id, reason, target_id)
      values ('clawback_payment', v_payment.user_id, '扣回 ' || v_take || ' 积分 · 操作人 ' || p_actor::text, p_payment_id::text);
    else
      v_take := 0;
    end if;
  end if;

  return jsonb_build_object(
    'taken', v_take,
    'credits_clawed_back', v_payment.credits_clawed_back,
    'clawback_shortfall', v_payment.clawback_shortfall
  );
end;
$$;


ALTER FUNCTION "public"."admin_clawback_payment"("p_payment_id" bigint, "p_actor" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_cleanup_test_runs"("p_actor" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  v_run_keys text[];
  v_photo_keys text[];
begin
  if p_actor is null or not exists (select 1 from public.profiles p where p.id = p_actor and p.role = 'admin') then
    raise exception 'NOT_ADMIN';
  end if;

  perform public.admin_expire_prompt_lab_runs(p_actor);
  update public.admin_test_runs r
     set status = 'failed', error_code = 'TIMEOUT', finished_at = now()
   where r.status = 'running' and r.created_at < now() - interval '10 minutes';
  update public.admin_test_spend x
     set counted_usd = 0, finished_at = now()
   where x.counted_usd is null and x.started_at < now() - interval '10 minutes';
  delete from public.admin_test_spend x where x.started_at < now() - interval '100 days';

  with ranked as (
    select r.id, r.created_at, r.cover_set_at,
           row_number() over (partition by r.template_id order by r.created_at desc, r.id desc) as n
      from public.admin_test_runs r
  ),
  doomed as (
    delete from public.admin_test_runs r
     using ranked k
     where r.id = k.id
       and k.cover_set_at is null
       and (k.created_at < now() - interval '30 days' or k.n > 50)
    returning r.output_key
  )
  select coalesce(array_agg(d.output_key) filter (where d.output_key is not null), '{}') into v_run_keys from doomed d;

  with doomed as (
    delete from public.admin_test_photos ph
     where ph.last_used_at < now() - interval '30 days'
       and not exists (select 1 from public.prompt_lab_runs l where l.photo_id=ph.id)
       and not exists (select 1 from public.admin_test_runs r where r.photo_id = ph.id and r.cover_set_at is not null)
    returning ph.object_key
  )
  select coalesce(array_agg(d.object_key), '{}') into v_photo_keys from doomed d;

  return jsonb_build_object('keys', to_jsonb(v_run_keys || v_photo_keys));
end;
$$;


ALTER FUNCTION "public"."admin_cleanup_test_runs"("p_actor" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_code_redemptions"("p_actor" "uuid", "p_code_id" "uuid" DEFAULT NULL::"uuid", "p_cursor" "jsonb" DEFAULT NULL::"jsonb") RETURNS SETOF "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $$
begin
  if not exists (select 1 from public.profiles where id = p_actor and role = 'admin' and banned_at is null) then
    raise exception 'NOT_ADMIN';
  end if;
  return query
    with page as materialized (
      select r.id, r.code_id, r.user_id, r.inviter_user_id, r.context, r.status,
        r.credits_granted, r.inviter_rewarded_at, r.inviter_reward_payment_id, r.discount_expires_at,
        r.discount_used_payment_id, r.discount_void_at, r.created_at
      from public.code_redemptions r
      where (r.code_id = p_code_id or (p_code_id is null and r.status = 'blocked_same_ip'))
        and (p_cursor is null or (r.created_at,r.id) < ((p_cursor->>'created_at')::timestamptz,(p_cursor->>'id')::uuid))
      order by r.created_at desc, r.id desc limit 30
    )
    select to_jsonb(r) || jsonb_build_object('code', c.code,
      'reward_payment_status', reward.status, 'reward_payment_refunded', reward.amount_refunded,
      'discount_conflict_payments', coalesce((
        select jsonb_agg(p.id order by p.id) from public.payments p
        where p.code_id = r.code_id and p.user_id = r.user_id and p.code_discount_conflict
      ), '[]'::jsonb))
    from page r left join public.codes c on c.id = r.code_id
    left join public.payments reward on reward.id = r.inviter_reward_payment_id
    order by r.created_at desc, r.id desc;
end;
$$;


ALTER FUNCTION "public"."admin_code_redemptions"("p_actor" "uuid", "p_code_id" "uuid", "p_cursor" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_commit_template_copy"("p_actor" "uuid", "p_source" "text", "p_request" "uuid", "p_target" "text", "p_token" "text", "p_assets" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $_$
declare t public.templates%rowtype; p public.template_prompts%rowtype; m jsonb; translated jsonb;
begin
  -- Serialize only retries of this specific request; unrelated templates copy concurrently.
  perform pg_advisory_xact_lock(hashtextextended(p_request::text,400));
  perform 1 from public.templates where id=p_source for share;
  perform 1 from public.template_prompts where template_id=p_source for share;
  m:=public.admin_template_copy_source(p_actor,p_source,p_request);
  if m ? 'existing' then return m->'existing'; end if;
  if p_token is distinct from m->>'token' then raise exception 'SOURCE_CHANGED'; end if;
  if p_target=p_source or p_target !~ '^[a-z0-9-]+-copy-[0-9a-f-]{36}$' or
    p_assets is distinct from replace(replace((m->'assets')::text,'/covers/'||p_source||'/','/covers/'||p_target||'/'),
      'style-refs/'||p_source||'/','style-refs/'||p_target||'/')::jsonb then raise exception 'REQUEST_MISMATCH'; end if;

  select * into strict t from public.templates where id=p_source;
  select * into strict p from public.template_prompts where template_id=p_source;
  translated:=t.translations;
  if nullif(translated#>>'{zh,name}','') is not null then
    translated:=jsonb_set(translated,'{zh,name}',to_jsonb(left(translated#>>'{zh,name}',115)||'（副本）'));
  end if;
  insert into public.templates(id,module,name,description,category_key,subcategory_key,fields,quality,credits_cost,visible_in,translations,
    sort_order,is_active,featured_rank,cover_media_type,cover_before_url,cover_after_url,cover_video_url,cover_poster_url,cover_locales)
  values(p_target,t.module,left(t.name,113)||' (Copy)',t.description,t.category_key,t.subcategory_key,t.fields,t.quality,t.credits_cost,t.visible_in,translated,
    (select coalesce(max(sort_order),0)+10 from public.templates),false,null,t.cover_media_type,
    p_assets->>'cover_before_url',p_assets->>'cover_after_url',p_assets->>'cover_video_url',p_assets->>'cover_poster_url',p_assets->'cover_locales');
  insert into public.template_prompts(template_id,body,model_params,provider_id,style_refs)
    values(p_target,p.body,p.model_params,p.provider_id,p_assets->'style_refs');
  perform admin.copy_template_price_marks(p_source,p_target);
  insert into admin.template_copy_requests values(p_request,p_actor,p_source,p_target,null);
  return jsonb_build_object('id',p_target,'previousStandard',null);
end $_$;


ALTER FUNCTION "public"."admin_commit_template_copy"("p_actor" "uuid", "p_source" "text", "p_request" "uuid", "p_target" "text", "p_token" "text", "p_assets" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_daily_costs"("p_days" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $$
declare
  v_today timestamptz;
  v_start timestamptz;
begin
  if p_days is null or p_days < 1 or p_days > 90 then
    raise exception 'INVALID_INPUT' using detail = 'p_days must be between 1 and 90';
  end if;

  v_today := date_trunc('day', now() at time zone 'UTC') at time zone 'UTC';
  v_start := v_today - make_interval(days => p_days - 1);

  return (
    with jobs as (
      select date_trunc('day', g.created_at at time zone 'UTC') as day, g.status, g.provider_usage, g.cost_usd
        from public.generation_jobs g
       where g.created_at >= v_start
    ),
    per_day as (
      select j.day,
             coalesce(sum(j.cost_usd), 0) as cost_usd,
             bool_or(coalesce(j.provider_usage ?| array['cost', 'prompt_tokens', 'completion_tokens'], false)) as has_openrouter,
             count(*) filter (where j.cost_usd is not null) as costed,
             count(*) filter (where j.cost_usd is null and j.provider_usage is not null) as uncosted,
             count(*) filter (where j.cost_usd is null and j.provider_usage is null and j.status <> 'running') as no_usage
        from jobs j
       group by j.day
    )
    select coalesce(jsonb_agg(jsonb_build_object(
             'day', to_char(d.day, 'YYYY-MM-DD'),
             'cost_usd', coalesce(p.cost_usd, 0),
             'has_openrouter', coalesce(p.has_openrouter, false),
             'costed', coalesce(p.costed, 0),
             'uncosted', coalesce(p.uncosted, 0),
             'no_usage', coalesce(p.no_usage, 0)
           ) order by d.day), '[]'::jsonb)
      from generate_series(v_start at time zone 'UTC', v_today at time zone 'UTC', interval '1 day') as d(day)
      left join per_day p on p.day = d.day
  );
end;
$$;


ALTER FUNCTION "public"."admin_daily_costs"("p_days" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_dashboard_stats"("p_days" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $$
declare
  v_tz constant text := 'Asia/Shanghai';
  v_today timestamptz;
  v_start timestamptz;
  v_result jsonb;
begin
  if p_days is null or p_days < 7 or p_days > 90 then
    raise exception 'INVALID_INPUT' using detail = 'p_days must be between 7 and 90';
  end if;

  v_today := date_trunc('day', now() at time zone v_tz) at time zone v_tz;
  v_start := v_today - make_interval(days => p_days - 1);

  with windows(key, since) as (
    values ('today', v_today), ('7d', v_today - interval '6 days'), ('period', v_start)
  ),
  jobs as (
    select g.created_at,
           g.status,
           -- generation_jobs.provider is '<source>/<model>'; older rows hold a bare name.
           case when position('/' in g.provider) > 0 then split_part(g.provider, '/', 1) else 'legacy' end as provider,
           case when position('/' in g.provider) > 0
                then substr(g.provider, position('/' in g.provider) + 1)
                else coalesce(g.provider, 'unknown') end as model,
           coalesce(g.inputs ->> 'resolution', '1k') as resolution,
           g.cost_usd,
           g.provider_usage is not null and g.cost_usd is null as uncosted,
           g.status = 'succeeded' and g.provider_usage is null and g.cost_usd is null as legacy
      from public.generation_jobs g
     where g.created_at >= v_start
  ),
  -- Net credits spent on generation: reserves minus refunds, per pool.
  spend as (
    select l.created_at, l.pool, -l.delta as used
      from public.credit_ledger l
     where l.created_at >= v_start and l.kind in ('reserve', 'refund')
  ),
  -- A paying user is new on the day of their first purchase ever.
  first_purchases as (
    select l.user_id, min(l.created_at) as first_at
      from public.credit_ledger l
     where l.created_at >= v_start
       and l.kind = 'purchase'
       and not exists (
         select 1 from public.credit_ledger e
          where e.user_id = l.user_id and e.kind = 'purchase' and e.created_at < v_start
       )
     group by l.user_id
  ),
  window_stats as (
    select jsonb_agg(jsonb_build_object(
             'key', w.key,
             'since', w.since,
             'signups', (select count(*) from public.profiles p where p.created_at >= w.since),
             'jobs', (select count(*) from jobs j where j.created_at >= w.since),
             'succeeded', (select count(*) from jobs j where j.created_at >= w.since and j.status = 'succeeded'),
             'failed', (select count(*) from jobs j where j.created_at >= w.since and j.status = 'failed'),
             'free_credits_used', (select coalesce(sum(s.used), 0) from spend s where s.created_at >= w.since and s.pool = 'free'),
             'paid_credits_used', (select coalesce(sum(s.used), 0) from spend s where s.created_at >= w.since and s.pool = 'paid'),
             'new_paying_users', (select count(*) from first_purchases f where f.first_at >= w.since),
             'cost_usd', (select coalesce(sum(j.cost_usd), 0) from jobs j where j.created_at >= w.since),
             'uncosted', (select count(*) from jobs j where j.created_at >= w.since and j.uncosted),
             'legacy', (select coalesce(jsonb_object_agg(r.resolution, r.n), '{}'::jsonb)
                          from (select j.resolution, count(*) as n from jobs j
                                 where j.created_at >= w.since and j.legacy group by j.resolution) r)
           ) order by w.since desc) as value
      from windows w
  ),
  trend as (
    select jsonb_agg(jsonb_build_object(
             'day', to_char(d.day at time zone v_tz, 'YYYY-MM-DD'),
             'jobs', (select count(*) from jobs j where j.created_at >= d.day and j.created_at < d.day + interval '1 day'),
             'succeeded', (select count(*) from jobs j
                            where j.created_at >= d.day and j.created_at < d.day + interval '1 day' and j.status = 'succeeded'),
             'cost_usd', (select coalesce(sum(j.cost_usd), 0) from jobs j
                           where j.created_at >= d.day and j.created_at < d.day + interval '1 day'),
             'legacy', (select coalesce(jsonb_object_agg(r.resolution, r.n), '{}'::jsonb)
                          from (select j.resolution, count(*) as n from jobs j
                                 where j.created_at >= d.day and j.created_at < d.day + interval '1 day' and j.legacy
                                 group by j.resolution) r)
           ) order by d.day) as value
      from generate_series(v_start, v_today, interval '1 day') as d(day)
  ),
  by_model as (
    select jsonb_agg(jsonb_build_object(
             'provider', m.provider, 'model', m.model, 'resolution', m.resolution, 'jobs', m.jobs, 'succeeded', m.succeeded,
             'cost_usd', m.cost_usd, 'uncosted', m.uncosted, 'legacy', m.legacy
           ) order by m.jobs desc, m.provider, m.model, m.resolution) as value
      from (
        select j.provider, j.model, j.resolution, count(*) as jobs, count(*) filter (where j.status = 'succeeded') as succeeded,
               coalesce(sum(j.cost_usd), 0) as cost_usd,
               count(*) filter (where j.uncosted) as uncosted,
               count(*) filter (where j.legacy) as legacy
          from jobs j
         group by j.provider, j.model, j.resolution
      ) m
  )
  select jsonb_build_object(
           'timezone', v_tz,
           'days', p_days,
           'generated_at', now(),
           'windows', (select value from window_stats),
           'trend', coalesce((select value from trend), '[]'::jsonb),
           'by_model', coalesce((select value from by_model), '[]'::jsonb)
         )
    into v_result;
  return v_result;
end;
$$;


ALTER FUNCTION "public"."admin_dashboard_stats"("p_days" integer) OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."support_tickets" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "user_id" "uuid" NOT NULL,
    "type" "text" NOT NULL,
    "status" "text" DEFAULT 'open'::"text" NOT NULL,
    "payment_id" bigint,
    "job_id" "uuid",
    "refund_decision" "text",
    "refund_amount_cents" integer,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "last_message_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "user_seen_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "closed_at" timestamp with time zone,
    CONSTRAINT "support_tickets_closed" CHECK ((("status" = 'closed'::"text") = ("closed_at" IS NOT NULL))),
    CONSTRAINT "support_tickets_decision_amount" CHECK ((("refund_decision" = 'approved'::"text") = ("refund_amount_cents" IS NOT NULL))),
    CONSTRAINT "support_tickets_decision_type" CHECK ((("refund_decision" IS NULL) OR ("type" = 'refund'::"text"))),
    CONSTRAINT "support_tickets_job_type" CHECK ((("job_id" IS NULL) OR ("type" = 'image_issue'::"text"))),
    CONSTRAINT "support_tickets_payment_type" CHECK ((("payment_id" IS NULL) OR ("type" = ANY (ARRAY['billing'::"text", 'refund'::"text"])))),
    CONSTRAINT "support_tickets_refund_amount_cents_check" CHECK (("refund_amount_cents" > 0)),
    CONSTRAINT "support_tickets_refund_decision_check" CHECK (("refund_decision" = ANY (ARRAY['approved'::"text", 'rejected'::"text"]))),
    CONSTRAINT "support_tickets_refund_payment" CHECK ((("type" <> 'refund'::"text") OR ("payment_id" IS NOT NULL))),
    CONSTRAINT "support_tickets_status_check" CHECK (("status" = ANY (ARRAY['open'::"text", 'replied'::"text", 'closed'::"text"]))),
    CONSTRAINT "support_tickets_type_check" CHECK (("type" = ANY (ARRAY['feedback'::"text", 'image_issue'::"text", 'billing'::"text", 'refund'::"text", 'account'::"text", 'other'::"text"])))
);


ALTER TABLE "public"."support_tickets" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_decide_refund"("p_ticket_id" "uuid", "p_decision" "text", "p_amount_cents" integer, "p_body" "text") RETURNS "public"."support_tickets"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_ticket public.support_tickets;
  v_left integer;
  v_body text := btrim(coalesce(p_body, ''));
begin
  if p_decision is null or p_decision not in ('approved', 'rejected') then
    raise exception 'INVALID_INPUT' using detail = 'decision must be approved or rejected';
  end if;
  if char_length(v_body) not between 1 and 2000 then
    raise exception 'INVALID_INPUT' using detail = 'a decision needs a reply of 1 to 2000 characters';
  end if;

  select * into v_ticket from public.support_tickets t where t.id = p_ticket_id for update;
  if not found then
    raise exception 'TICKET_NOT_FOUND';
  end if;
  if v_ticket.type <> 'refund' then
    raise exception 'INVALID_INPUT' using detail = 'not a refund ticket';
  end if;

  select p.amount_total - p.amount_refunded into v_left from public.payments p where p.id = v_ticket.payment_id;
  if p_decision = 'approved' and (p_amount_cents is null or p_amount_cents not between 1 and v_left) then
    raise exception 'INVALID_INPUT' using detail = 'amount must be between 1 and the unrefunded total';
  end if;
  if p_decision = 'rejected' and p_amount_cents is not null then
    raise exception 'INVALID_INPUT' using detail = 'a rejection takes no amount';
  end if;

  update public.support_tickets
     set refund_decision = p_decision,
         refund_amount_cents = p_amount_cents,
         status = 'replied',
         closed_at = null,
         last_message_at = now()
   where id = p_ticket_id
  returning * into v_ticket;

  insert into public.support_ticket_messages (ticket_id, author, body) values (p_ticket_id, 'admin', v_body);

  insert into public.admin_audit_log (action, user_id, target_id, reason)
  values (
    'decide_refund',
    v_ticket.user_id,
    p_ticket_id::text,
    format('退款工单：%s%s', p_decision, case when p_amount_cents is null then '' else ' ' || p_amount_cents end)
  );
  return v_ticket;
end;
$$;


ALTER FUNCTION "public"."admin_decide_refund"("p_ticket_id" "uuid", "p_decision" "text", "p_amount_cents" integer, "p_body" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_delete_provider"("p_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_active boolean;
begin
  -- Row lock: a concurrent switch to this row waits for the delete, or the delete sees it active.
  select is_active into v_active from public.ai_providers where id = p_id for update;
  if not found then
    raise exception 'PROVIDER_NOT_FOUND';
  end if;
  -- The module would silently fall back (env, or none for decision): switch first.
  if v_active then
    raise exception 'PROVIDER_ACTIVE' using errcode = '55000';
  end if;

  if exists (select 1 from public.template_prompts where provider_id = p_id) then
    raise exception 'PROVIDER_REFERENCED' using errcode = '23503';
  end if;

  delete from public.ai_providers where id = p_id;
  delete from vault.secrets where name = 'shotviva.provider.' || p_id::text;
end;
$$;


ALTER FUNCTION "public"."admin_delete_provider"("p_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_delete_reference_category"("p_actor" "uuid", "p_key" "text", "p_move_to" "text") RETURNS integer
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare moved integer:=0;
begin
  perform admin.require_reference_admin(p_actor);
  perform pg_advisory_xact_lock(hashtextextended('shotviva.category_tree',0));
  perform 1 from public.template_categories where key=p_key and kind='reference' for update;
  if not found then raise exception 'CATEGORY_NOT_FOUND'; end if;
  if exists(select from public.template_categories where parent_id=p_key) then raise exception 'CATEGORY_HAS_CHILDREN'; end if;
  if p_move_to is not null then
    perform 1 from public.template_categories where key=p_move_to and key<>p_key and kind='reference' for update;
    if not found then raise exception 'CATEGORY_NOT_FOUND'; end if;
    update public.reference_assets set category_id=p_move_to where category_id=p_key;
    get diagnostics moved=row_count;
  elsif exists(select from public.reference_assets where category_id=p_key) then
    raise exception 'CATEGORY_MOVE_REQUIRED';
  end if;
  delete from public.template_categories where key=p_key;
  return moved;
end $$;


ALTER FUNCTION "public"."admin_delete_reference_category"("p_actor" "uuid", "p_key" "text", "p_move_to" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_delete_template_category"("p_key" "text", "p_move_to" "text", "p_actor" "uuid") RETURNS integer
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare moved integer:=0; dest text;
begin
  if not exists(select 1 from public.profiles where id=p_actor and role='admin') then raise exception 'NOT_ADMIN'; end if;
  perform pg_advisory_xact_lock(hashtextextended('shotviva.category_tree',0));
  perform 1 from public.template_categories where key=p_key and kind='template' for update;
  if not found then raise exception 'CATEGORY_NOT_FOUND'; end if;
  if exists(select 1 from public.template_categories where key=p_key and is_system) then raise exception 'CATEGORY_SYSTEM'; end if;
  if exists(select 1 from public.template_categories where parent_id=p_key) then raise exception 'CATEGORY_HAS_CHILDREN'; end if;
  if not exists(select 1 from public.template_categories where kind='template' and not is_system and key<>p_key)
    then raise exception 'CATEGORY_LAST'; end if;
  if exists(select 1 from public.templates where category_key=p_key or subcategory_key=p_key)
    or exists(select 1 from public.template_series where category_key=p_key) then
    if p_move_to is null then raise exception 'CATEGORY_MOVE_REQUIRED'; end if;
    select c.root_key into dest from public.template_category_paths c join public.template_categories n on n.key=c.key
      where c.key=p_move_to and not n.is_system and c.key<>p_key;
    if not found then raise exception 'INVALID_INPUT'; end if;
    update public.templates set category_key=dest,subcategory_key=nullif(p_move_to,dest)
      where category_key=p_key or subcategory_key=p_key;
    get diagnostics moved = row_count;
    update public.template_series set category_key=p_move_to where category_key=p_key;
  end if;
  delete from public.template_categories where key=p_key;
  return moved;
end $$;


ALTER FUNCTION "public"."admin_delete_template_category"("p_key" "text", "p_move_to" "text", "p_actor" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_due_reference_deletions"("p_actor" "uuid") RETURNS TABLE("r2_key" "text")
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
begin
  perform admin.require_reference_admin(p_actor);
  return query select d.r2_key from public.reference_object_deletions d
    where d.created_at<=clock_timestamp() order by d.created_at,d.r2_key limit 200 for update skip locked;
end $$;


ALTER FUNCTION "public"."admin_due_reference_deletions"("p_actor" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_edit_reference_asset"("p_actor" "uuid", "p_id" "uuid", "p_fields" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
begin
  perform admin.require_reference_admin(p_actor);
  if jsonb_typeof(p_fields) is distinct from 'object'
    or p_fields - array['category_id','source_url','note','tags'] <> '{}'::jsonb then raise exception 'INVALID_INPUT'; end if;
  perform pg_advisory_xact_lock_shared(hashtextextended('shotviva.category_tree',0));
  update public.reference_assets set
    category_id=case when p_fields?'category_id' then p_fields->>'category_id' else category_id end,
    source_url=case when p_fields?'source_url' then p_fields->>'source_url' else source_url end,
    note=case when p_fields?'note' then p_fields->>'note' else note end,
    tags=case when p_fields?'tags' then array(select jsonb_array_elements_text(p_fields->'tags')) else tags end
  where id=p_id;
  if not found then raise exception 'REFERENCE_NOT_FOUND'; end if;
end $$;


ALTER FUNCTION "public"."admin_edit_reference_asset"("p_actor" "uuid", "p_id" "uuid", "p_fields" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_expire_prompt_lab_runs"("p_actor" "uuid") RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
begin
  perform admin.require_reference_admin(p_actor);
  with expired as (
    update public.prompt_lab_runs set status='failed',error_code='TIMEOUT',finished_at=now()
      where (status='queued' and (started_at<now()-interval '10 minutes'
        or (started_at at time zone 'Asia/Shanghai')::date<(now() at time zone 'Asia/Shanghai')::date))
      or (status='running' and claimed_at<now()-interval '10 minutes')
      returning id,claimed_at
  )
  update public.admin_test_spend s set counted_usd=case when e.claimed_at is null then 0 else s.estimate_usd end,finished_at=now()
    from expired e where s.run_id=e.id;
  with expired as (
    update public.prompt_lab_reverse_requests set status='failed',error_code='TIMEOUT',finished_at=now()
      where status='running' and started_at<now()-interval '10 minutes' returning id
  )
  update public.admin_test_spend s set finished_at=now() from expired e where s.run_id=e.id;
end $$;


ALTER FUNCTION "public"."admin_expire_prompt_lab_runs"("p_actor" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_finish_prompt_lab_reverse"("p_actor" "uuid", "p_request_id" "uuid", "p_prompt" "text", "p_error_code" "text", "p_cost_usd" numeric, "p_submitted" boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare req public.prompt_lab_reverse_requests; n integer;
begin
  perform admin.require_reference_admin(p_actor);
  if p_prompt is not null and (length(p_prompt) not between 1 and 32000 or length(btrim(p_prompt))=0)
    or p_cost_usd<0 or p_submitted is null then raise exception 'INVALID_INPUT'; end if;
  select * into req from public.prompt_lab_reverse_requests where id=p_request_id;
  if not found or req.created_by is distinct from p_actor then raise exception 'PROMPT_REQUEST_NOT_FOUND'; end if;
  perform 1 from public.prompt_lab_sessions where id=req.session_id for update;
  select * into req from public.prompt_lab_reverse_requests where id=p_request_id for update;
  if not found then raise exception 'PROMPT_REQUEST_NOT_FOUND'; end if;
  if req.status='running' or req.error_code='TIMEOUT' then
    if p_prompt is not null then
      select coalesce(max(version_no),0)+1 into n from public.prompt_lab_versions where session_id=req.session_id;
      insert into public.prompt_lab_versions(session_id,version_no,prompt,created_by) values(req.session_id,n,p_prompt,p_actor)
        returning id into req.version_id;
      update public.prompt_lab_sessions set updated_at=now() where id=req.session_id;
    end if;
    req.status:=case when p_prompt is null then 'failed' else 'succeeded' end;
    update public.prompt_lab_reverse_requests set status=req.status,version_id=req.version_id,
      error_code=case when req.status='failed' then coalesce(p_error_code,'GENERATION_FAILED') end,finished_at=now() where id=req.id;
    update public.admin_test_spend set cost_usd=p_cost_usd,counted_usd=coalesce(p_cost_usd,
      case when p_submitted or p_prompt is not null then estimate_usd else 0 end),finished_at=now() where run_id=req.id;
  end if;
  return jsonb_build_object('status',req.status,'version_id',req.version_id);
end $$;


ALTER FUNCTION "public"."admin_finish_prompt_lab_reverse"("p_actor" "uuid", "p_request_id" "uuid", "p_prompt" "text", "p_error_code" "text", "p_cost_usd" numeric, "p_submitted" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_finish_prompt_lab_run"("p_actor" "uuid", "p_run_id" "uuid", "p_status" "text", "p_output_key" "text", "p_error_code" "text", "p_provider_usage" "jsonb", "p_cost_usd" numeric) RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare r public.prompt_lab_runs;
begin
  perform admin.require_reference_admin(p_actor);
  if p_status is null or p_status not in ('succeeded','failed') or (p_status='succeeded')<>(p_output_key is not null)
    or p_cost_usd<0 then raise exception 'INVALID_INPUT'; end if;
  select * into r from public.prompt_lab_runs where id=p_run_id for update;
  if not found then raise exception 'PROMPT_RUN_NOT_FOUND'; end if;
  if r.status in ('succeeded','failed') and r.error_code is distinct from 'TIMEOUT' then return; end if;
  if r.claimed_at is null then raise exception 'PROMPT_RUN_NOT_CLAIMED'; end if;
  update public.prompt_lab_runs set status=p_status,output_key=p_output_key,
    error_code=case when p_status='failed' then coalesce(p_error_code,'GENERATION_FAILED') end,
    cost_usd=p_cost_usd,finished_at=now() where id=p_run_id;
  update public.admin_test_spend set cost_usd=p_cost_usd,counted_usd=coalesce(p_cost_usd,
    case when p_status='failed' and p_error_code='PREPARE_FAILED' and not coalesce(p_provider_usage ?| array['output_tokens','completion_tokens','cost'],false) then 0 else estimate_usd end),
    has_openrouter=coalesce(p_provider_usage ?| array['cost','prompt_tokens','completion_tokens'],false),finished_at=now()
  where run_id=p_run_id;
end $$;


ALTER FUNCTION "public"."admin_finish_prompt_lab_run"("p_actor" "uuid", "p_run_id" "uuid", "p_status" "text", "p_output_key" "text", "p_error_code" "text", "p_provider_usage" "jsonb", "p_cost_usd" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_finish_test_run"("p_run_id" "uuid", "p_status" "text", "p_output_key" "text", "p_error_code" "text", "p_provider_usage" "jsonb", "p_cost_usd" numeric, "p_duration_ms" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  v_row public.admin_test_runs;
begin
  if p_status is null or p_status not in ('succeeded', 'failed') then
    raise exception 'INVALID_INPUT' using detail = 'status must be succeeded or failed';
  end if;
  if p_status = 'succeeded' and p_output_key is null then
    raise exception 'INVALID_INPUT' using detail = 'a succeeded run needs its output';
  end if;

  update public.admin_test_runs r
     set status = p_status,
         output_key = case when p_status = 'succeeded' then p_output_key end,
         error_code = case when p_status = 'failed' then coalesce(p_error_code, 'GENERATION_FAILED') end,
         provider_usage = p_provider_usage,
         cost_usd = p_cost_usd,
         duration_ms = p_duration_ms,
         finished_at = now()
   where r.id = p_run_id and r.status = 'running'
  returning * into v_row;

  if v_row.id is null then
    select * into v_row from public.admin_test_runs r where r.id = p_run_id;
    if not found then
      raise exception 'TEST_RUN_NOT_FOUND';
    end if;
    return to_jsonb(v_row);
  end if;

  update public.admin_test_spend x
     set cost_usd = p_cost_usd,
         counted_usd = coalesce(
           p_cost_usd,
           case when p_status = 'succeeded' or p_provider_usage ?| array['output_tokens', 'completion_tokens', 'cost'] then x.estimate_usd else 0 end
         ),
         finished_at = now()
   where x.run_id = p_run_id;
  return to_jsonb(v_row);
end;
$$;


ALTER FUNCTION "public"."admin_finish_test_run"("p_run_id" "uuid", "p_status" "text", "p_output_key" "text", "p_error_code" "text", "p_provider_usage" "jsonb", "p_cost_usd" numeric, "p_duration_ms" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_get_dispute"("p_dispute_id" "text") RETURNS TABLE("stripe_dispute_id" "text", "stripe_charge_id" "text", "payment_id" bigint, "user_id" "uuid", "email" "text", "product_id" "text", "amount" integer, "currency" "text", "reason" "text", "responder" "text", "due_by" timestamp with time zone, "auto_banned_at" timestamp with time zone, "evidence_drafted_at" timestamp with time zone, "submitted_at" timestamp with time zone, "reminded_at" timestamp with time zone, "created_at" timestamp with time zone)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select d.stripe_dispute_id, d.stripe_charge_id, d.payment_id, d.user_id, coalesce(nullif(u.email::text, ''), nullif(u.phone::text, '')),
         p.product_id, d.amount, d.currency, d.reason, d.responder, d.due_by,
         d.auto_banned_at, d.evidence_drafted_at, d.submitted_at, d.reminded_at, d.created_at
    from public.payment_disputes d
    left join auth.users u on u.id = d.user_id
    left join public.payments p on p.id = d.payment_id
   where d.stripe_dispute_id = p_dispute_id;
$$;


ALTER FUNCTION "public"."admin_get_dispute"("p_dispute_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_growth_stats"("p_start" timestamp with time zone, "p_end" timestamp with time zone, "p_prev_start" timestamp with time zone, "p_prev_end" timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if p_start is null or p_end is null or p_prev_start is null or p_prev_end is null
     or p_start >= p_end or p_prev_start >= p_prev_end or p_prev_end > p_start
     or p_end - p_start > interval '31 days' or p_prev_end - p_prev_start > interval '31 days'
     or p_end > now() + interval '5 minutes' then
    raise exception 'INVALID_INPUT' using detail = 'two ordered periods of at most 31 days, not in the future';
  end if;

  return (
    with periods(key, since, until) as (
      values ('current', p_start, p_end), ('previous', p_prev_start, p_prev_end)
    ),
    people as (
      select pr.id, pr.created_at, pr.referred_by is not null as referred
        from public.profiles pr
       where pr.role <> 'admin'
    ),
    pays as (
      select pm.user_id, pm.created_at, pm.channel, pm.product_id like 'pack\_%' as is_pack,
             pe.created_at as signed_at, pe.referred, pm.currency = 'usd' as usd,
             -- Kept, pre-tax: a refund returns its share of the tax (1181 uses the same formula).
             case when pm.currency = 'usd' and pm.amount_total > 0
                  then round((pm.amount_total - pm.amount_refunded)::numeric * (pm.amount_total - pm.amount_tax) / pm.amount_total)
                  else 0 end as net_cents,
             case when pm.currency = 'usd' and pm.amount_total > 0
                  then round((pm.amount_total - pm.amount_refunded)::numeric * pm.amount_tax / pm.amount_total)
                  else 0 end as tax_cents,
             case when pm.currency = 'usd' and pm.amount_total > 0
                  then round(pm.amount_refunded::numeric * (pm.amount_total - pm.amount_tax) / pm.amount_total)
                  else 0 end as refunded_cents,
             pm.amount_refunded > 0 as refunded_any,
             case
               when (pm.channel = 'stripe' and pm.stripe_session_id is null)
                 or (pm.channel = 'waffo' and exists (
                       select from public.payments e
                        where e.waffo_order_id = pm.waffo_order_id and (e.created_at, e.id) < (pm.created_at, pm.id)))
                 then 'renewal'
               when exists (
                       select from public.payments e
                        where e.user_id = pm.user_id and (e.created_at, e.id) < (pm.created_at, pm.id))
                 then 'repeat'
               else 'first'
             end as kind
        from public.payments pm
        join people pe on pe.id = pm.user_id
       where pm.created_at >= p_prev_start and pm.created_at < p_end
    )
    select jsonb_build_object(
             'timezone', 'Asia/Shanghai',
             'admin_ids', coalesce((select jsonb_agg(pr.id order by pr.id) from public.profiles pr where pr.role = 'admin'), '[]'::jsonb),
             'periods', jsonb_object_agg(p.key, s.stats)
           )
      from periods p
     cross join lateral (
       with cohort as (
         select pe.id, pe.referred,
                exists (select from public.generation_jobs g
                         where g.user_id = pe.id and g.status = 'succeeded'
                           and g.created_at >= pe.created_at and g.created_at < p.until) as imaged,
                exists (select from public.payments pm
                         where pm.user_id = pe.id and pm.created_at >= pe.created_at and pm.created_at < p.until) as paid
           from people pe
          where pe.created_at >= p.since and pe.created_at < p.until
       ),
       orders as (
         select x.* from pays x where x.created_at >= p.since and x.created_at < p.until
       ),
       buyers as (
         select o.user_id, sum(o.net_cents) as net_cents, count(*) as orders,
                bool_or(o.referred) as referred, min(o.signed_at) as signed_at
           from orders o
          group by o.user_id
       )
       select jsonb_build_object(
         'since', p.since,
         'until', p.until,
         'signups', (select count(*) from cohort),
         'new_users', (select jsonb_build_object('first_image', count(*) filter (where c.imaged),
                                                 'paid', count(*) filter (where c.paid)) from cohort c),
         'returning', jsonb_build_object(
           'active', (select count(distinct g.user_id)
                        from public.generation_jobs g
                        join people pe on pe.id = g.user_id
                       where g.created_at >= p.since and g.created_at < p.until
                         and g.status = 'succeeded' and pe.created_at < p.since),
           'paid', (select count(*) from buyers b where b.signed_at < p.since)),
         'payers', (select count(*) from buyers),
         'orders', (select jsonb_build_object(
                      'total', count(*),
                      'first', count(*) filter (where o.kind = 'first'),
                      'repeat', count(*) filter (where o.kind = 'repeat'),
                      'renewal', count(*) filter (where o.kind = 'renewal'),
                      'non_usd', count(*) filter (where not o.usd)) from orders o),
         'money', (select jsonb_build_object(
                     'net_usd', coalesce(sum(o.net_cents), 0) / 100.0,
                     'tax_usd', coalesce(sum(o.tax_cents), 0) / 100.0,
                     'refunded_usd', coalesce(sum(o.refunded_cents), 0) / 100.0) from orders o),
         'by_kind', (select jsonb_build_object(
                       'first', coalesce(sum(o.net_cents) filter (where o.kind = 'first'), 0) / 100.0,
                       'repeat', coalesce(sum(o.net_cents) filter (where o.kind = 'repeat'), 0) / 100.0,
                       'renewal', coalesce(sum(o.net_cents) filter (where o.kind = 'renewal'), 0) / 100.0) from orders o),
         'by_type', (select jsonb_build_object(
                       'plan', jsonb_build_object('orders', count(*) filter (where not o.is_pack),
                                                  'net_usd', coalesce(sum(o.net_cents) filter (where not o.is_pack), 0) / 100.0),
                       'pack', jsonb_build_object('orders', count(*) filter (where o.is_pack),
                                                  'net_usd', coalesce(sum(o.net_cents) filter (where o.is_pack), 0) / 100.0)) from orders o),
         'by_channel', (select jsonb_build_object(
                          'stripe', jsonb_build_object('orders', count(*) filter (where o.channel = 'stripe'),
                                                       'net_usd', coalesce(sum(o.net_cents) filter (where o.channel = 'stripe'), 0) / 100.0),
                          'waffo', jsonb_build_object('orders', count(*) filter (where o.channel = 'waffo'),
                                                      'net_usd', coalesce(sum(o.net_cents) filter (where o.channel = 'waffo'), 0) / 100.0)) from orders o),
         'refunds', (select jsonb_build_object('count', count(*) filter (where o.refunded_any),
                                               'usd', coalesce(sum(o.refunded_cents), 0) / 100.0) from orders o),
         'disputes', (select jsonb_build_object('count', count(*),
                                                'usd', coalesce(sum(d.amount) filter (where d.currency = 'usd'), 0) / 100.0)
                        from public.payment_disputes d
                       where d.created_at >= p.since and d.created_at < p.until
                         and (d.user_id is null or exists (select from people pe where pe.id = d.user_id))),
         'affiliate', jsonb_build_object(
           'signups', (select count(*) from cohort c where c.referred),
           'payers', (select count(*) from buyers b where b.referred),
           'net_usd', (select coalesce(sum(b.net_cents), 0) / 100.0 from buyers b where b.referred)),
         'cohort', (select coalesce(jsonb_agg(c.id order by c.id), '[]'::jsonb) from cohort c),
         'cohort_referred', (select coalesce(jsonb_agg(c.id order by c.id), '[]'::jsonb) from cohort c where c.referred),
         'buyers', (select coalesce(jsonb_agg(jsonb_build_object('user_id', b.user_id, 'net_usd', b.net_cents / 100.0,
                                                                 'orders', b.orders, 'referred', b.referred) order by b.user_id), '[]'::jsonb)
                      from buyers b)
       ) as stats
     ) s
  );
end;
$$;


ALTER FUNCTION "public"."admin_growth_stats"("p_start" timestamp with time zone, "p_end" timestamp with time zone, "p_prev_start" timestamp with time zone, "p_prev_end" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_identity_judge_stats"("p_hours" integer) RETURNS TABLE("calls" integer, "refused" integer, "failed_open" integer)
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  select count(*)::integer as calls,
         (count(*) filter (where c.identity_swap))::integer as refused,
         (count(*) filter (where c.failed))::integer as failed_open
    from public.identity_judge_calls c
   where c.created_at > now() - make_interval(hours => least(greatest(coalesce(p_hours, 24), 1), 24))
$$;


ALTER FUNCTION "public"."admin_identity_judge_stats"("p_hours" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_identity_refusal_counts"("p_user_ids" "uuid"[]) RETURNS TABLE("user_id" "uuid", "total" integer, "last_24h" integer)
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
begin
  perform public.purge_identity_refusals();
  return query
  select r.user_id,
         count(*)::integer as total,
         (count(*) filter (where r.created_at > now() - interval '24 hours'))::integer as last_24h
    from public.identity_refusals r
   where r.user_id = any (p_user_ids[1:200])
     and r.created_at > now() - interval '90 days'
   group by r.user_id;
end;
$$;


ALTER FUNCTION "public"."admin_identity_refusal_counts"("p_user_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_image_pricing_catalog"("p_env_model" "text") RETURNS "jsonb"
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  select jsonb_build_object('version',case when admin.is_template_catalog_v2() then 'v2' else 'v1' end,
    'unit_price',admin.lowest_credit_price(),'tariffs',admin.template_catalog_minimums(),
    'providers',coalesce((select jsonb_agg(to_jsonb(p)||jsonb_build_object('approved',admin.template_approved_prices(p.provider_id))
      || case when p.is_active then jsonb_build_object('fallback_floors',(
        select jsonb_object_agg(quality,tiers) from (
          select quality,jsonb_object_agg(res,admin.fallback_route_floor(coalesce(p.provider_id::text,'env')||'/'||p.model,res,quality)) tiers
          from unnest(array['medium','high']) quality cross join unnest(array['1k','2k','3k']) res group by quality
        ) grouped)) else '{}'::jsonb end)
      from public.admin_image_provider_pricing(p_env_model) p),'[]'))
$$;


ALTER FUNCTION "public"."admin_image_pricing_catalog"("p_env_model" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_image_provider_pricing"("p_env_model" "text") RETURNS TABLE("provider_id" "uuid", "label" "text", "model" "text", "adapter" "text", "is_active" boolean, "capabilities" "jsonb", "resolutions" "text"[], "estimated_image_costs" "jsonb", "p95" "jsonb")
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  with samples as (
    select g.provider, coalesce(g.inputs->>'resolution', '1k') as resolution,
           percentile_cont(0.95) within group (order by g.cost_usd) as cost
      from public.generation_jobs g
     where g.created_at >= now() - interval '30 days'
       and coalesce(g.inputs->>'resolution', '1k') in ('1k','2k','3k')
       and g.status = 'succeeded' and g.cost_usd is not null
     group by 1, 2 having count(*) >= 10
  ), costs as (
    select provider, jsonb_object_agg(resolution, cost) as p95 from samples group by provider
  )
  select p.id, p.label, p.model, p.adapter, p.is_active, p.capabilities, p.resolutions,
         p.estimated_image_costs, coalesce(c.p95, '{}'::jsonb)
    from public.ai_providers p
    left join costs c on c.provider = p.id::text || '/' || p.model
   where p.module = 'image'
  union all
  select null::uuid, '环境默认'::text, p_env_model, 'openai_images'::text, true, '{}'::jsonb,
         array['1k', '2k', '3k'], '{}'::jsonb, coalesce(c.p95, '{}'::jsonb)
    from (values (1)) as fallback(dummy) left join costs c on c.provider = 'env/' || p_env_model
   where not exists (select 1 from public.ai_providers where module = 'image' and is_active)
   order by 2, 1
$$;


ALTER FUNCTION "public"."admin_image_provider_pricing"("p_env_model" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_import_template"("p_template" "jsonb", "p_prompt" "jsonb", "p_open_sale" boolean, "p_actor" "uuid" DEFAULT NULL::"uuid", "p_style_refs" "jsonb" DEFAULT NULL::"jsonb") RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare template_id text := p_template->>'id';
begin
  if p_open_sale is null then raise exception 'INVALID_INPUT'; end if;
  if not p_open_sale and coalesce((p_template->>'is_active')::boolean,
      (select t.is_active from public.templates t where t.id=template_id for update),false) then
    raise exception 'IMPORT_OPEN_SALE_REQUIRED';
  end if;
  if p_style_refs is null then
    perform public.admin_upsert_template(p_template,p_prompt);
  else
    perform public.admin_upsert_template(p_template,p_prompt,p_style_refs);
  end if;
  if p_open_sale then
    perform public.admin_set_template_sale(p_actor,template_id,true);
  elsif exists (select from public.templates t where t.id=template_id and t.is_active) then
    -- A concurrent importer may have created a live row after the initial lookup.
    -- Check the final state under the upsert's lock before committing.
    raise exception 'IMPORT_OPEN_SALE_REQUIRED';
  end if;
end;
$$;


ALTER FUNCTION "public"."admin_import_template"("p_template" "jsonb", "p_prompt" "jsonb", "p_open_sale" boolean, "p_actor" "uuid", "p_style_refs" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_list_codes"("p_actor" "uuid", "p_cursor" "jsonb" DEFAULT NULL::"jsonb", "p_kind" "text" DEFAULT NULL::"text", "p_code_id" "uuid" DEFAULT NULL::"uuid") RETURNS SETOF "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $$
begin
  if not exists (select 1 from public.profiles where id = p_actor and role = 'admin' and banned_at is null) then
    raise exception 'NOT_ADMIN';
  end if;
  if p_kind not in ('invite','campaign') then raise exception 'INVALID_INPUT'; end if;
  return query
    with page as materialized (
      select c.id, c.code, c.kind, c.owner_user_id, c.note, c.invitee_credits, c.invitee_pool,
        c.discount_percent, c.discount_products, c.discount_duration, c.discount_months,
        c.discount_valid_days, c.starts_at, c.expires_at, c.max_redemptions, c.redemption_count,
        c.active, c.new_users_only, c.created_at
      from public.codes c
      where (p_kind is null or c.kind = p_kind) and (p_code_id is null or c.id = p_code_id)
        and (p_cursor is null or (c.created_at,c.id) < ((p_cursor->>'created_at')::timestamptz,(p_cursor->>'id')::uuid))
      order by c.created_at desc, c.id desc limit 30
    )
    select to_jsonb(c) || stats.value from page c cross join lateral (
      with attributed as materialized (
        -- A campaign has direct evidence in payments.code_id (including a late duplicate).
        select p.user_id, p.currency, p.amount_total, p.amount_tax, p.amount_refunded, p.amount_discount
        from public.payments p where c.kind = 'campaign' and p.code_id = c.id
        union all
        -- The invite code refers the account. Each successful redemption matches a different user.
        select p.user_id, p.currency, p.amount_total, p.amount_tax, p.amount_refunded, p.amount_discount
        from public.code_redemptions r join public.payments p
          on p.user_id = r.user_id and p.created_at >= r.created_at
        where c.kind = 'invite' and r.code_id = c.id and r.status = 'ok'
      ),
      sums as (
        select lower(a.currency) as currency,
          sum(a.amount_total::bigint - a.amount_tax - a.amount_refunded) as net_amount,
          sum(a.amount_discount) as discount_amount from attributed a group by lower(a.currency)
      )
      select jsonb_build_object(
        'purchasers', (select count(distinct a.user_id) from attributed a),
        'amounts', coalesce((select jsonb_object_agg(s.currency,
          jsonb_build_object('net',s.net_amount,'discount',s.discount_amount)) from sums s), '{}'::jsonb)
      ) as value
    ) stats order by c.created_at desc, c.id desc;
end;
$$;


ALTER FUNCTION "public"."admin_list_codes"("p_actor" "uuid", "p_cursor" "jsonb", "p_kind" "text", "p_code_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_list_disputes"("p_cursor_at" timestamp with time zone, "p_cursor_id" "text", "p_limit" integer) RETURNS TABLE("stripe_dispute_id" "text", "stripe_charge_id" "text", "payment_id" bigint, "user_id" "uuid", "email" "text", "product_id" "text", "amount" integer, "currency" "text", "reason" "text", "responder" "text", "due_by" timestamp with time zone, "auto_banned_at" timestamp with time zone, "evidence_drafted_at" timestamp with time zone, "submitted_at" timestamp with time zone, "reminded_at" timestamp with time zone, "created_at" timestamp with time zone)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select d.stripe_dispute_id, d.stripe_charge_id, d.payment_id, d.user_id, coalesce(nullif(u.email::text, ''), nullif(u.phone::text, '')),
         p.product_id, d.amount, d.currency, d.reason, d.responder, d.due_by,
         d.auto_banned_at, d.evidence_drafted_at, d.submitted_at, d.reminded_at, d.created_at
    from public.payment_disputes d
    left join auth.users u on u.id = d.user_id
    left join public.payments p on p.id = d.payment_id
   where p_cursor_at is null or (d.created_at, d.stripe_dispute_id) < (p_cursor_at, p_cursor_id)
   order by d.created_at desc, d.stripe_dispute_id desc
   limit least(greatest(coalesce(p_limit, 30), 1), 50);
$$;


ALTER FUNCTION "public"."admin_list_disputes"("p_cursor_at" timestamp with time zone, "p_cursor_id" "text", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_list_template_requests"() RETURNS TABLE("id" "uuid", "email" "text", "description" "text", "image_keys" "text"[], "status" "text", "template_id" "text", "votes_count" integer, "created_at" timestamp with time zone)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select r.id, u.email::text, r.description, r.image_keys, r.status, r.template_id, r.votes_count, r.created_at
    from unnest(array['pending', 'live', 'shipped', 'rejected']) as s(status)
   cross join lateral (
           select t.id, t.user_id, t.description, t.image_keys, t.status, t.template_id, t.votes_count, t.created_at
             from public.template_requests t
            where t.status = s.status
            order by t.created_at desc
            limit 500
         ) r
    left join auth.users u on u.id = r.user_id
   order by r.created_at desc;
$$;


ALTER FUNCTION "public"."admin_list_template_requests"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_list_tickets"("p_status" "text", "p_type" "text", "p_cursor_at" timestamp with time zone, "p_cursor_id" "uuid", "p_limit" integer) RETURNS TABLE("id" "uuid", "user_id" "uuid", "email" "text", "type" "text", "status" "text", "payment_id" bigint, "job_id" "uuid", "refund_decision" "text", "created_at" timestamp with time zone, "last_message_at" timestamp with time zone, "preview" "text", "tier" "text", "due_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if p_status is not null and p_status not in ('open', 'replied', 'closed') then
    raise exception 'INVALID_INPUT' using detail = 'unknown status';
  end if;
  if p_type is not null and p_type not in ('feedback', 'image_issue', 'billing', 'refund', 'account', 'other') then
    raise exception 'INVALID_INPUT' using detail = 'unknown ticket type';
  end if;
  if p_limit is null or p_limit not between 1 and 101 then
    raise exception 'INVALID_INPUT' using detail = 'p_limit must be between 1 and 101';
  end if;

  if p_status = 'open' then
    return query
      with open_rows as (
        select t.id, t.user_id, t.type, t.status, t.payment_id, t.job_id, t.refund_decision,
               t.created_at, t.last_message_at, d.tier,
               coalesce(d.last_user_at, t.created_at) + make_interval(hours => public.support_reply_hours(d.tier)) as due_at
          from public.support_tickets t
          cross join lateral (
            select public.current_tier(t.user_id) as tier,
                   (select max(m.created_at) from public.support_ticket_messages m
                     where m.ticket_id = t.id and m.author = 'user') as last_user_at
          ) d
         where t.status = 'open'
           and (p_type is null or t.type = p_type)
      )
      select r.id, r.user_id, u.email::text, r.type, r.status, r.payment_id, r.job_id, r.refund_decision,
             r.created_at, r.last_message_at, f.preview, r.tier, r.due_at
        from open_rows r
        left join auth.users u on u.id = r.user_id
        left join lateral (
          select left(m.body, 140) as preview from public.support_ticket_messages m
           where m.ticket_id = r.id order by m.created_at limit 1
        ) f on true
       where p_cursor_at is null or (r.due_at, r.id) > (p_cursor_at, p_cursor_id)
       order by r.due_at, r.id
       limit p_limit;
  else
    return query
      select t.id, t.user_id, u.email::text, t.type, t.status, t.payment_id, t.job_id, t.refund_decision,
             t.created_at, t.last_message_at, f.preview, d.tier,
             coalesce(d.last_user_at, t.created_at) + make_interval(hours => public.support_reply_hours(d.tier))
        from public.support_tickets t
        left join auth.users u on u.id = t.user_id
        cross join lateral (
          select public.current_tier(t.user_id) as tier,
                 (select max(m.created_at) from public.support_ticket_messages m
                   where m.ticket_id = t.id and m.author = 'user') as last_user_at
        ) d
        left join lateral (
          select left(m.body, 140) as preview from public.support_ticket_messages m
           where m.ticket_id = t.id order by m.created_at limit 1
        ) f on true
       where (p_status is null or t.status = p_status)
         and (p_type is null or t.type = p_type)
         and (p_cursor_at is null or (t.last_message_at, t.id) < (p_cursor_at, p_cursor_id))
       order by t.last_message_at desc, t.id desc
       limit p_limit;
  end if;
end;
$$;


ALTER FUNCTION "public"."admin_list_tickets"("p_status" "text", "p_type" "text", "p_cursor_at" timestamp with time zone, "p_cursor_id" "uuid", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_list_users"("p_query" "text" DEFAULT NULL::"text", "p_tier" "text" DEFAULT NULL::"text", "p_provider" "text" DEFAULT NULL::"text", "p_status" "text" DEFAULT NULL::"text", "p_from" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_to" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_sort" "text" DEFAULT 'created'::"text", "p_page" integer DEFAULT 1) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  v_q text := nullif(btrim(coalesce(p_query, '')), '');
  v_like text;
  v_digits text;
  v_where text := 'true';
  v_from text := 'public.profiles p';
  v_order text := 'p.created_at desc, p.id desc';
  v_total bigint;
  v_ids uuid[];
begin
  if p_tier is not null and p_tier not in ('free', 'starter', 'pro', 'max') then
    raise exception 'INVALID_INPUT' using detail = 'tier must be free, starter, pro or max';
  end if;
  if p_provider is not null and p_provider not in ('email', 'google', 'phone') then
    raise exception 'INVALID_INPUT' using detail = 'provider must be email, google or phone';
  end if;
  if p_status is not null and p_status not in ('active', 'banned') then
    raise exception 'INVALID_INPUT' using detail = 'status must be active or banned';
  end if;
  if p_sort is null or p_sort not in ('created', 'last_job', 'paid_credits') then
    raise exception 'INVALID_INPUT' using detail = 'sort must be created, last_job or paid_credits';
  end if;
  if p_page is null or p_page < 1 or p_page > 10000 then
    raise exception 'INVALID_INPUT' using detail = 'page must be between 1 and 10000';
  end if;
  if length(v_q) > 320 then
    raise exception 'INVALID_INPUT' using detail = 'query is too long';
  end if;

  -- The lookup box's substring rules (admin_search_users, 0442): % and _ match themselves; a
  -- query of digits, spaces, dashes and a leading + with at least 4 digits also matches the phone.
  if v_q is not null then
    v_like := '%' || replace(replace(replace(v_q, '\', '\\'), '%', '\%'), '_', '\_') || '%';
    if v_q ~ '^\+?[0-9][0-9 -]{2,}$' and length(regexp_replace(v_q, '[^0-9]', '', 'g')) >= 4 then
      v_digits := regexp_replace(v_q, '[^0-9]', '', 'g');
    end if;
  end if;

  -- Parameters: $1 email pattern, $2 phone digits, $3 sign-up method, $4 from, $5 to, $6 tier,
  -- $7 offset. The method is the one the account signed up with; linking Google later does not
  -- change it.
  if v_q is not null or p_provider is not null then
    v_where := v_where || ' and exists (select 1 from auth.users u where u.id = p.id'
      || case when v_q is null then ''
              when v_digits is null then ' and u.email ilike $1'
              else ' and (u.email ilike $1 or u.phone like ''%'' || $2 || ''%'')' end
      || case when p_provider is null then '' else ' and u.raw_app_meta_data ->> ''provider'' = $3' end
      || ')';
  end if;
  if p_status = 'banned' then
    v_where := v_where || ' and p.banned_at is not null';
  elsif p_status = 'active' then
    v_where := v_where || ' and p.banned_at is null';
  end if;
  if p_from is not null then
    v_where := v_where || ' and p.created_at >= $4';
  end if;
  if p_to is not null then
    v_where := v_where || ' and p.created_at < $5';
  end if;
  if p_tier is not null then
    v_where := v_where || ' and coalesce(public.current_tier(p.id), ''free'') = $6';
  end if;

  execute 'select count(*) from public.profiles p where ' || v_where
    into v_total
    using v_like, v_digits, p_provider, p_from, p_to, p_tier;

  if p_sort = 'last_job' then
    v_from := v_from || ' left join lateral (select g.created_at from public.generation_jobs g '
      || 'where g.user_id = p.id order by g.created_at desc limit 1) j on true';
    v_order := 'j.created_at desc nulls last, p.created_at desc, p.id desc';
  elsif p_sort = 'paid_credits' then
    v_order := 'p.credits desc, p.created_at desc, p.id desc';
  end if;

  -- ARRAY(subquery) keeps the subquery's order.
  execute 'select array(select p.id from ' || v_from || ' where ' || v_where
      || ' order by ' || v_order || ' limit 50 offset $7)'
    into v_ids
    using v_like, v_digits, p_provider, p_from, p_to, p_tier, (p_page - 1) * 50;

  -- The 50 rows of the page, each joined by primary key.
  return jsonb_build_object(
    'total', v_total,
    'rows', coalesce((
      select jsonb_agg(jsonb_build_object(
               'id', p.id,
               'email', u.email::text,
               'phone', nullif(u.phone, '')::text,
               'created_at', p.created_at,
               'provider', u.raw_app_meta_data ->> 'provider',
               'role', p.role,
               'credits', p.credits,
               'free_credits', p.free_credits,
               'paid_until', p.paid_until,
               'tier', coalesce(plan.tier, 'free'),
               'product_id', plan.product_id,
               'last_generation_at', j.created_at,
               'banned_at', p.banned_at
             ) order by ids.n)
        from unnest(v_ids) with ordinality as ids(id, n)
        join public.profiles p on p.id = ids.id
        join auth.users u on u.id = p.id
        left join lateral (
          select l.product_id, c.tier
            from public.credit_ledger l join admin.catalog_products c on c.product_id=l.product_id
           where p.paid_until > now()
             and l.user_id = p.id and l.pool = 'paid' and l.delta > 0
             and l.product_id is not null and not starts_with(l.product_id,'pack_') and c.kind<>'pack'
           order by l.created_at desc, l.id desc
           limit 1
        ) plan on true
        left join lateral (
          select g.created_at
            from public.generation_jobs g
           where g.user_id = p.id
           order by g.created_at desc
           limit 1
        ) j on true
    ), '[]'::jsonb)
  );
end;
$_$;


ALTER FUNCTION "public"."admin_list_users"("p_query" "text", "p_tier" "text", "p_provider" "text", "p_status" "text", "p_from" timestamp with time zone, "p_to" timestamp with time zone, "p_sort" "text", "p_page" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_log_replay"("p_user_id" "uuid", "p_target_id" "text", "p_reason" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if p_user_id is null or p_target_id is null or p_target_id !~ '^(cs|sub)_'
     or p_reason is null or length(btrim(p_reason)) = 0 then
    raise exception 'INVALID_INPUT' using detail = 'user, a cs_/sub_ target and a reason are required';
  end if;

  insert into public.admin_audit_log (action, user_id, target_id, reason)
  values ('replay_checkout', p_user_id, p_target_id, p_reason);
end;
$$;


ALTER FUNCTION "public"."admin_log_replay"("p_user_id" "uuid", "p_target_id" "text", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_lookup"("p_query" "text") RETURNS TABLE("kind" "text", "user_id" "uuid", "job_id" "uuid")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  v_q text := btrim(coalesce(p_query, ''));
  v_users uuid[];
begin
  if length(v_q) = 0 or length(v_q) > 320 then
    return;
  end if;

  if v_q ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
    return query select 'user'::text, p.id, null::uuid from public.profiles p where p.id = v_q::uuid;
    if found then return; end if;
    return query select 'job'::text, j.user_id, j.id from public.generation_jobs j where j.id = v_q::uuid;
    return;
  end if;

  if v_q like 'cs\_%' then
    return query select 'checkout'::text, pay.user_id, null::uuid from public.payments pay where pay.stripe_session_id = v_q;
    if found then return; end if;
    return query select 'checkout'::text, l.user_id, null::uuid from public.credit_ledger l where l.idempotency_key = 'purchase:' || v_q;
    return;
  end if;

  if v_q like 'in\_%' then
    return query select 'invoice'::text, pay.user_id, null::uuid from public.payments pay where pay.stripe_invoice_id = v_q;
    if found then return; end if;
    return query select 'invoice'::text, l.user_id, null::uuid from public.credit_ledger l where l.idempotency_key = 'renewal:' || v_q;
    return;
  end if;

  if v_q ~ '^(ch|py)_' then
    return query select 'charge'::text, pay.user_id, null::uuid from public.payments pay where pay.stripe_charge_id = v_q;
    return;
  end if;

  if v_q like 'sub\_%' then
    return query select 'subscription'::text, s.user_id, null::uuid from public.subscriptions s where s.stripe_subscription_id = v_q;
    return;
  end if;

  return query select 'waffo'::text, pay.user_id, null::uuid from public.payments pay where pay.waffo_order_id = v_q;
  if found then return; end if;
  return query select 'waffo'::text, l.user_id, null::uuid from public.credit_ledger l where l.idempotency_key = 'purchase:' || v_q;
  if found then return; end if;

  -- The query is a literal substring: % and _ typed by the admin match themselves.
  select array_agg(u.id) into v_users
    from (select au.id from auth.users au
           where au.email ilike '%' || replace(replace(replace(v_q, '\', '\\'), '%', '\%'), '_', '\_') || '%'
           limit 2) u;
  if cardinality(v_users) = 1 then
    return query select 'email'::text, v_users[1], null::uuid;
  end if;
end;
$_$;


ALTER FUNCTION "public"."admin_lookup"("p_query" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_manage_prompt_version"("p_actor" "uuid", "p_id" "text", "p_version" integer, "p_action" "text", "p_name" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare active int;
begin
  if not exists(select from public.profiles where id=p_actor and role='admin' and banned_at is null) then raise exception 'FORBIDDEN'; end if;
  perform 1 from public.templates where id=p_id for update;
  select version into active from public.template_prompts where template_id=p_id for update;
  if p_action='rename' and length(coalesce(p_name,''))<=80 then
    update public.template_prompt_versions set display_name=nullif(trim(p_name),'') where template_id=p_id and version=p_version;
  elsif p_action='delete' then
    if active=p_version then raise exception 'ACTIVE_VERSION'; end if;
    delete from public.template_prompt_versions where template_id=p_id and version=p_version;
    if found then
      insert into admin.deleted_prompt_versions(template_id,version,actor_id) values(p_id,p_version,p_actor);
      return;
    end if;
  else raise exception 'INVALID_INPUT'; end if;
  if not found then raise exception 'VERSION_NOT_FOUND'; end if;
end;
$$;


ALTER FUNCTION "public"."admin_manage_prompt_version"("p_actor" "uuid", "p_id" "text", "p_version" integer, "p_action" "text", "p_name" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_mark_dispute_submitted"("p_dispute_id" "text", "p_actor" "uuid") RETURNS timestamp with time zone
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_row public.payment_disputes;
begin
  if p_actor is null or not exists (select 1 from public.profiles where id = p_actor and role = 'admin') then
    raise exception 'NOT_ADMIN';
  end if;

  select * into v_row from public.payment_disputes where stripe_dispute_id = p_dispute_id for update;
  if not found then
    raise exception 'DISPUTE_NOT_FOUND';
  end if;
  if v_row.responder <> 'shotviva' then
    raise exception 'DISPUTE_NOT_OURS' using detail = 'Stripe answers Managed Payments disputes';
  end if;
  if v_row.submitted_at is not null then
    raise exception 'DISPUTE_ALREADY_SUBMITTED';
  end if;

  update public.payment_disputes set submitted_at = now(), submitted_by = p_actor
   where stripe_dispute_id = p_dispute_id
  returning * into v_row;

  insert into public.admin_audit_log (action, user_id, reason, target_id)
  values ('submit_dispute', coalesce(v_row.user_id, p_actor), '提交拒付申诉证据 · 操作人 ' || p_actor::text, p_dispute_id);
  return v_row.submitted_at;
end;
$$;


ALTER FUNCTION "public"."admin_mark_dispute_submitted"("p_dispute_id" "text", "p_actor" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_mark_prompt_lab_run"("p_actor" "uuid", "p_session_id" "uuid", "p_run_id" "uuid", "p_starred" boolean, "p_is_best" boolean) RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
begin
  perform admin.require_reference_admin(p_actor);
  perform admin.lock_prompt_lab(p_session_id);
  perform 1 from public.prompt_lab_runs where id=p_run_id and session_id=p_session_id and status='succeeded' for update;
  if not found then raise exception 'PROMPT_RUN_NOT_FOUND'; end if;
  if p_is_best then update public.prompt_lab_runs set is_best=false where session_id=p_session_id and is_best and id<>p_run_id; end if;
  update public.prompt_lab_runs set starred=coalesce(p_starred,starred),is_best=coalesce(p_is_best,is_best) where id=p_run_id;
end $$;


ALTER FUNCTION "public"."admin_mark_prompt_lab_run"("p_actor" "uuid", "p_session_id" "uuid", "p_run_id" "uuid", "p_starred" boolean, "p_is_best" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_moderate_works"("p_actor" "uuid", "p_job_ids" "uuid"[], "p_decision" "text", "p_reason" "text") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_ids uuid[];
begin
  if p_actor is null or not exists (
      select 1 from public.profiles p where p.id = p_actor and p.role = 'admin' and p.banned_at is null) then
    raise exception 'NOT_ADMIN';
  end if;
  if p_job_ids is null or cardinality(p_job_ids) not between 1 and 50 then
    raise exception 'INVALID_INPUT' using detail = 'between 1 and 50 works';
  end if;
  if p_decision is null or p_decision not in ('approved', 'rejected') then
    raise exception 'INVALID_INPUT' using detail = 'decision must be approved or rejected';
  end if;
  if p_decision = 'rejected' and (p_reason is null or p_reason not in
      ('sexual', 'violence', 'hate', 'minor', 'privacy', 'ip', 'spam', 'quality', 'other')) then
    raise exception 'INVALID_INPUT' using detail = 'a rejection needs a reason';
  end if;

  with changed as (
    update public.generation_jobs j
       set moderation_status = p_decision,
           moderation_reason = case when p_decision = 'rejected' then p_reason end,
           -- Keeping an approved work (e.g. after a report) keeps its place in the gallery.
           moderated_at = case when j.moderation_status = p_decision then j.moderated_at else now() end,
           moderated_by = p_actor
     where j.id = any (p_job_ids) and j.status = 'succeeded' and j.visibility = 'public' and j.deleted_at is null
    returning j.id
  )
  select coalesce(array_agg(id), '{}') into v_ids from changed;

  update public.work_reports r set resolved_at = now()
   where r.job_id = any (v_ids) and r.resolved_at is null;

  insert into public.admin_audit_log (action, user_id, reason, target_id)
  select 'moderate_work', p_actor, p_decision || coalesce(':' || case when p_decision = 'rejected' then p_reason end, ''), id::text
    from unnest(v_ids) as id;

  return cardinality(v_ids);
end;
$$;


ALTER FUNCTION "public"."admin_moderate_works"("p_actor" "uuid", "p_job_ids" "uuid"[], "p_decision" "text", "p_reason" "text") OWNER TO "postgres";


