ALTER FUNCTION "public"."admin_reserve_reference_upload"("p_actor" "uuid", "p_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_resolve_waffo_renewal"("p_actor" "uuid", "p_ticket" "uuid", "p_decision" "text", "p_total_usd_cents" integer, "p_tax_usd_cents" integer) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  r admin.waffo_renewal_periods;
  v_change public.credit_change;
  v_payment bigint;
  v_body text;
begin
  if not exists(select from public.profiles where id=p_actor and role='admin' and banned_at is null) then
    raise exception 'FORBIDDEN';
  end if;
  if p_decision is null or p_decision not in ('settled','refunded') then raise exception 'INVALID_INPUT'; end if;
  if p_decision='refunded' and (p_total_usd_cents is not null or p_tax_usd_cents is not null) then
    raise exception 'INVALID_INPUT';
  end if;
  select * into r from admin.waffo_renewal_periods where ticket_id=p_ticket or resolved_ticket_id=p_ticket;
  if not found then raise exception 'TICKET_NOT_FOUND'; end if;
  perform pg_advisory_xact_lock(hashtextextended('waffo-renewal:' || r.order_id || ':' || r.period_number,0));
  select * into strict r from admin.waffo_renewal_periods where payment_id=r.payment_id for update;
  if r.resolution=p_decision then return; end if;
  if r.resolution is not null then raise exception 'CONFLICT'; end if;
  perform 1 from public.support_tickets where id=p_ticket and user_id=r.user_id and type='billing' for update;
  if not found then raise exception 'TICKET_NOT_FOUND'; end if;
  if p_decision='settled' then
    if p_total_usd_cents is null or p_tax_usd_cents is null or p_tax_usd_cents<0 or p_total_usd_cents<=p_tax_usd_cents then
      raise exception 'INVALID_INPUT';
    end if;
    -- Any payment already fulfilling this period prevents a second extension, even under another PAY.
    if exists(select from admin.waffo_renewal_periods other join public.payments p on p.waffo_payment_id=other.payment_id
      where other.order_id=r.order_id and other.period_number=r.period_number) then raise exception 'CONFLICT'; end if;
    v_change := public.settle_waffo_order_v2(r.user_id,r.product_id,r.payment_id,r.order_id,p_total_usd_cents,'usd',p_tax_usd_cents,'card');
    if not v_change.applied then raise exception 'CONFLICT'; end if;
    select id into strict v_payment from public.payments where waffo_payment_id=r.payment_id;
    v_body := E'已核对本期续费。积分已到账，会员有效期已更新。\nWe’ve verified your renewal, added your credits and updated your membership expiry.';
  else
    if exists(select from public.payments where waffo_payment_id=r.payment_id) then raise exception 'CONFLICT'; end if;
    v_body := E'已确认这笔续费扣款已退款。\nWe’ve confirmed that this renewal charge was refunded.';
  end if;
  update admin.waffo_renewal_periods set ticket_id=null,resolved_ticket_id=p_ticket,resolution=p_decision where payment_id=r.payment_id;
  update public.support_tickets set status='closed',closed_at=now(),last_message_at=now(),payment_id=v_payment where id=p_ticket;
  insert into public.support_ticket_messages(ticket_id,author,body) values(p_ticket,'admin',v_body);
  insert into public.admin_audit_log(action,user_id,target_id,reason) values('waffo_renewal_' || p_decision,r.user_id,p_ticket::text,
    jsonb_build_object('actor',p_actor,'order',r.order_id,'period',r.period_number,'payment',r.payment_id,
      'total_usd_cents',p_total_usd_cents,'tax_usd_cents',p_tax_usd_cents)::text);
end;
$$;


ALTER FUNCTION "public"."admin_resolve_waffo_renewal"("p_actor" "uuid", "p_ticket" "uuid", "p_decision" "text", "p_total_usd_cents" integer, "p_tax_usd_cents" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_revenue_stats"("p_days" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $$
declare
  v_tz constant text := 'Asia/Shanghai';
  v_today timestamptz;
  v_start timestamptz;
  v_result jsonb;
begin
  if p_days is null or p_days < 7 or p_days > 90 then
    raise exception 'INVALID_INPUT' using detail = 'p_days must be between 7 and 90';
  end if;

  v_today := date_trunc('day', now() at time zone v_tz) at time zone v_tz;
  v_start := v_today - make_interval(days => p_days - 1);

  with windows(key, since) as (
    values ('today', v_today), ('7d', v_today - interval '6 days'), ('period', v_start)
  ),
  purchases as (
    select pm.created_at,
           pm.product_id,
           pm.channel,
           case when pm.currency = 'usd' and pm.amount_total > 0
                then round((pm.amount_total - pm.amount_refunded)::numeric * (pm.amount_total - pm.amount_tax) / pm.amount_total) / 100.0
                else 0 end as amount
      from public.payments pm
     where pm.created_at >= v_start
  )
  select jsonb_build_object(
           'timezone', v_tz,
           'days', p_days,
           'generated_at', now(),
           'windows', (
             select jsonb_agg(jsonb_build_object(
                      'key', w.key,
                      'since', w.since,
                      'purchases', (select count(*) from purchases x where x.created_at >= w.since),
                      'revenue_usd', (select coalesce(sum(x.amount), 0) from purchases x where x.created_at >= w.since)
                    ) order by w.since desc)
               from windows w
           ),
           'by_product', coalesce((
             select jsonb_agg(jsonb_build_object(
                      'product_id', g.product_id, 'channel', g.channel,
                      'purchases', g.purchases, 'revenue_usd', g.revenue
                    ) order by g.revenue desc, g.product_id, g.channel)
               from (
                 select coalesce(x.product_id, 'unknown') as product_id, x.channel,
                        count(*) as purchases, sum(x.amount) as revenue
                   from purchases x
                  group by 1, 2
               ) g
           ), '[]'::jsonb),
           'trend', (
             select jsonb_agg(jsonb_build_object(
                      'day', to_char(d.day at time zone v_tz, 'YYYY-MM-DD'),
                      'revenue_usd', (select coalesce(sum(x.amount), 0) from purchases x
                                       where x.created_at >= d.day and x.created_at < d.day + interval '1 day')
                    ) order by d.day)
               from generate_series(v_start, v_today, interval '1 day') as d(day)
           ),
           'subscriptions', coalesce((
             select jsonb_object_agg(s.status, s.n)
               from (select status, count(*) as n from public.subscriptions group by status) s
           ), '{}'::jsonb)
         )
    into v_result;
  return v_result;
end;
$$;


ALTER FUNCTION "public"."admin_revenue_stats"("p_days" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_review_template_request"("p_request_id" "uuid", "p_status" "text", "p_template_id" "text" DEFAULT NULL::"text") RETURNS "text"[]
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_current text;
  v_keys text[];
begin
  select r.status, r.image_keys into v_current, v_keys
    from public.template_requests r
   where r.id = p_request_id
     for update;
  if not found then
    raise exception 'REQUEST_NOT_FOUND';
  end if;

  if not (
       (v_current = 'pending' and p_status in ('live', 'rejected'))
    or (v_current = 'live' and p_status in ('rejected', 'shipped'))
  ) then
    raise exception 'REQUEST_TRANSITION_INVALID'
      using detail = v_current || ' -> ' || coalesce(p_status, 'null');
  end if;

  if p_status = 'shipped' then
    perform 1 from public.templates t where t.id = p_template_id;
    if not found then
      raise exception 'TEMPLATE_NOT_FOUND';
    end if;
  end if;

  update public.template_requests
     set status = p_status,
         template_id = case when p_status = 'shipped' then p_template_id end,
         image_keys = case when p_status = 'rejected' then '{}'::text[] else image_keys end,
         reviewed_at = now()
   where id = p_request_id;

  if p_status = 'shipped' then
    insert into public.template_request_notices (user_id, request_id)
    select r.user_id, r.id from public.template_requests r where r.id = p_request_id
    union all
    select v.user_id, v.request_id from public.template_request_votes v where v.request_id = p_request_id
    on conflict (user_id, request_id) do nothing;
  end if;

  return case when p_status = 'rejected' then v_keys else '{}'::text[] end;
end;
$$;


ALTER FUNCTION "public"."admin_review_template_request"("p_request_id" "uuid", "p_status" "text", "p_template_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_save_code"("p_actor" "uuid", "p_code_id" "uuid", "p_fields" "jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  catalog jsonb;
  floor_id text;
begin
  if not exists (select 1 from public.profiles where id = p_actor and role = 'admin' and banned_at is null) then
    raise exception 'NOT_ADMIN';
  end if;
  select jsonb_agg(jsonb_build_object('id', p.id, 'priceCents', p.price_usd * 100,
                 'credits', p.credits, 'subscription', p.days is not null) order by p.id)
    into catalog from public.products p where p.active;
  select p.id into floor_id from public.products p where p.active and p.days is not null and
      not exists (select 1 from public.products s where s.active and s.days is not null and
                    s.price_usd * p.credits < p.price_usd * s.credits)
    order by p.id limit 1;
  return public.admin_save_code(p_actor, p_code_id, p_fields, catalog, floor_id);
end;
$$;


ALTER FUNCTION "public"."admin_save_code"("p_actor" "uuid", "p_code_id" "uuid", "p_fields" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_save_code"("p_actor" "uuid", "p_code_id" "uuid", "p_fields" "jsonb", "p_catalog" "jsonb", "p_floor_product_id" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_old public.codes;
  v_new public.codes;
begin
  if not exists (select 1 from public.profiles where id = p_actor and role = 'admin' and banned_at is null) then
    raise exception 'NOT_ADMIN';
  end if;
  if p_code_id is null or jsonb_typeof(p_fields) is distinct from 'object' or p_fields = '{}' or
     p_fields - array['code','note','invitee_credits','invitee_pool','discount_percent','discount_products',
       'discount_duration','discount_months','discount_valid_days','stripe_coupon_id','starts_at',
       'expires_at','max_redemptions','new_users_only','active'] <> '{}' then
    raise exception 'INVALID_INPUT';
  end if;
  -- A repeated create request can arrive before the first transaction has inserted its row.
  perform pg_advisory_xact_lock(hashtextextended('shotviva.admin_code:' || p_code_id::text, 0));
  select c.* into v_old from public.codes c where c.id = p_code_id for update;
  if v_old.id is not null and v_old.kind <> 'campaign' then raise exception 'INVALID_CODE_KIND'; end if;

  select * into v_new from jsonb_populate_record(v_old, p_fields);
  v_new.code := upper(v_new.code);
  if v_new.invitee_credits is not null then v_new.invitee_pool := coalesce(v_new.invitee_pool, 'free'); end if;

  -- Reject edits even if the new percentage would pass the floor: Stripe cannot mutate the coupon.
  if v_old.id is not null and
    row(v_new.discount_percent, v_new.discount_products, v_new.discount_duration, v_new.discount_months,
        v_new.discount_valid_days, v_new.stripe_coupon_id) is distinct from
    row(v_old.discount_percent, v_old.discount_products, v_old.discount_duration, v_old.discount_months,
        v_old.discount_valid_days, v_old.stripe_coupon_id) then
    raise exception 'CODE_DISCOUNT_IMMUTABLE';
  end if;
  if v_new.max_redemptions < coalesce(v_old.redemption_count, 0) then
    raise exception 'CODE_QUOTA_BELOW_CLAIMED';
  end if;
  -- Existing discount terms are immutable. Editing metadata must still work after a reprice.
  if v_old.id is null and v_new.discount_percent is not null then
    if nullif(btrim(v_new.stripe_coupon_id), '') is null or coalesce(cardinality(v_new.discount_products), 0) = 0 then
      raise exception 'INVALID_DISCOUNT';
    end if;
    perform public._validate_code_discount(v_new.discount_products, v_new.discount_percent, p_catalog, p_floor_product_id);
  end if;

  if v_old.id is not null and v_old is not distinct from v_new then return v_old.id; end if;
  if v_old.id is null then
    insert into public.codes(id, code, kind, note, invitee_credits, invitee_pool, discount_percent,
      discount_products, discount_duration, discount_months, discount_valid_days, stripe_coupon_id,
      starts_at, expires_at, max_redemptions, active, new_users_only, created_by)
    values (p_code_id, v_new.code, 'campaign', v_new.note, v_new.invitee_credits, v_new.invitee_pool,
      v_new.discount_percent, v_new.discount_products, v_new.discount_duration, v_new.discount_months,
      v_new.discount_valid_days, v_new.stripe_coupon_id, v_new.starts_at, v_new.expires_at,
      v_new.max_redemptions, coalesce(v_new.active,true), coalesce(v_new.new_users_only,false), p_actor);
  else
    update public.codes set code = v_new.code, note = v_new.note, invitee_credits = v_new.invitee_credits,
      invitee_pool = v_new.invitee_pool, starts_at = v_new.starts_at, expires_at = v_new.expires_at,
      max_redemptions = v_new.max_redemptions, active = v_new.active, new_users_only = v_new.new_users_only,
      updated_at = now() where id = p_code_id;
  end if;
  insert into public.admin_audit_log(action, user_id, target_id, reason)
  values ('save_code', p_actor, p_code_id::text, v_new.code);
  return p_code_id;
end;
$$;


ALTER FUNCTION "public"."admin_save_code"("p_actor" "uuid", "p_code_id" "uuid", "p_fields" "jsonb", "p_catalog" "jsonb", "p_floor_product_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_save_invite_rewards"("p_actor" "uuid", "p_invitee" integer, "p_inviter" integer, "p_expected" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  previous jsonb;
  updated jsonb := jsonb_build_object('inviteeCredits', p_invitee, 'inviterCredits', p_inviter);
begin
  if not exists (select 1 from public.profiles where id = p_actor and role = 'admin' and banned_at is null) then
    raise exception 'NOT_ADMIN';
  end if;
  if p_invitee is null or p_invitee not between 0 and 10000
     or p_inviter is null or p_inviter not between 0 and 10000 then raise exception 'INVALID_INPUT'; end if;
  select value into strict previous from public.system_settings where key = 'code_invite_rewards' for update;
  if previous is distinct from p_expected then raise exception 'INVITE_SETTINGS_CHANGED'; end if;
  if previous = updated then return; end if;
  update public.system_settings set value = updated, updated_at = now(), updated_by = p_actor
    where key = 'code_invite_rewards';
  insert into public.admin_audit_log(action, user_id, target_id, reason)
    values ('save_code', p_actor, 'code_invite_rewards', jsonb_build_object('before', previous, 'after', updated)::text);
end;
$$;


ALTER FUNCTION "public"."admin_save_invite_rewards"("p_actor" "uuid", "p_invitee" integer, "p_inviter" integer, "p_expected" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_save_prompt_lab_version"("p_actor" "uuid", "p_session_id" "uuid", "p_version_id" "uuid", "p_mode" "text", "p_prompt" "text", "p_note" "text") RETURNS "uuid"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare prev public.prompt_lab_versions; new_id uuid; n integer;
begin
  perform admin.require_reference_admin(p_actor);
  perform admin.lock_prompt_lab(p_session_id);
  if p_mode in ('edit','copy') then
    select * into prev from public.prompt_lab_versions where id=p_version_id and session_id=p_session_id;
    if not found then raise exception 'PROMPT_VERSION_NOT_FOUND'; end if;
  elsif p_mode is distinct from 'create' or p_version_id is not null then raise exception 'INVALID_INPUT';
  end if;
  if p_mode='copy' then
    p_prompt:=coalesce(p_prompt,prev.prompt);
    p_note:=coalesce(p_note,prev.note);
  end if;
  if p_prompt is null or length(btrim(p_prompt))=0 or length(p_prompt)>32000 or length(p_note)>2000 then raise exception 'INVALID_INPUT'; end if;
  update public.prompt_lab_sessions set updated_at=now() where id=p_session_id;
  if p_mode='edit' and not exists(select from public.prompt_lab_runs where version_id=p_version_id) then
    update public.prompt_lab_versions set prompt=p_prompt,note=p_note where id=p_version_id;
    return p_version_id;
  end if;
  select coalesce(max(version_no),0)+1 into n from public.prompt_lab_versions where session_id=p_session_id;
  insert into public.prompt_lab_versions(session_id,version_no,prompt,note,created_by)
    values(p_session_id,n,p_prompt,p_note,p_actor) returning id into new_id;
  return new_id;
end $$;


ALTER FUNCTION "public"."admin_save_prompt_lab_version"("p_actor" "uuid", "p_session_id" "uuid", "p_version_id" "uuid", "p_mode" "text", "p_prompt" "text", "p_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_save_provider"("p_actor" "uuid", "p_id" "uuid", "p_settings" "jsonb", "p_capabilities" "jsonb", "p_key" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_id uuid;
  v_tiers text[] := array(select jsonb_array_elements_text(p_capabilities->'resolutions'));
begin
  if not exists (select 1 from public.profiles where id=p_actor and role='admin' and banned_at is null) then
    raise exception 'ADMIN_REQUIRED' using errcode='42501';
  end if;
  if p_settings->>'module'='image' and (jsonb_typeof(p_capabilities->'originalRatio') is distinct from 'boolean'
     or jsonb_typeof(p_capabilities->'aspectRatios') is distinct from 'array'
     or jsonb_typeof(p_capabilities->'maxReferences') is distinct from 'number'
     or jsonb_typeof(p_capabilities->'minReferences') is distinct from 'number'
     or (p_capabilities->>'fetchedAt')::timestamptz is null) then
    raise exception 'INVALID_PROVIDER_CAPABILITIES' using errcode='23514';
  end if;
  if p_settings->>'module'='decision' then v_tiers := array['1k','2k','3k']; end if;
  if p_id is null then
    if p_key is null then raise exception 'PROVIDER_KEY_REQUIRED'; end if;
    insert into public.ai_providers (module,adapter,label,base_url,model,notes,updated_by,capabilities,resolutions,
      price_input_text_per_m,price_input_image_per_m,price_output_per_m,estimated_image_costs)
    values (p_settings->>'module',p_settings->>'adapter',p_settings->>'label',p_settings->>'base_url',p_settings->>'model',p_settings->>'notes',p_actor,
      p_capabilities,v_tiers,(p_settings->>'price_input_text_per_m')::numeric,(p_settings->>'price_input_image_per_m')::numeric,
      (p_settings->>'price_output_per_m')::numeric,coalesce(p_settings->'estimated_image_costs','{}')) returning id into v_id;
  else
    update public.ai_providers set label=p_settings->>'label',base_url=p_settings->>'base_url',model=p_settings->>'model',
      notes=p_settings->>'notes',updated_by=p_actor,capabilities=p_capabilities,resolutions=v_tiers,
      estimated_image_costs=coalesce(p_settings->'estimated_image_costs', case when model=p_settings->>'model' and base_url=p_settings->>'base_url' then estimated_image_costs else '{}'::jsonb end),
      price_input_text_per_m=(p_settings->>'price_input_text_per_m')::numeric,
      price_input_image_per_m=(p_settings->>'price_input_image_per_m')::numeric,price_output_per_m=(p_settings->>'price_output_per_m')::numeric
    where id=p_id and module=p_settings->>'module' and adapter=p_settings->>'adapter' returning id into v_id;
    if not found then raise exception 'PROVIDER_NOT_FOUND'; end if;
  end if;
  if p_key is not null then perform public.admin_set_provider_key(v_id,p_key); end if;
  return v_id;
end;
$$;


ALTER FUNCTION "public"."admin_save_provider"("p_actor" "uuid", "p_id" "uuid", "p_settings" "jsonb", "p_capabilities" "jsonb", "p_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_save_reference_category"("p_actor" "uuid", "p_key" "text", "p_name_en" "text", "p_name_zh" "text", "p_parent" "text", "p_is_new" boolean) RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare next_order integer;
begin
  perform admin.require_reference_admin(p_actor);
  perform pg_advisory_xact_lock(hashtextextended('shotviva.category_tree',0));
  if p_is_new is null then raise exception 'INVALID_INPUT'; end if;
  if p_is_new and exists(select from public.template_categories where key=p_key) then raise exception 'CATEGORY_KEY_TAKEN'; end if;
  if not p_is_new and not exists(select from public.template_categories where key=p_key and kind='reference') then
    raise exception 'CATEGORY_NOT_FOUND';
  end if;
  if exists(select from public.template_categories where name_en_lookup='reference:'||lower(btrim(p_name_en)) and key<>p_key)
    then raise exception 'CATEGORY_NAME_EN_TAKEN'; end if;
  if exists(select from public.template_categories where name_zh_lookup='reference:'||btrim(p_name_zh) and key<>p_key)
    then raise exception 'CATEGORY_NAME_ZH_TAKEN'; end if;
  if p_is_new then
    if p_parent is not null and not exists(select from public.template_categories where key=p_parent and kind='reference' and level<3)
      then raise exception 'INVALID_PARENT'; end if;
    select coalesce(max(sort_order),0)+10 into next_order from public.template_categories
      where kind='reference' and parent_id is not distinct from p_parent;
    insert into public.template_categories(key,name_en,name_zh,parent_id,kind,is_visible,sort_order)
      values(p_key,btrim(p_name_en),btrim(p_name_zh),p_parent,'reference',false,next_order);
  else
    update public.template_categories set name_en=btrim(p_name_en),name_zh=btrim(p_name_zh) where key=p_key;
  end if;
end $$;


ALTER FUNCTION "public"."admin_save_reference_category"("p_actor" "uuid", "p_key" "text", "p_name_en" "text", "p_name_zh" "text", "p_parent" "text", "p_is_new" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_save_template_assignment"("p_actor" "uuid", "p_template" "jsonb", "p_prompt" "jsonb", "p_assignment" "jsonb", "p_is_new" boolean, "p_expected" integer DEFAULT NULL::integer, "p_selected" integer DEFAULT NULL::integer, "p_style_refs" "jsonb" DEFAULT NULL::"jsonb") RETURNS integer
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  v_id text := p_template->>'id';
  v_node text := p_template->>'category_key';
  v_series uuid;
  v_previous_series uuid;
  v_old public.templates%rowtype;
  v_root text;
  v_system boolean;
  v_version integer;
  v_order integer := 0;
begin
  if not exists(select from public.profiles where id=p_actor and role='admin' and banned_at is null) then
    raise exception 'NOT_ADMIN';
  end if;
  if p_is_new is null or not coalesce(p_assignment ? 'series_id',false) then raise exception 'INVALID_INPUT'; end if;
  begin
    v_series := (p_assignment->>'series_id')::uuid;
    v_previous_series := (p_assignment->>'previous_series_id')::uuid;
  exception when invalid_text_representation then
    raise exception 'INVALID_INPUT';
  end;
  perform pg_advisory_xact_lock_shared(hashtextextended('shotviva.category_tree',0));
  perform pg_advisory_xact_lock(hashtextextended('shotviva.template_series',0));
  select * into v_old from public.templates where id=v_id for update;
  if found and p_is_new then raise exception 'TEMPLATE_EXISTS'; end if;
  if v_old.id is null and not p_is_new then raise exception 'TEMPLATE_NOT_FOUND'; end if;
  if not p_is_new and (not (p_assignment ? 'previous_series_id')
      or v_previous_series is distinct from v_old.series_id
      or p_assignment->>'previous_category' is distinct from coalesce(v_old.subcategory_key,v_old.category_key)) then
    raise exception 'STALE_TEMPLATE_ASSIGNMENT';
  end if;
  select p.root_key,c.is_system into v_root,v_system from public.template_category_paths p
    join public.template_categories c on c.key=p.key where p.key=v_node;
  if not found then raise exception 'CATEGORY_NOT_FOUND'; end if;
  if v_system or exists(select from public.template_categories where key=v_old.category_key and is_system) then
    if v_old.category_key is distinct from v_node or v_series is not null then raise exception 'SYSTEM_ASSIGNMENT'; end if;
  end if;
  if v_series is not null and not exists(select from public.template_series where id=v_series) then
    raise exception 'SERIES_NOT_FOUND';
  end if;

  p_template:=jsonb_set(p_template,'{category_key}',to_jsonb(v_root));
  if p_expected is not null then
    v_version:=public.admin_save_versioned_template(p_actor,p_template,p_prompt,p_expected,p_selected,p_style_refs);
  elsif p_style_refs is not null then
    perform public.admin_upsert_template(p_template,p_prompt,p_style_refs);
  else
    perform public.admin_upsert_template(p_template,p_prompt);
  end if;
  if v_series is not distinct from v_old.series_id then
    v_order:=coalesce(v_old.series_sort_order,0);
  elsif v_series is not null then
    select coalesce(max(series_sort_order),0)+1 into v_order from public.templates where series_id=v_series;
  end if;
  update public.templates set subcategory_key=nullif(v_node,v_root),series_id=v_series,series_sort_order=v_order
    where id=v_id and (subcategory_key,series_id,series_sort_order)
      is distinct from (nullif(v_node,v_root),v_series,v_order);
  if v_version is null then select version into v_version from public.template_prompts where template_id=v_id; end if;
  return v_version;
end $$;


ALTER FUNCTION "public"."admin_save_template_assignment"("p_actor" "uuid", "p_template" "jsonb", "p_prompt" "jsonb", "p_assignment" "jsonb", "p_is_new" boolean, "p_expected" integer, "p_selected" integer, "p_style_refs" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_save_template_category"("p_category" "jsonb", "p_is_new" boolean, "p_actor" "uuid") RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  k text := btrim(p_category->>'key');
  en text := btrim(p_category->>'name_en');
  zh text := btrim(p_category->>'name_zh');
  parent text := p_category->>'parent_id';
  next_order integer;
  previous public.template_categories;
begin
  if not exists(select 1 from public.profiles where id=p_actor and role='admin' and banned_at is null) then raise exception 'NOT_ADMIN'; end if;
  perform pg_advisory_xact_lock(hashtextextended('shotviva.category_tree',0));
  select * into previous from public.template_categories where key=k;
  if p_is_new and found then raise exception 'CATEGORY_KEY_TAKEN'; end if;
  if not p_is_new then
    if previous.key is null or previous.kind <> 'template' then raise exception 'CATEGORY_NOT_FOUND'; end if;
    if previous.is_system then raise exception 'CATEGORY_SYSTEM'; end if;
  end if;
  if exists(select 1 from public.template_categories where name_en_lookup='template:'||lower(en) and key<>k) then raise exception 'CATEGORY_NAME_EN_TAKEN'; end if;
  if exists(select 1 from public.template_categories where name_zh_lookup='template:'||zh and key<>k) then raise exception 'CATEGORY_NAME_ZH_TAKEN'; end if;

  if p_is_new then
    if parent is not null and not exists(select 1 from public.template_categories
        where key=parent and kind='template' and not is_system and level<3) then raise exception 'INVALID_PARENT'; end if;
    select coalesce(max(sort_order),0)+10 into next_order from public.template_categories
      where parent_id is not distinct from parent and kind='template' and not is_system;
    insert into public.template_categories(key, name_en, name_zh, intro_en, intro_zh, card_style, sort_order,
      parent_id,slug,is_visible,seo_title_en,seo_title_zh,seo_description_en,seo_description_zh)
    values(k,en,zh,nullif(btrim(p_category->>'intro_en'),''),nullif(btrim(p_category->>'intro_zh'),''),
      coalesce(p_category->>'card_style','pair'),next_order,parent,coalesce(p_category->>'slug',k),
      coalesce((p_category->>'is_visible')::boolean,true),nullif(p_category->>'seo_title_en',''),nullif(p_category->>'seo_title_zh',''),
      nullif(p_category->>'seo_description_en',''),nullif(p_category->>'seo_description_zh',''));
  else
    update public.template_categories set name_en=en, name_zh=zh, intro_en=nullif(btrim(p_category->>'intro_en'),''),
      intro_zh=nullif(btrim(p_category->>'intro_zh'),''), card_style=coalesce(p_category->>'card_style','pair'),
      slug=coalesce(p_category->>'slug',previous.slug), is_visible=coalesce((p_category->>'is_visible')::boolean,previous.is_visible),
      seo_title_en=nullif(coalesce(p_category->>'seo_title_en',previous.seo_title_en),''),
      seo_title_zh=nullif(coalesce(p_category->>'seo_title_zh',previous.seo_title_zh),''),
      seo_description_en=nullif(coalesce(p_category->>'seo_description_en',previous.seo_description_en),''),
      seo_description_zh=nullif(coalesce(p_category->>'seo_description_zh',previous.seo_description_zh),'')
    where key=k;
  end if;
end $$;


ALTER FUNCTION "public"."admin_save_template_category"("p_category" "jsonb", "p_is_new" boolean, "p_actor" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_save_template_series"("p_id" "uuid", "p_revision" "text", "p_fields" "jsonb", "p_members" "text"[], "p_actor" "uuid", "p_reason" "text") RETURNS "uuid"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  previous public.template_series;
  saved public.template_series;
begin
  if not exists(select 1 from public.profiles where id=p_actor and role='admin' and banned_at is null) then
    raise exception 'NOT_ADMIN';
  end if;
  perform pg_advisory_xact_lock_shared(hashtextextended('shotviva.category_tree',0));
  perform pg_advisory_xact_lock(hashtextextended('shotviva.template_series',0));
  if p_id is not null then
    select * into previous from public.template_series where id=p_id for update;
    if not found or p_revision is distinct from admin.template_series_revision(previous) then
      raise exception 'SERIES_CHANGED';
    end if;
    if previous.is_active and not (p_fields->>'is_active')::boolean and nullif(btrim(p_reason),'') is null then
      raise exception 'SERIES_REASON_REQUIRED';
    end if;
  end if;
  if p_members is null or cardinality(p_members)<>(select count(distinct m) from unnest(p_members) m) then
    raise exception 'INVALID_SERIES_MEMBERS';
  end if;
  perform 1 from public.templates where id=any(p_members) or series_id=p_id order by id for update;
  if cardinality(p_members)<>(select count(*) from public.templates t
      join public.template_categories c on c.key=t.category_key where t.id=any(p_members)
      and not c.is_system and t.id not in ('freeform','edit')) then
    raise exception 'INVALID_SERIES_MEMBERS';
  end if;
  if exists(select 1 from public.templates where id=any(p_members) and series_id is not null and series_id is distinct from p_id) then
    raise exception 'SERIES_MEMBER_TAKEN';
  end if;
  saved:=jsonb_populate_record(null::public.template_series,p_fields);
  if p_id is null then
    insert into public.template_series(slug,name_en,name_zh,description_en,description_zh,cover_url,
      category_key,sort_order,is_active,show_members)
    values(saved.slug,saved.name_en,saved.name_zh,saved.description_en,saved.description_zh,saved.cover_url,
      saved.category_key,saved.sort_order,saved.is_active,saved.show_members) returning id into p_id;
  else
    update public.template_series set slug=saved.slug,name_en=saved.name_en,name_zh=saved.name_zh,
      description_en=saved.description_en,description_zh=saved.description_zh,cover_url=saved.cover_url,
      category_key=saved.category_key,sort_order=saved.sort_order,is_active=saved.is_active,show_members=saved.show_members
    where id=p_id;
  end if;
  update public.templates set series_id=null,series_sort_order=0 where series_id=p_id and not (id=any(p_members));
  update public.templates t set series_id=p_id,series_sort_order=m.ord::integer
    from unnest(p_members) with ordinality as m(id,ord) where t.id=m.id
      and (t.series_id is distinct from p_id or t.series_sort_order<>m.ord);
  return p_id;
end $$;


ALTER FUNCTION "public"."admin_save_template_series"("p_id" "uuid", "p_revision" "text", "p_fields" "jsonb", "p_members" "text"[], "p_actor" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_save_versioned_template"("p_actor" "uuid", "p_template" "jsonb", "p_prompt" "jsonb", "p_expected" integer, "p_selected" integer DEFAULT NULL::integer, "p_style_refs" "jsonb" DEFAULT NULL::"jsonb") RETURNS integer
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare v_id text:=p_template->>'id'; current_v integer; h public.template_prompt_versions%rowtype;
  previous text:=current_setting('shotviva.restore_prompt_version',true);
begin
  if not exists(select from public.profiles where id=p_actor and role='admin' and banned_at is null) then raise exception 'FORBIDDEN'; end if;
  perform 1 from public.templates where id=v_id for update;
  if not found then raise exception 'TEMPLATE_NOT_FOUND'; end if;
  select version into current_v from public.template_prompts where template_id=v_id for update;
  if current_v is distinct from p_expected then raise exception 'STALE_PROMPT'; end if;
  if p_selected is not null then
    select * into h from public.template_prompt_versions where template_id=v_id and version=p_selected;
    if not found then raise exception 'VERSION_NOT_FOUND'; end if;
    if h.provider_id is not null and (p_prompt->>'provider_id')::uuid=h.provider_id then
      perform 1 from public.ai_providers where id=h.provider_id and module='image' and model=h.provider_model
        and vault_secret_id is not null for share;
      if not found then raise exception 'HISTORICAL_PROVIDER_UNAVAILABLE'; end if;
    end if;
  end if;
  -- Listing, ranking and cover uploads are different admin operations with their own guards.
  p_template := p_template - array['is_active','featured_rank','sort_order','cover_before_url','cover_after_url'];
  perform set_config('shotviva.restore_prompt_version',coalesce(p_selected::text,''),true);
  if p_style_refs is null then perform public.admin_upsert_template(p_template,p_prompt);
  else perform public.admin_upsert_template(p_template,p_prompt,p_style_refs); end if;
  perform set_config('shotviva.restore_prompt_version',coalesce(previous,''),true);
  select version into strict current_v from public.template_prompts where template_id=v_id;
  return current_v;
end $$;


ALTER FUNCTION "public"."admin_save_versioned_template"("p_actor" "uuid", "p_template" "jsonb", "p_prompt" "jsonb", "p_expected" integer, "p_selected" integer, "p_style_refs" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_search_users"("p_query" "text") RETURNS TABLE("id" "uuid", "email" "text", "created_at" timestamp with time zone, "provider" "text", "role" "text", "credits" integer, "free_credits" integer, "paid_until" timestamp with time zone, "generation_count" integer, "last_generation_at" timestamp with time zone, "banned_at" timestamp with time zone, "phone" "text")
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $_$
  select o.id, o.email, o.created_at, o.provider, o.role, o.credits, o.free_credits, o.paid_until,
         o.generation_count, o.last_generation_at, o.banned_at, o.phone
    from admin.users_overview o
   -- The query is a literal substring: % and _ typed by the admin match themselves.
   where length(btrim(coalesce(p_query, ''))) > 0
     and (o.email ilike '%' || replace(replace(replace(btrim(p_query), '\', '\\'), '%', '\%'), '_', '\_') || '%'
          or (btrim(p_query) ~ '^\+?[0-9][0-9 -]{2,}$'
              and length(regexp_replace(p_query, '[^0-9]', '', 'g')) >= 4
              and o.phone like '%' || regexp_replace(p_query, '[^0-9]', '', 'g') || '%'))
   order by o.created_at desc, o.id desc
   limit 50
$_$;


ALTER FUNCTION "public"."admin_search_users"("p_query" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_series_candidates"("p_search" "text", "p_after" "text") RETURNS TABLE("id" "text", "name" "text", "cover_url" "text", "series_id" "uuid", "is_active" boolean)
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  select t.id, coalesce(nullif(t.translations #>> '{zh,name}',''),t.name),
         coalesce(t.cover_after_url,t.cover_locales #>> '{zh,after}',t.cover_locales #>> '{en,after}'),
         t.series_id,t.is_active
    from public.templates t join public.template_categories c on c.key=t.category_key
   where not c.is_system and t.id not in ('freeform','edit') and (p_after is null or t.id>p_after)
     and (p_search='' or strpos(lower(t.id),lower(p_search))>0 or strpos(lower(t.name),lower(p_search))>0
          or strpos(lower(t.translations #>> '{zh,name}'),lower(p_search))>0)
   order by t.id limit 31
$$;


ALTER FUNCTION "public"."admin_series_candidates"("p_search" "text", "p_after" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_set_code_active"("p_actor" "uuid", "p_code_id" "uuid", "p_active" boolean) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if not exists (select 1 from public.profiles where id = p_actor and role = 'admin' and banned_at is null) then
    raise exception 'NOT_ADMIN';
  end if;
  if p_active is null then raise exception 'INVALID_INPUT'; end if;
  update public.codes set active = p_active, updated_at = now() where id = p_code_id;
  if not found then raise exception 'CODE_NOT_FOUND'; end if;
  insert into public.admin_audit_log(action, user_id, target_id, reason)
  values ('set_code_active', p_actor, p_code_id::text, case when p_active then '启用' else '停用' end);
end;
$$;


ALTER FUNCTION "public"."admin_set_code_active"("p_actor" "uuid", "p_code_id" "uuid", "p_active" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_set_feature_access"("p_key" "text", "p_min_tier" "text", "p_open_to_all_at" timestamp with time zone, "p_actor" "uuid") RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
begin
  if p_actor is null then
    raise exception 'INVALID_INPUT' using detail = 'actor is required';
  end if;
  if p_min_tier is not null and p_min_tier not in ('pro', 'max') then
    raise exception 'INVALID_INPUT' using detail = 'min_tier must be pro or max';
  end if;

  insert into public.feature_access (key, min_tier, open_to_all_at, updated_at, updated_by)
  values (p_key, p_min_tier, p_open_to_all_at, now(), p_actor)
  on conflict (key) do update
    set min_tier = excluded.min_tier,
        open_to_all_at = excluded.open_to_all_at,
        updated_at = excluded.updated_at,
        updated_by = excluded.updated_by;
end;
$$;


ALTER FUNCTION "public"."admin_set_feature_access"("p_key" "text", "p_min_tier" "text", "p_open_to_all_at" timestamp with time zone, "p_actor" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_set_featured_templates"("p_ids" "text"[]) RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  v_ids text[] := coalesce(p_ids, '{}');
begin
  if cardinality(v_ids) > 12 then
    raise exception 'at most 12 featured templates' using errcode = '22023';
  end if;
  if cardinality(v_ids) <> (select count(distinct id) from unnest(v_ids) as u(id)) then
    raise exception 'featured templates must not repeat' using errcode = '22023';
  end if;
  if exists (
    select 1 from unnest(v_ids) as u(id)
    where not exists (
      select 1 from public.templates t where t.id = u.id and t.is_active and 'web' = any (t.visible_in)
    )
  ) then
    raise exception 'only published web templates can be featured' using errcode = '22023';
  end if;

  update public.templates set featured_rank = null where featured_rank is not null;
  update public.templates t
  set featured_rank = o.position
  from unnest(v_ids) with ordinality as o(id, position)
  where t.id = o.id;
end;
$$;


ALTER FUNCTION "public"."admin_set_featured_templates"("p_ids" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_set_openai_admin_key"("p_key" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  v_name constant text := 'shotviva.openai_admin_key';
  v_secret uuid;
begin
  -- Same shape rule as provider keys: printable ASCII without whitespace, 16-1024 characters.
  if p_key is not null and (char_length(p_key) not between 16 and 1024 or p_key !~ '^[!-~]+$') then
    raise exception 'PROVIDER_KEY_INVALID' using errcode = '23514';
  end if;

  if p_key is null then
    delete from vault.secrets where name in (v_name, 'shotviva.openai_costs_project');
    return;
  end if;

  select id into v_secret from vault.secrets where name = v_name;
  if v_secret is null then
    perform vault.create_secret(p_key, v_name, 'Shotviva OpenAI Admin key (cost reconciliation)');
  else
    perform vault.update_secret(v_secret, p_key);
  end if;
end;
$_$;


ALTER FUNCTION "public"."admin_set_openai_admin_key"("p_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_set_openai_costs_project"("p_project_id" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  v_name constant text := 'shotviva.openai_costs_project';
  v_secret uuid;
begin
  if p_project_id is not null and p_project_id !~ '^proj_[A-Za-z0-9]{1,64}$' then
    raise exception 'INVALID_INPUT' using errcode = '23514', detail = 'project id must look like proj_…';
  end if;

  select id into v_secret from vault.secrets where name = v_name;
  if p_project_id is null then
    delete from vault.secrets where name = v_name;
  elsif v_secret is null then
    perform vault.create_secret(p_project_id, v_name, 'Shotviva OpenAI project id for cost reconciliation');
  else
    perform vault.update_secret(v_secret, p_project_id);
  end if;
end;
$_$;


ALTER FUNCTION "public"."admin_set_openai_costs_project"("p_project_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_set_prompt_lab_reverse"("p_actor" "uuid", "p_model" "text", "p_instruction" "text") RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
begin
  perform admin.require_reference_admin(p_actor);
  if p_model is null or p_instruction is null or length(p_model)>300 or length(p_instruction)>32000
    or (btrim(p_model)='')<>(btrim(p_instruction)='') then raise exception 'INVALID_INPUT'; end if;
  insert into public.system_settings(key,value,updated_by) values('prompt_lab_reverse',
    jsonb_build_object('model',btrim(p_model),'instruction',btrim(p_instruction)),p_actor)
    on conflict(key) do update set value=excluded.value,updated_by=p_actor,updated_at=now();
end $$;


ALTER FUNCTION "public"."admin_set_prompt_lab_reverse"("p_actor" "uuid", "p_model" "text", "p_instruction" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_set_provider_key"("p_id" "uuid", "p_key" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  v_secret uuid;
  v_name text := 'shotviva.provider.' || p_id::text;
begin
  -- Printable ASCII without whitespace, 16-1024 characters: every supported provider key fits.
  if p_key is not null and (char_length(p_key) not between 16 and 1024 or p_key !~ '^[!-~]+$') then
    raise exception 'PROVIDER_KEY_INVALID' using errcode = '23514';
  end if;

  select vault_secret_id into v_secret from public.ai_providers where id = p_id for update;
  if not found then
    raise exception 'PROVIDER_NOT_FOUND';
  end if;

  if p_key is null then
    delete from vault.secrets where id = v_secret or name = v_name;
    update public.ai_providers set vault_secret_id = null, api_key_last4 = null where id = p_id;
    return;
  end if;

  if v_secret is not null and exists (select 1 from vault.secrets where id = v_secret) then
    perform vault.update_secret(v_secret, p_key);
  else
    -- A leftover secret under this name is replaced, never reused blindly.
    delete from vault.secrets where name = v_name;
    v_secret := vault.create_secret(p_key, v_name, 'Shotviva image provider API key');
  end if;

  update public.ai_providers set vault_secret_id = v_secret, api_key_last4 = right(p_key, 4) where id = p_id;
end;
$_$;


ALTER FUNCTION "public"."admin_set_provider_key"("p_id" "uuid", "p_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_set_system_setting"("p_key" "text", "p_value" "jsonb", "p_actor" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
begin
  if p_actor is null then
    raise exception 'INVALID_INPUT' using detail = 'actor is required';
  end if;
  if not exists (select 1 from public.profiles p where p.id = p_actor and p.role = 'admin'
      and (p_key not in ('code_gift_policy','code_inviter_window_days','gallery_enabled','gallery_auto_approve')
           or p.banned_at is null)) then
    raise exception 'NOT_ADMIN';
  end if;

  case p_key
    when 'wishlist_enabled', 'gallery_enabled', 'gallery_auto_approve' then
      if p_value is null or jsonb_typeof(p_value) <> 'boolean' then
        raise exception 'INVALID_INPUT' using detail = p_key || ' must be a boolean';
      end if;
    when 'admin_test_daily_budget_usd' then
      if p_value is null or jsonb_typeof(p_value) <> 'number'
         or (p_value #>> '{}')::numeric < 0 or (p_value #>> '{}')::numeric > 1000 then
        raise exception 'INVALID_INPUT' using detail = 'admin_test_daily_budget_usd must be a number from 0 to 1000';
      end if;
    when 'code_inviter_window_days' then
      if jsonb_typeof(p_value) is distinct from 'number' or
         (p_value #>> '{}') !~ '^[1-9][0-9]*$' or (p_value #>> '{}')::numeric > 2147483647 then
        raise exception 'INVALID_INPUT' using detail = 'reward window must be a positive integer';
      end if;
    when 'code_gift_policy' then
      if jsonb_typeof(p_value) is distinct from 'object' or
         jsonb_typeof(p_value->'requirePaidGiftCap') is distinct from 'boolean' or
         jsonb_typeof(p_value->'maxCreditsPerCode') is distinct from 'number' or
         (p_value->>'maxCreditsPerCode') !~ '^[1-9][0-9]*$' or
         (p_value->>'maxCreditsPerCode')::numeric > 2147483647 or
         p_value - array['requirePaidGiftCap','maxCreditsPerCode'] <> '{}'::jsonb then
        raise exception 'INVALID_INPUT' using detail = 'invalid gift code policy';
      end if;
    else
      raise exception 'INVALID_INPUT' using detail = 'unknown setting';
  end case;

  insert into public.system_settings (key, value, updated_at, updated_by)
  values (p_key, p_value, now(), p_actor)
  on conflict (key) do update
    set value = excluded.value,
        updated_at = excluded.updated_at,
        updated_by = excluded.updated_by;

  if p_key in ('gallery_enabled', 'gallery_auto_approve') then
    insert into public.admin_audit_log (action, user_id, reason, target_id)
    values ('gallery_setting', p_actor, p_value::text, p_key);
  end if;
end;
$_$;


ALTER FUNCTION "public"."admin_set_system_setting"("p_key" "text", "p_value" "jsonb", "p_actor" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_set_template_locale_cover"("p_actor" "uuid", "p_template_id" "text", "p_locale" "text", "p_patch" "jsonb", "p_assets_base" "text", "p_locales" "text"[], "p_clear" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $_$
declare
  v_row public.templates;
  v_live boolean;
  v_next jsonb;
  v_result jsonb;
  v_key text;
  v_value jsonb;
begin
  if p_actor is null or not exists (select 1 from public.profiles p where p.id = p_actor and p.role = 'admin') then
    raise exception 'NOT_ADMIN';
  end if;
  if p_locale is null or p_locale !~ '^[a-z]{2,3}(-[a-z0-9]{2,8})?$' then
    raise exception 'INVALID_INPUT' using detail = 'unknown language code';
  end if;
  if p_assets_base is null or p_assets_base !~ '^https://[^/]+(/[^?#]*)?$' then
    raise exception 'INVALID_INPUT' using detail = 'assets base must be an https URL';
  end if;
  if p_patch is null or jsonb_typeof(p_patch) <> 'object' then
    raise exception 'INVALID_INPUT' using detail = 'patch must be an object';
  end if;
  for v_key, v_value in select e.key, e.value from jsonb_each(p_patch) as e(key, value) loop
    if v_key not in ('before', 'after', 'video', 'poster', 'media') then
      raise exception 'INVALID_INPUT' using detail = 'unknown cover key';
    end if;
    if jsonb_typeof(v_value) = 'null' then
      continue;
    end if;
    if v_key = 'media' and (v_value #>> '{}') not in ('animated', 'video') then
      raise exception 'INVALID_INPUT' using detail = 'media must be animated or video';
    end if;
    if v_key <> 'media' and (jsonb_typeof(v_value) <> 'string'
        or left(v_value #>> '{}', length(rtrim(p_assets_base, '/')) + 1) <> rtrim(p_assets_base, '/') || '/') then
      raise exception 'INVALID_INPUT' using detail = 'cover URLs must be on the assets origin';
    end if;
  end loop;

  select * into v_row from public.templates t where t.id = p_template_id for update;
  if not found then
    raise exception 'TEMPLATE_NOT_FOUND';
  end if;

  if p_clear then
    v_next := '{}'::jsonb;
  else
    v_next := jsonb_strip_nulls(coalesce(v_row.cover_locales -> p_locale, '{}'::jsonb) || p_patch);
  end if;
  v_result := case when v_next = '{}'::jsonb then v_row.cover_locales - p_locale else jsonb_set(v_row.cover_locales, array[p_locale], v_next) end;

  -- The publish rule, for a template visitors can see: some "before" and some "after" left.
  v_live := v_row.is_active and 'web' = any (v_row.visible_in);
  if v_live and public._template_has_cover_parts(v_row.cover_before_url, v_row.cover_after_url, v_row.cover_locales, p_locales)
     and not public._template_has_cover_parts(v_row.cover_before_url, v_row.cover_after_url, v_result, p_locales) then
    raise exception 'COVER_STILL_NEEDED';
  end if;

  update public.templates t set cover_locales = v_result where t.id = p_template_id;
  return v_result;
end;
$_$;


ALTER FUNCTION "public"."admin_set_template_locale_cover"("p_actor" "uuid", "p_template_id" "text", "p_locale" "text", "p_patch" "jsonb", "p_assets_base" "text", "p_locales" "text"[], "p_clear" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_set_template_order"("p_group" "text", "p_ids" "text"[], "p_actor" "uuid") RETURNS "void"
    LANGUAGE "sql"
    SET "search_path" TO ''
    AS $$
  select public.admin_set_template_order(p_group, p_ids, p_actor, null);
$$;


ALTER FUNCTION "public"."admin_set_template_order"("p_group" "text", "p_ids" "text"[], "p_actor" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_set_template_order"("p_group" "text", "p_ids" "text"[], "p_actor" "uuid", "p_expected_ids" "text"[]) RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  v_ids text[] := coalesce(p_ids, '{}');
  v_members text[];
  order_slots integer[];
  upper_bounds bigint[] := '{}';
  max_order bigint := 2147483647;
  assigned_order bigint := -2147483648;
begin
  if p_actor is null then
    raise exception 'INVALID_INPUT' using detail = 'actor is required';
  end if;
  if not exists (select 1 from public.profiles p where p.id = p_actor and p.role = 'admin' and p.banned_at is null) then
    raise exception 'NOT_ADMIN';
  end if;
  if p_group is null or p_group not in ('catalogue', 'featured', 'active', 'inactive') then
    raise exception 'INVALID_INPUT' using detail = 'unknown catalogue group';
  end if;
  if cardinality(v_ids) <> (select count(distinct id) from unnest(v_ids) as u(id)) then
    raise exception 'INVALID_INPUT' using detail = 'ids must not repeat';
  end if;

  -- Holds off other template writes for these few milliseconds, so the membership checked
  -- below is still the membership when the new order is written. Reads are not blocked.
  lock table public.templates in share row exclusive mode;

  select coalesce(array_agg(t.id order by case when p_group = 'featured' then t.featured_rank else t.sort_order end, t.id), '{}'),
         array_agg(t.sort_order order by t.sort_order, t.id)
    into v_members, order_slots
  from public.templates t
  where case p_group
    when 'catalogue' then t.id <> 'edit'
    when 'featured' then t.featured_rank is not null
    else t.id <> 'edit' and t.is_active = (p_group = 'active')
  end;

  if cardinality(v_members) <> cardinality(v_ids) or not (v_members @> v_ids) then
    raise exception 'ORDER_MISMATCH'
      using detail = format('%s ids given, the %s group has %s', cardinality(v_ids), p_group, cardinality(v_members));
  end if;

  if p_expected_ids is not null and p_expected_ids <> v_members then
    raise exception 'ORDER_MISMATCH' using detail = 'the displayed order changed';
  end if;

  if p_group <> 'featured' then
    if v_ids = v_members then
      return;
    end if;

    -- An unmoved row is an anchor. Work backwards to find the highest integer
    -- each slot may occupy. Equal integers follow id order, exactly as in the UI.
    for i in reverse cardinality(v_ids)..1 loop
      if v_ids[i] > v_ids[i + 1] then
        max_order := max_order - 1;
      end if;
      if v_ids[i] = v_members[i] then
        if order_slots[i] > max_order then
          raise exception 'ORDER_TIED';
        end if;
        max_order := order_slots[i];
      end if;
      upper_bounds[i] := max_order;
    end loop;

    -- Work forwards and reuse the old slot number whenever it fits. For a
    -- duplicate legacy number, stay within both the previous row and next anchor.
    for i in 1..cardinality(v_ids) loop
      if v_ids[i - 1] > v_ids[i] then
        assigned_order := assigned_order + 1;
      end if;
      if assigned_order > upper_bounds[i] then
        raise exception 'ORDER_TIED';
      end if;
      assigned_order := greatest(assigned_order, least(order_slots[i], upper_bounds[i]));
      order_slots[i] := assigned_order;
    end loop;
    update public.templates t
    set sort_order = s.slot
    from unnest(v_ids, order_slots) as s(id, slot)
    where t.id = s.id and t.sort_order <> s.slot;
    return;
  end if;

  -- Cleared first so the one-per-position index never sees two rows on one rank mid-way.
  update public.templates set featured_rank = null where featured_rank is not null;
  update public.templates t
  set featured_rank = o.position
  from unnest(v_ids) with ordinality as o(id, position)
  where t.id = o.id;
end;
$$;


ALTER FUNCTION "public"."admin_set_template_order"("p_group" "text", "p_ids" "text"[], "p_actor" "uuid", "p_expected_ids" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_set_template_sale"("p_actor" "uuid", "p_template_id" "text", "p_enabled" boolean) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare t public.templates;
begin
  if not exists(select from public.profiles where id=p_actor and role='admin' and banned_at is null) then raise exception 'FORBIDDEN'; end if;
  select * into strict t from public.templates where id=p_template_id for update;
  if p_enabled is null then raise exception 'INVALID_INPUT'; end if;
  if not p_enabled and t.is_active then raise exception 'UNPUBLISH_FIRST' using detail='请先下架，再关闭销售'; end if;
  if p_enabled=exists(select from public.template_sale_approvals where template_id=t.id and enabled) then return; end if;
  if p_enabled then
    perform admin.set_template_unpriced_resolutions(t.id,null);
    perform admin.assert_template_sale_floor(t);
  end if;
  insert into public.template_sale_approvals(template_id,enabled) values(t.id,p_enabled)
    on conflict(template_id) do update set enabled=excluded.enabled;
  insert into admin.template_sale_events(template_id,actor_id,enabled) values(t.id,p_actor,p_enabled);
end;
$$;


ALTER FUNCTION "public"."admin_set_template_sale"("p_actor" "uuid", "p_template_id" "text", "p_enabled" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_set_test_run_cover"("p_actor" "uuid", "p_run_id" "uuid", "p_before_url" "text", "p_after_url" "text", "p_locale" "text" DEFAULT NULL::"text") RETURNS "text"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $_$
declare
  v_template text;
  v_run public.admin_test_runs;
begin
  if p_actor is null or not exists (select 1 from public.profiles p where p.id = p_actor and p.role = 'admin') then
    raise exception 'NOT_ADMIN';
  end if;
  if p_locale is not null and p_locale !~ '^[a-z]{2,3}(-[a-z0-9]{2,8})?$' then
    raise exception 'INVALID_INPUT' using detail = 'unknown language code';
  end if;
  if p_after_url is null or p_after_url !~ '^https://' or (p_before_url is not null and p_before_url !~ '^https://') then
    raise exception 'INVALID_INPUT' using detail = 'cover URLs must be https';
  end if;

  select * into v_run from public.admin_test_runs r
   where r.id = p_run_id and r.status = 'succeeded' and r.output_key is not null
   for update;
  if not found then
    raise exception 'TEST_RUN_NOT_FOUND';
  end if;
  if v_run.kind = 'translate'
     and (p_locale is distinct from (v_run.inputs ->> 'target_locale') or p_before_url is not null) then
    raise exception 'TRANSLATE_TARGET_ONLY';
  end if;

  update public.admin_test_runs r set cover_set_at = now() where r.id = p_run_id;
  v_template := v_run.template_id;

  if p_locale is null then
    update public.templates t
       set cover_after_url = p_after_url,
           cover_before_url = coalesce(p_before_url, t.cover_before_url)
     where t.id = v_template;
  else
    update public.templates t
       set cover_locales = jsonb_set(
             t.cover_locales,
             array[p_locale],
             coalesce(t.cover_locales -> p_locale, '{}'::jsonb)
               || jsonb_build_object('after', p_after_url)
               || case when p_before_url is null or t.cover_before_url is not null then '{}'::jsonb
                       else jsonb_build_object('before', p_before_url) end)
     where t.id = v_template;
  end if;
  return v_template;
end;
$_$;


ALTER FUNCTION "public"."admin_set_test_run_cover"("p_actor" "uuid", "p_run_id" "uuid", "p_before_url" "text", "p_after_url" "text", "p_locale" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_signup_ip_clusters"("p_days" integer) RETURNS TABLE("signup_ip" "inet", "accounts" integer, "last_signup_at" timestamp with time zone, "members" "jsonb")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if p_days is null or p_days not in (1, 7) then
    raise exception 'INVALID_INPUT' using detail = 'p_days must be 1 or 7';
  end if;

  return query
  with recent as (
    select p.id, p.signup_ip, p.created_at, p.free_credits, p.banned_at
      from public.profiles p
     where p.created_at >= now() - make_interval(days => p_days)
       and p.signup_ip is not null
  ), clusters as (
    select r.signup_ip, count(*)::integer as accounts, max(r.created_at) as last_signup_at
      from recent r
     group by r.signup_ip
    having count(*) >= 3
     order by count(*) desc, max(r.created_at) desc
     limit 50
  )
  select c.signup_ip, c.accounts, c.last_signup_at,
         (select jsonb_agg(jsonb_build_object(
                    'id', r.id,
                    'email', u.email,
                    'phone', nullif(u.phone, ''),
                    'created_at', r.created_at,
                    'free_credits', r.free_credits,
                    'free_used', coalesce(used.credits, 0),
                    'banned_at', r.banned_at)
                  order by r.created_at desc)
            from recent r
            left join auth.users u on u.id = r.id
            left join lateral (
              select -sum(l.delta)::integer as credits
                from public.credit_ledger l
               where l.user_id = r.id and l.pool = 'free' and l.kind in ('reserve', 'refund')
            ) used on true
           where r.signup_ip = c.signup_ip)
    from clusters c
   order by c.accounts desc, c.last_signup_at desc;
end;
$$;


ALTER FUNCTION "public"."admin_signup_ip_clusters"("p_days" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_template_copy_source"("p_actor" "uuid", "p_source" "text", "p_request" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $$
declare receipt admin.template_copy_requests%rowtype; manifest jsonb;
begin
  if not exists(select from public.profiles where id=p_actor and role='admin' and banned_at is null) then raise exception 'FORBIDDEN'; end if;
  select * into receipt from admin.template_copy_requests where request_id=p_request;
  if found then
    if (receipt.actor_id,receipt.source_id) is distinct from (p_actor,p_source) then raise exception 'REQUEST_MISMATCH'; end if;
    return jsonb_build_object('existing',jsonb_build_object('id',receipt.target_id,'previousStandard',receipt.previous_standard));
  end if;
  select jsonb_build_object('token',t.xmin::text||'/'||p.xmin::text,'assets',jsonb_build_object(
    'cover_before_url',t.cover_before_url,'cover_after_url',t.cover_after_url,'cover_poster_url',t.cover_poster_url,
    'cover_video_url',t.cover_video_url,'cover_locales',t.cover_locales,'style_refs',p.style_refs)) into manifest
    from public.templates t join public.template_prompts p on p.template_id=t.id
    join public.template_categories c on c.key=t.category_key
    where t.id=p_source and t.id not in ('edit','freeform') and not c.is_system;
  if manifest is null then raise exception 'TEMPLATE_NOT_FOUND'; end if;
  return manifest;
end $$;


ALTER FUNCTION "public"."admin_template_copy_source"("p_actor" "uuid", "p_source" "text", "p_request" "uuid") OWNER TO "postgres";


