    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  select to_jsonb(s) || jsonb_build_object('revision',admin.template_series_revision(s),'members',
    coalesce((select jsonb_agg(jsonb_build_object('id',t.id,
      'name',coalesce(nullif(t.translations #>> '{zh,name}',''),t.name),
      'cover_url',coalesce(t.cover_after_url,t.cover_locales #>> '{zh,after}',t.cover_locales #>> '{en,after}'),
      'is_active',t.is_active, 'series_id',s.id) order by t.series_sort_order,t.id)
      from public.templates t where t.series_id=s.id),'[]'))
  from public.template_series s where s.id=p_id
$$;


ALTER FUNCTION "public"."admin_template_series_detail"("p_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_test_budget_status"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $$
declare
  v_start timestamptz := date_trunc('day', now() at time zone 'Asia/Shanghai') at time zone 'Asia/Shanghai';
  v_budget numeric;
  v_spent numeric;
  v_runs integer;
begin
  select case when jsonb_typeof(s.value) = 'number' then (s.value #>> '{}')::numeric end
    into v_budget
    from public.system_settings s
   where s.key = 'admin_test_daily_budget_usd';

  select coalesce(sum(case
           when x.counted_usd is not null then x.counted_usd
           when x.started_at > now() - interval '10 minutes' then x.estimate_usd
           else 0
         end), 0),
         count(*)
    into v_spent, v_runs
    from public.admin_test_spend x
   where x.started_at >= v_start;

  return jsonb_build_object(
    'budget_usd', coalesce(v_budget, 5),
    'spent_usd', round(v_spent, 6),
    'runs', v_runs,
    'day', to_char(now() at time zone 'Asia/Shanghai', 'YYYY-MM-DD')
  );
end;
$$;


ALTER FUNCTION "public"."admin_test_budget_status"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_test_daily_costs"("p_days" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $$
declare
  v_today timestamptz;
  v_start timestamptz;
begin
  if p_days is null or p_days < 1 or p_days > 90 then
    raise exception 'INVALID_INPUT' using detail = 'p_days must be between 1 and 90';
  end if;

  v_today := date_trunc('day', now() at time zone 'UTC') at time zone 'UTC';
  v_start := v_today - make_interval(days => p_days - 1);

  return (
    with by_provider as (
      select date_trunc('day', x.started_at at time zone 'UTC') as day,
             coalesce(x.provider, 'unknown') as provider,
             coalesce(sum(x.cost_usd), 0) as cost_usd,
             bool_or(x.has_openrouter) as has_openrouter,
             count(*) as runs
        from public.admin_test_spend x
       where x.started_at >= v_start
       group by 1, 2
    ), days as (
      select p.day, sum(p.cost_usd) as cost_usd, sum(p.runs) as runs, bool_or(p.has_openrouter) as has_openrouter,
             jsonb_agg(jsonb_build_object('provider', p.provider, 'cost_usd', p.cost_usd, 'runs', p.runs)
                       order by p.provider) as by_provider
        from by_provider p group by p.day
    )
    select coalesce(jsonb_agg(jsonb_build_object(
             'day', to_char(d.day, 'YYYY-MM-DD'), 'cost_usd', d.cost_usd, 'runs', d.runs,
             'has_openrouter', d.has_openrouter, 'by_provider', d.by_provider
           ) order by d.day), '[]'::jsonb)
      from days d
  );
end;
$$;


ALTER FUNCTION "public"."admin_test_daily_costs"("p_days" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_todo_counts"() RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select jsonb_build_object(
    'stuck_jobs', (
      select count(*) from public.generation_jobs
       where status = 'running' and created_at < now() - interval '10 minutes'),
    'jobs_1h', (
      select jsonb_build_object('total', count(*), 'failed', count(*) filter (where status = 'failed'))
        from public.generation_jobs where created_at >= now() - interval '1 hour'),
    'jobs_24h', (
      select jsonb_build_object('total', count(*), 'failed', count(*) filter (where status = 'failed'))
        from public.generation_jobs where created_at >= now() - interval '24 hours'),
    'pending_requests', (
      select count(*) from public.template_requests where status = 'pending'),
    'unresolved_dispute_links', (
      select count(*) from public.payment_dispute_link_errors where resolved_at is null),
    'payment_issues', (
      select count(*) from public.payments
       where status <> 'paid' and created_at >= now() - interval '60 days'),
    'last_purchase_at', (
      select created_at from public.credit_ledger
       where kind = 'purchase' order by created_at desc, id desc limit 1),
    'provider', (
      select jsonb_build_object('label', label, 'model', model)
        from public.ai_providers where module = 'image' and is_active),
    'open_tickets', (
      select count(*) from public.support_tickets where status = 'open'),
    'overdue_tickets', (
      select count(*) from public.support_tickets t
       where t.status = 'open'
         and coalesce(
               (select max(m.created_at) from public.support_ticket_messages m
                 where m.ticket_id = t.id and m.author = 'user'),
               t.created_at)
             + make_interval(hours => public.support_reply_hours(public.current_tier(t.user_id))) < now())
  )
$$;


ALTER FUNCTION "public"."admin_todo_counts"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_top_inviters"("p_actor" "uuid", "p_days" integer DEFAULT 30) RETURNS TABLE("inviter_user_id" "uuid", "invited" bigint, "purchasers" bigint, "earned" bigint)
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $$
begin
  if not exists (select 1 from public.profiles where id = p_actor and role = 'admin' and banned_at is null) then
    raise exception 'NOT_ADMIN';
  end if;
  if p_days is not null and p_days <> 30 then raise exception 'INVALID_INPUT'; end if;
  return query
    select r.inviter_user_id, count(*),
      count(*) filter (where exists (select 1 from public.payments p where p.user_id = r.user_id and p.created_at >= r.created_at)),
      coalesce(sum(l.delta), 0)
    from public.code_redemptions r
    left join public.credit_ledger l on l.idempotency_key = 'invite:' || r.id::text
    where r.inviter_user_id is not null and r.status = 'ok'
      and (p_days is null or r.created_at >= now() - interval '30 days')
    group by r.inviter_user_id order by 2 desc, 3 desc, 4 desc, 1 limit 50;
end;
$$;


ALTER FUNCTION "public"."admin_top_inviters"("p_actor" "uuid", "p_days" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_unban_user"("p_user_id" "uuid", "p_reason" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if p_reason is null or length(btrim(p_reason)) = 0 then
    raise exception 'INVALID_INPUT' using detail = 'reason is required';
  end if;

  update public.profiles set banned_at = null where id = p_user_id;
  if not found then
    raise exception 'PROFILE_NOT_FOUND';
  end if;

  insert into public.admin_audit_log (action, user_id, reason) values ('unban_user', p_user_id, p_reason);
end;
$$;


ALTER FUNCTION "public"."admin_unban_user"("p_user_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_upsert_template"("p_template" "jsonb", "p_prompt" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  v_id text := p_template ->> 'id';
  v_provider uuid;
  v_model text;
  v_floor jsonb;
  v_resolution text;
  v_approved jsonb;
  unpriced text[];
begin
  perform 1 from public.templates where id = v_id for update;
  if v_id='edit' then v_provider:=null;
  elsif p_prompt ? 'provider_id' then
    v_provider := (p_prompt ->> 'provider_id')::uuid;
  else
    select provider_id into v_provider from public.template_prompts where template_id = v_id;
  end if;
  select p.id, p.model into v_provider, v_model from public.ai_providers p
    where p.module = 'image' and (p.id = v_provider or (v_provider is null and p.is_active)) for share;

  -- Older deployments send no pricing snapshot. New code derives it from site products and
  -- measured costs on the server; callers without the service role cannot invoke this RPC.
  if admin.is_template_catalog_v2() and (p_template#>>'{price_floors,version}') is distinct from 'v2' then
    raise exception 'MODEL_CHANGED' using detail='请刷新模板报价后再保存';
  end if;
  if p_template ? 'unpriced_resolutions' then
    unpriced:=array(select jsonb_array_elements_text(p_template->'unpriced_resolutions'));
  else
    select unpriced_resolutions into unpriced from public.template_sale_approvals where template_id=v_id;
  end if;
  if p_template ? 'price_floors' then
    v_floor := p_template->'price_floors'->'providers'->coalesce(v_provider::text, 'env');
    if v_floor is null or (v_provider is not null and p_template->'price_floors' ? 'models'
        and v_model is distinct from (p_template->'price_floors'->'models'->>v_provider::text)) then
      raise exception 'MODEL_CHANGED';
    end if;
    v_approved := admin.template_approved_prices(v_provider)->v_id;
    foreach v_resolution in array array['1k','2k','3k'] loop
      if v_resolution=any(unpriced) then continue; end if;
      if (p_template->'credits_cost'->>v_resolution)::integer <
          (v_floor->coalesce(p_template->>'quality','high')->>v_resolution)::integer
        and not coalesce(v_approved->>'quality'=p_template->>'quality'
          and v_approved->'costs'->v_resolution=p_template->'credits_cost'->v_resolution,false) then
        raise exception 'MODEL_CREDIT_FLOOR' using detail = format('%s 积分低于所选模型下限，请检查该档建议积分和成本估价', v_resolution);
      end if;
    end loop;
  end if;
  insert into public.templates as t (
    id, module, name, category, category_key, cover_before_url, cover_after_url,
    fields, quality, credits_cost, sort_order, is_active, visible_in, translations, description, featured_rank
  ) values (
    v_id,
    coalesce(p_template ->> 'module', 'image'),
    p_template ->> 'name',
    -- New code sends the key; old code and the prompt import send a name. The 0581 trigger
    -- fills whichever is missing.
    p_template ->> 'category',
    nullif(p_template ->> 'category_key', ''),
    nullif(p_template ->> 'cover_before_url', ''),
    nullif(p_template ->> 'cover_after_url', ''),
    coalesce(p_template -> 'fields', '{}'::jsonb),
    coalesce(p_template ->> 'quality', 'high'),
    -- Required: a template without its three prices must not save at some default.
    p_template -> 'credits_cost',
    -- New templates go to the end unless a position is given.
    coalesce(
      (p_template ->> 'sort_order')::integer,
      (select coalesce(max(sort_order), 0) + 10 from public.templates)
    ),
    coalesce((p_template ->> 'is_active')::boolean, false),
    array(select jsonb_array_elements_text(coalesce(p_template -> 'visible_in', '["web"]'::jsonb))),
    coalesce(p_template -> 'translations', '{}'::jsonb),
    nullif(btrim(p_template ->> 'description'), ''),
    (p_template ->> 'featured_rank')::smallint
  )
  on conflict (id) do update set
    module = excluded.module,
    name = excluded.name,
    category = excluded.category,
    -- After the BEFORE INSERT trigger, so always set (EXCLUDED carries the trigger's values).
    category_key = excluded.category_key,
    -- Only when the payload carries them: the editor leaves covers to the upload.
    cover_before_url = case when p_template ? 'cover_before_url' then excluded.cover_before_url else t.cover_before_url end,
    cover_after_url = case when p_template ? 'cover_after_url' then excluded.cover_after_url else t.cover_after_url end,
    fields = excluded.fields,
    quality = excluded.quality,
    credits_cost = excluded.credits_cost,
    sort_order = coalesce((p_template ->> 'sort_order')::integer, t.sort_order),
    is_active = coalesce((p_template ->> 'is_active')::boolean, t.is_active),
    visible_in = excluded.visible_in,
    -- The editor always sends the whole object; the prompt import script does not, and keeps it.
    translations = case when p_template ? 'translations' then excluded.translations else t.translations end,
    description = case when p_template ? 'description' then excluded.description else t.description end,
    featured_rank = case
      when p_template ? 'featured_rank' then excluded.featured_rank
      when coalesce((p_template ->> 'is_active')::boolean, t.is_active) and 'web' = any (excluded.visible_in) then t.featured_rank
      else null
    end;

  if p_prompt is not null then
    insert into public.template_prompts as tp (template_id, body, model_params, provider_id)
    values (v_id, p_prompt ->> 'body', coalesce(p_prompt -> 'model_params', '{}'::jsonb), (p_prompt ->> 'provider_id')::uuid)
    on conflict (template_id) do update set
      body = excluded.body,
      model_params = excluded.model_params,
      provider_id = case when p_prompt ? 'provider_id' then excluded.provider_id else tp.provider_id end;
  else
    perform admin.assert_template_reference_range(v_id);
  end if;
  perform admin.set_template_unpriced_resolutions(v_id,unpriced);
end;
$$;


ALTER FUNCTION "public"."admin_upsert_template"("p_template" "jsonb", "p_prompt" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_upsert_template"("p_template" "jsonb", "p_prompt" "jsonb", "p_style_refs" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare previous_refs text := current_setting('shotviva.save_style_refs',true);
begin
  if p_prompt is null then raise exception 'PROMPT_REQUIRED'; end if;
  -- A failed SQL statement rolls back its local settings; restore on success as well.
  perform set_config('shotviva.save_style_refs',
    jsonb_build_object('id',p_template->>'id','refs',p_style_refs)::text, true);
  perform public.admin_upsert_template(p_template, p_prompt);
  perform set_config('shotviva.save_style_refs',coalesce(previous_refs,''),true);
end;
$$;


ALTER FUNCTION "public"."admin_upsert_template"("p_template" "jsonb", "p_prompt" "jsonb", "p_style_refs" "jsonb") OWNER TO "postgres";


