CREATE OR REPLACE FUNCTION "public"."attach_ticket_images"("p_ticket_id" "uuid", "p_owner_id" "uuid", "p_message_id" "uuid", "p_images" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_prefix text := 'tickets/' || p_owner_id::text || '/' || p_ticket_id::text || '/';
  v_image jsonb;
begin
  if p_images is null or jsonb_typeof(p_images) = 'null' then
    return;
  end if;
  if jsonb_typeof(p_images) <> 'array' then
    raise exception 'INVALID_INPUT' using detail = 'images must be a list';
  end if;
  if jsonb_array_length(p_images) > 3 then
    raise exception 'INVALID_INPUT' using detail = 'at most 3 images per message';
  end if;

  for v_image in select value from jsonb_array_elements(p_images) loop
    if jsonb_typeof(v_image) <> 'object' or left(coalesce(v_image ->> 'object_key', ''), char_length(v_prefix)) <> v_prefix then
      raise exception 'INVALID_INPUT' using detail = 'image is not under this ticket';
    end if;
    begin
      insert into public.support_ticket_attachments (message_id, ticket_id, object_key, content_type, bytes, width, height)
      values (
        p_message_id,
        p_ticket_id,
        v_image ->> 'object_key',
        v_image ->> 'content_type',
        (v_image ->> 'bytes')::integer,
        (v_image ->> 'width')::integer,
        (v_image ->> 'height')::integer
      );
    exception
      when check_violation or not_null_violation or unique_violation
        or invalid_text_representation or numeric_value_out_of_range then
        raise exception 'INVALID_INPUT' using detail = 'image entry is invalid';
    end;
  end loop;
end;
$$;


ALTER FUNCTION "public"."attach_ticket_images"("p_ticket_id" "uuid", "p_owner_id" "uuid", "p_message_id" "uuid", "p_images" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."begin_identity_judge"("p_user_id" "uuid", "p_text_hash" "text", "p_per_hour" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  v_cached boolean;
  v_id bigint;
begin
  if p_user_id is null or p_per_hour is null or p_per_hour < 1 then
    raise exception 'INVALID_INPUT' using detail = 'user and a positive hourly limit are required';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('identity_judge:' || p_user_id::text, 0));

  if p_text_hash is not null then
    select c.identity_swap into v_cached
      from public.identity_judge_calls c
     where c.user_id = p_user_id and c.text_hash = p_text_hash and c.identity_swap is not null
       and c.created_at > now() - interval '10 minutes'
     order by c.created_at desc
     limit 1;
    if found then
      return jsonb_build_object('status', 'cached', 'identity_swap', v_cached);
    end if;
  end if;

  if (select count(*) from public.identity_judge_calls c
       where c.user_id = p_user_id and c.created_at > now() - interval '1 hour') >= p_per_hour then
    return jsonb_build_object('status', 'limited');
  end if;

  insert into public.identity_judge_calls (user_id, text_hash) values (p_user_id, p_text_hash)
  returning id into v_id;

  delete from public.identity_judge_calls c
   where c.id in (select o.id from public.identity_judge_calls o
                   where o.created_at < now() - interval '1 day'
                   order by o.created_at
                   limit 500);
  return jsonb_build_object('status', 'call', 'id', v_id);
end;
$$;


ALTER FUNCTION "public"."begin_identity_judge"("p_user_id" "uuid", "p_text_hash" "text", "p_per_hour" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."bump_template_prompt_version"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
begin
  if new.body is distinct from old.body or new.model_params is distinct from old.model_params
      or new.version = old.version + 1 then
    new.version := old.version + 1;
    new.updated_at := now();
  else
    new.version := old.version;
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."bump_template_prompt_version"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."catalog_channel_price"("p_product" "text", "p_revision" integer, "p_channel" "text", "p_key" "text", "p_recurring" boolean, "p_store" "text" DEFAULT NULL::"text", "p_mode" "text" DEFAULT NULL::"text") RETURNS "text"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_id text;
begin
  if p_channel='stripe' then
    select price_id into v_id from admin.catalog_stripe_prices
      where product_id=p_product and revision=p_revision and lookup_key=p_key;
  elsif p_channel='waffo' then
    select case when p_recurring then recurring_id else one_time_id end into v_id from admin.catalog_waffo_bindings
      where product_id=p_product and revision=p_revision and store_id=p_store and mode=p_mode;
  else raise exception 'INVALID_INPUT';
  end if;
  if v_id is null and (p_revision<>2 or not exists(select from admin.product_terms_v2 where product_id=p_product)
      or (p_channel='stripe' and exists(select from admin.catalog_stripe_prices where product_id=p_product and revision=p_revision))
      or (p_channel='waffo' and exists(select from admin.catalog_waffo_bindings where product_id=p_product and revision=p_revision))) then
    raise exception 'CATALOG_CHANNEL_UNVERIFIED';
  end if;
  return v_id;
end
$$;


ALTER FUNCTION "public"."catalog_channel_price"("p_product" "text", "p_revision" integer, "p_channel" "text", "p_key" "text", "p_recurring" boolean, "p_store" "text", "p_mode" "text") OWNER TO "postgres";


