CREATE OR REPLACE FUNCTION "public"."catalog_receipt"("p_token" "uuid", "p_user" "uuid", "p_product" "text", "p_revision" integer, "p_channel" "text", "p_price" "text", "p_unit" integer, "p_credits" integer, "p_ref" "text", "p_contract" "text", "p_renewal" boolean, "p_net" integer, "p_discounted" boolean, "p_record" boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  a admin.catalog_checkout_attempts;
  c admin.catalog_products;
  k text;
begin
  select * into strict a from admin.catalog_checkout_attempts where token=p_token for update;
  if (a.user_id,a.product_id,a.revision,a.channel,a.price_id,a.unit_cents,a.credits)
    is distinct from (p_user,p_product,p_revision,p_channel,p_price,p_unit,p_credits) then
    raise exception 'CATALOG_RECEIPT_MISMATCH'; end if;
  if (a.form='subscription') is distinct from (p_contract is not null) or (p_renewal and p_contract is null)
    then raise exception 'CATALOG_CONTRACT_MISMATCH'; end if;
  if p_channel='stripe' and p_net is distinct from
    (case when p_renewal and not p_discounted then a.unit_cents else a.net_cents end)
    then raise exception 'CATALOG_PAID_AMOUNT_MISMATCH'; end if;
  if p_channel='stripe' and not p_renewal then
    if a.session_id is not null and a.session_id<>p_ref then raise exception 'CATALOG_SESSION_MISMATCH'; end if;
    if p_record then update admin.catalog_checkout_attempts set session_id=p_ref where token=p_token; end if;
  end if;
  if p_record and p_contract is not null then
    insert into admin.catalog_contracts(channel,subscription_id,token) values (p_channel,p_contract,p_token)
      on conflict(channel,subscription_id) do nothing;
    if not exists(select from admin.catalog_contracts where channel=p_channel and subscription_id=p_contract and token=p_token)
      then raise exception 'CATALOG_CONTRACT_MISMATCH'; end if;
  end if;
  k := case when p_renewal and p_channel='stripe' then 'renewal:' else 'purchase:' end || p_ref;
  if p_record then
    insert into admin.catalog_receipts(event_key,token,initial_payment) values(k,p_token,not p_renewal)
      on conflict do nothing;
    if not exists(select from admin.catalog_receipts where event_key=k and token=p_token and initial_payment=not p_renewal)
      then raise exception 'IDEMPOTENCY_CONFLICT'; end if;
  end if;
  select * into strict c from admin.catalog_products where product_id=p_product;
  return jsonb_build_object('id',p_product,'tier',c.tier,'interval',
    case c.kind when 'monthly' then 'month' when 'yearly' then 'year' end,
    'paidDays',a.paid_days,'credits',a.credits,'priceUsd',a.unit_cents::numeric/100);
end
$$;


ALTER FUNCTION "public"."catalog_receipt"("p_token" "uuid", "p_user" "uuid", "p_product" "text", "p_revision" integer, "p_channel" "text", "p_price" "text", "p_unit" integer, "p_credits" integer, "p_ref" "text", "p_contract" "text", "p_renewal" boolean, "p_net" integer, "p_discounted" boolean, "p_record" boolean) OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."template_category_paths" WITH ("security_invoker"='true') AS
 SELECT "c"."key",
    COALESCE("g"."key", "p"."key", "c"."key") AS "root_key",
    "array_remove"(ARRAY["g"."slug", "p"."slug", "c"."slug"], NULL::"text") AS "path",
    ((NOT "c"."is_system") AND "c"."is_visible" AND (("c"."parent_id" IS NULL) OR ("p"."is_visible" IS TRUE)) AND (("p"."parent_id" IS NULL) OR ("g"."is_visible" IS TRUE))) AS "web_visible"
   FROM (("public"."template_categories" "c"
     LEFT JOIN "public"."template_categories" "p" ON (("p"."key" = "c"."parent_id")))
     LEFT JOIN "public"."template_categories" "g" ON (("g"."key" = "p"."parent_id")))
  WHERE ("c"."kind" = 'template'::"text");


ALTER VIEW "public"."template_category_paths" OWNER TO "postgres";


CREATE OR REPLACE VIEW "admin"."published_web_members" WITH ("security_invoker"='true') AS
 SELECT "t"."id",
    "t"."series_id",
    "t"."series_sort_order",
    "t"."sort_order",
    "c"."key" AS "category_key",
    (("t"."series_id" IS NULL) OR "s"."show_members") AS "standalone"
   FROM ((("public"."templates" "t"
     JOIN "public"."template_category_paths" "c" ON (("c"."key" = COALESCE("t"."subcategory_key", "t"."category_key"))))
     LEFT JOIN "public"."template_series" "s" ON (("s"."id" = "t"."series_id")))
     LEFT JOIN "public"."template_category_paths" "sc" ON (("sc"."key" = "s"."category_key")))
  WHERE ("t"."is_active" AND ('web'::"text" = ANY ("t"."visible_in")) AND "c"."web_visible" AND (("t"."series_id" IS NULL) OR ("s"."is_active" AND "sc"."web_visible")));


ALTER VIEW "admin"."published_web_members" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."web_template_members" WITH ("security_invoker"='true') AS
 SELECT "id",
    "series_id",
    "series_sort_order",
    "sort_order",
    "category_key",
    "standalone"
   FROM "admin"."published_web_members" "m"
  WHERE "admin"."web_standard_sale_allowed"("id");


ALTER VIEW "public"."web_template_members" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."web_catalogue_entries" WITH ("security_invoker"='true') AS
 SELECT 'template'::"text" AS "type",
    ('template-'::"text" || "m"."id") AS "entry_key",
    "m"."sort_order",
    "m"."category_key",
    "m"."id" AS "template_id",
    NULL::"uuid" AS "series_id",
    NULL::"text" AS "cover_template_id"
   FROM "public"."web_template_members" "m"
  WHERE "m"."standalone"
UNION ALL
 SELECT 'series'::"text" AS "type",
    ('series-'::"text" || "s"."id") AS "entry_key",
    "s"."sort_order",
    "c"."key" AS "category_key",
    NULL::"text" AS "template_id",
    "s"."id" AS "series_id",
    "cover"."id" AS "cover_template_id"
   FROM (("public"."template_series" "s"
     JOIN "public"."template_category_paths" "c" ON ((("c"."key" = "s"."category_key") AND "c"."web_visible")))
     CROSS JOIN LATERAL ( SELECT "m"."id"
           FROM "public"."web_template_members" "m"
          WHERE ("m"."series_id" = "s"."id")
          ORDER BY "m"."series_sort_order", "m"."id"
         LIMIT 1) "cover")
  WHERE "s"."is_active";


ALTER VIEW "public"."web_catalogue_entries" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."category_entries"("p_path" "text"[]) RETURNS SETOF "public"."web_catalogue_entries"
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  with recursive nodes(key,depth) as (
    select c.key,1 from public.template_categories c
    where cardinality(p_path) between 1 and 3 and c.parent_id is null and c.kind='template'
      and c.slug=p_path[1] and c.is_visible and not c.is_system
    union all
    select c.key,n.depth+1 from nodes n join public.template_categories c on c.parent_id=n.key
    where c.is_visible and (n.depth>=cardinality(p_path) or c.slug=p_path[n.depth+1])
  )
  select e.* from nodes n join public.web_catalogue_entries e on e.category_key=n.key
  where n.depth>=cardinality(p_path)
$$;


ALTER FUNCTION "public"."category_entries"("p_path" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."category_path"("public"."templates") RETURNS "text"[]
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $_$
  select c.path from public.template_category_paths c where c.key=coalesce($1.subcategory_key,$1.category_key)
$_$;


ALTER FUNCTION "public"."category_path"("public"."templates") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."check_referenced_provider_module"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
begin
  if exists (select 1 from public.template_prompts where provider_id = old.id) then
    raise exception 'PROVIDER_REFERENCED' using errcode = '23503';
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."check_referenced_provider_module"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."check_template_image_provider"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
begin
  perform 1 from public.ai_providers where id = new.provider_id and module = 'image' for share;
  if not found then
    raise exception 'PROVIDER_NOT_IMAGE' using errcode = '23503';
  end if;
  return new;
end;
