CREATE OR REPLACE FUNCTION "public"."clawback_payment_credits"("p_payment_id" bigint, "p_ref" "text", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_payment public.payments;
  v_granted integer;
  v_due integer;
  v_owed integer;
  v_balance integer;
  v_take integer := 0;
  v_key text;
begin
  if p_payment_id is null or p_ref is null or length(p_ref) = 0 or p_reason is null or length(p_reason) = 0 then
    raise exception 'INVALID_INPUT' using detail = 'payment id, ref and reason are required';
  end if;

  select * into v_payment from public.payments where id = p_payment_id for update;
  if not found then
    raise exception 'PAYMENT_NOT_FOUND';
  end if;

  v_granted := public._payment_granted_credits(v_payment);
  v_due := case
    when v_payment.status = 'disputed' then v_granted
    when v_payment.amount_refunded >= v_payment.amount_total then
      case when v_payment.amount_refunded > 0 or v_payment.status = 'refunded' then v_granted else 0 end
    else (v_granted::bigint * v_payment.amount_refunded / v_payment.amount_total)::integer
  end;
  v_owed := greatest(0, v_due - v_payment.credits_clawed_back - v_payment.clawback_shortfall);

  if v_owed > 0 then
    select credits into v_balance from public.profiles where id = v_payment.user_id for update;
    v_take := least(v_owed, greatest(coalesce(v_balance, 0), 0));
    if v_take > 0 then
      v_key := 'clawback:' || p_payment_id || ':' || p_ref;
      if not (public._apply_credit_change(v_payment.user_id, 'paid', 'clawback', -v_take, p_reason, v_key)).applied then
        -- This ref already settled its share (nothing left to do for it).
        v_take := 0;
        v_owed := 0;
      else
        update public.credit_ledger set payment_id = p_payment_id where idempotency_key = v_key;
      end if;
    end if;
    update public.payments
       set credits_clawed_back = credits_clawed_back + v_take,
           clawback_shortfall = clawback_shortfall + (v_owed - v_take)
     where id = p_payment_id
    returning * into v_payment;
  end if;

  return jsonb_build_object(
    'granted', v_granted,
    'taken', v_take,
    'written_off', v_owed - v_take,
    'credits_clawed_back', v_payment.credits_clawed_back,
    'clawback_shortfall', v_payment.clawback_shortfall
  );
end;
$$;


ALTER FUNCTION "public"."clawback_payment_credits"("p_payment_id" bigint, "p_ref" "text", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."close_payment_dispute"("p_dispute_id" "text", "p_status" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  v_row public.payment_disputes;
  v_open public.payment_disputes;
  v_payment public.payments;
  v_first boolean := false;
  v_superseded boolean := false;
  v_kept boolean := p_status in ('won', 'warning_closed');
  v_key text := 'clawback_restore:' || p_dispute_id;
begin
  if p_dispute_id is null or p_status is null or p_status !~ '^[a-z_]{1,40}$' then
    raise exception 'INVALID_INPUT' using detail = 'dispute id and status are required';
  end if;

  select * into v_row from public.payment_disputes where stripe_dispute_id = p_dispute_id;
  if not found then
    return null;
  end if;
  if v_row.payment_id is null then
    -- A purchase can now attach this orphan while close is running. Re-read
    -- after its charge lock before choosing the payment to lock and restore.
    perform pg_advisory_xact_lock(hashtextextended(v_row.stripe_charge_id, 914));
    select * into strict v_row from public.payment_disputes where stripe_dispute_id = p_dispute_id;
  end if;
  if v_row.payment_id is not null then
    select * into v_payment from public.payments where id = v_row.payment_id for update;
  end if;
  select * into v_row from public.payment_disputes where stripe_dispute_id = p_dispute_id for update;

  if v_row.closed_at is null then
    v_first := true;
    update public.payment_disputes set closed_status = p_status, closed_at = now()
     where stripe_dispute_id = p_dispute_id
    returning * into v_row;

    if v_row.payment_id is not null then
      select * into v_open from public.payment_disputes
       where payment_id = v_row.payment_id and closed_at is null
       order by created_at desc, stripe_dispute_id desc
       limit 1
       for update;
      if found then
        v_superseded := true;
        if v_kept then
          update public.payment_disputes
             set credits_clawed_back = credits_clawed_back + v_row.credits_clawed_back,
                 clawback_shortfall = clawback_shortfall + v_row.clawback_shortfall
           where stripe_dispute_id = v_open.stripe_dispute_id;
          update public.payment_disputes set credits_clawed_back = 0, clawback_shortfall = 0
           where stripe_dispute_id = p_dispute_id
          returning * into v_row;
        end if;
      elsif v_kept and not exists (
        select 1 from public.payment_disputes d
         where d.payment_id = v_row.payment_id
           and d.stripe_dispute_id <> p_dispute_id
           and d.closed_status not in ('won', 'warning_closed')
      ) then
        if v_row.credits_clawed_back > 0
           and (public._apply_credit_change(v_payment.user_id, 'paid', 'clawback_restore', v_row.credits_clawed_back,
                  '拒付胜诉还回 ' || p_dispute_id, v_key)).applied then
          update public.credit_ledger set payment_id = v_payment.id where idempotency_key = v_key;
        end if;
        update public.payments
           set credits_clawed_back = greatest(0, credits_clawed_back - v_row.credits_clawed_back),
               clawback_shortfall = greatest(0, clawback_shortfall - v_row.clawback_shortfall),
               status = case
                 when status <> 'disputed' then status
                 when amount_total > 0 and amount_refunded >= amount_total then 'refunded'
                 when amount_refunded > 0 then 'partially_refunded'
                 else 'paid'
               end
         where id = v_payment.id;
        update public.payment_disputes set credits_restored = v_row.credits_clawed_back
         where stripe_dispute_id = p_dispute_id
        returning * into v_row;
        perform public.clawback_payment_credits(v_payment.id, 'dispute_closed:' || p_dispute_id, '退款扣回 ' || p_dispute_id);
      end if;
    end if;
  end if;

  return jsonb_build_object(
    'first_close', v_first,
    -- Another dispute on the payment is still open and now decides (the Owner hears when it closes).
    'superseded', v_superseded,
    'kept', v_row.closed_status in ('won', 'warning_closed'),
    'closed_status', v_row.closed_status,
    'credits_restored', v_row.credits_restored,
    'user_id', v_row.user_id,
    'payment_id', v_row.payment_id,
    'product_id', v_payment.product_id,
    'amount', v_row.amount,
    'currency', v_row.currency
  );
end;
$_$;


ALTER FUNCTION "public"."close_payment_dispute"("p_dispute_id" "text", "p_status" "text") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."codes" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "code" "text" NOT NULL,
    "kind" "text" NOT NULL,
    "owner_user_id" "uuid",
    "invitee_credits" integer,
    "invitee_pool" "text",
    "discount_percent" integer,
    "discount_products" "text"[],
    "discount_duration" "text",
    "discount_months" integer,
    "discount_valid_days" integer,
    "stripe_coupon_id" "text",
    "starts_at" timestamp with time zone,
    "expires_at" timestamp with time zone,
    "max_redemptions" integer,
    "redemption_count" integer DEFAULT 0 NOT NULL,
    "new_users_only" boolean DEFAULT false NOT NULL,
    "active" boolean DEFAULT true NOT NULL,
    "note" "text",
    "created_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "codes_check" CHECK ((("kind" = 'invite'::"text") = ("owner_user_id" IS NOT NULL))),
    CONSTRAINT "codes_check1" CHECK ((("kind" <> 'invite'::"text") OR (("invitee_credits" IS NULL) AND ("discount_percent" IS NULL)))),
    CONSTRAINT "codes_check2" CHECK ((("kind" <> 'campaign'::"text") OR ("invitee_credits" IS NOT NULL) OR ("discount_percent" IS NOT NULL))),
    CONSTRAINT "codes_check3" CHECK ((("invitee_credits" IS NULL) = ("invitee_pool" IS NULL))),
    CONSTRAINT "codes_check4" CHECK ((("invitee_pool" <> 'paid'::"text") OR ("max_redemptions" IS NULL) OR ("max_redemptions" > 0))),
    CONSTRAINT "codes_check5" CHECK ((("discount_percent" IS NULL) = ("discount_products" IS NULL))),
    CONSTRAINT "codes_check6" CHECK ((("discount_percent" IS NULL) = ("discount_duration" IS NULL))),
    CONSTRAINT "codes_check7" CHECK ((("discount_percent" IS NOT NULL) OR (("discount_valid_days" IS NULL) AND ("stripe_coupon_id" IS NULL)))),
    CONSTRAINT "codes_check8" CHECK ((("discount_months" IS NOT NULL) = (NOT ("discount_duration" IS DISTINCT FROM 'repeating'::"text")))),
    CONSTRAINT "codes_check9" CHECK (("expires_at" > "starts_at")),
    CONSTRAINT "codes_code_check" CHECK (("code" ~ '^[A-Z0-9]{4,20}$'::"text")),
    CONSTRAINT "codes_discount_duration_check" CHECK (("discount_duration" = ANY (ARRAY['once'::"text", 'repeating'::"text", 'forever'::"text"]))),
    CONSTRAINT "codes_discount_months_check" CHECK (("discount_months" > 0)),
    CONSTRAINT "codes_discount_percent_check" CHECK ((("discount_percent" >= 1) AND ("discount_percent" <= 90))),
    CONSTRAINT "codes_discount_products_check" CHECK ((("discount_products" IS NULL) OR (("cardinality"("discount_products") > 0) AND ("array_position"("discount_products", NULL::"text") IS NULL) AND ("array_to_string"("discount_products", ' '::"text") ~ '^[a-z][a-z0-9_]{0,63}( [a-z][a-z0-9_]{0,63})*$'::"text")))),
    CONSTRAINT "codes_discount_valid_days_check" CHECK (("discount_valid_days" > 0)),
    CONSTRAINT "codes_invitee_credits_check" CHECK (("invitee_credits" > 0)),
    CONSTRAINT "codes_invitee_pool_check" CHECK (("invitee_pool" = ANY (ARRAY['free'::"text", 'paid'::"text"]))),
    CONSTRAINT "codes_kind_check" CHECK (("kind" = ANY (ARRAY['invite'::"text", 'campaign'::"text"]))),
    CONSTRAINT "codes_max_redemptions_check" CHECK (("max_redemptions" > 0)),
    CONSTRAINT "codes_redemption_count_check" CHECK (("redemption_count" >= 0))
);


ALTER TABLE "public"."codes" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."code_preview_credits"("offer" "public"."codes") RETURNS integer
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  select case when offer.kind = 'invite' then
    (select (value->>'inviteeCredits')::integer from public.system_settings where key = 'code_invite_rewards')
    else coalesce(offer.invitee_credits, 0) end;
$$;


ALTER FUNCTION "public"."code_preview_credits"("offer" "public"."codes") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."generation_jobs" (
    "id" "uuid" NOT NULL,
    "user_id" "uuid" NOT NULL,
    "module" "text" NOT NULL,
    "template_id" "text" NOT NULL,
    "inputs" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "provider" "text",
    "source" "text" NOT NULL,
    "idempotency_key" "text",
    "status" "text" DEFAULT 'running'::"text" NOT NULL,
    "visibility" "text" NOT NULL,
    "credits_cost" integer NOT NULL,
    "output_key" "text",
    "error_code" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "finished_at" timestamp with time zone,
    "credit_pool" "text" NOT NULL,
    "parent_job_id" "uuid",
    "provider_usage" "jsonb",
    "cost_usd" numeric(10,6),
    "deleted_at" timestamp with time zone,
    "client_ip" "inet",
    "downloaded_at" timestamp with time zone,
    "download_ip" "inet",
    "download_count" integer DEFAULT 0 NOT NULL,
    "batch_id" "uuid",
    "moderation_status" "text" DEFAULT 'pending'::"text" NOT NULL,
    "moderation_reason" "text",
    "moderation_categories" "text"[] DEFAULT '{}'::"text"[] NOT NULL,
    "auto_moderated_at" timestamp with time zone,
    "moderated_at" timestamp with time zone,
    "moderated_by" "uuid",
    CONSTRAINT "generation_jobs_check" CHECK ((("status" = 'running'::"text") = ("finished_at" IS NULL))),
    CONSTRAINT "generation_jobs_check1" CHECK ((("status" <> 'succeeded'::"text") OR ("output_key" IS NOT NULL))),
    CONSTRAINT "generation_jobs_cost_usd_nonnegative" CHECK ((("cost_usd" IS NULL) OR ("cost_usd" >= (0)::numeric))),
    CONSTRAINT "generation_jobs_credit_pool_check" CHECK (("credit_pool" = ANY (ARRAY['free'::"text", 'paid'::"text"]))),
    CONSTRAINT "generation_jobs_credits_cost_check" CHECK (("credits_cost" > 0)),
    CONSTRAINT "generation_jobs_download_count_check" CHECK (("download_count" >= 0)),
    CONSTRAINT "generation_jobs_free_work_public" CHECK ((("credit_pool" = 'paid'::"text") OR ("visibility" = 'public'::"text"))),
    CONSTRAINT "generation_jobs_moderation_reason_check" CHECK (("moderation_reason" = ANY (ARRAY['auto'::"text", 'sexual'::"text", 'violence'::"text", 'hate'::"text", 'minor'::"text", 'privacy'::"text", 'ip'::"text", 'spam'::"text", 'quality'::"text", 'other'::"text"]))),
    CONSTRAINT "generation_jobs_moderation_status_check" CHECK (("moderation_status" = ANY (ARRAY['pending'::"text", 'approved'::"text", 'rejected'::"text"]))),
    CONSTRAINT "generation_jobs_module_check" CHECK (("module" = ANY (ARRAY['image'::"text", 'video'::"text"]))),
    CONSTRAINT "generation_jobs_provider_usage_object" CHECK ((("provider_usage" IS NULL) OR ("jsonb_typeof"("provider_usage") = 'object'::"text"))),
    CONSTRAINT "generation_jobs_source_check" CHECK (("source" = ANY (ARRAY['web'::"text", 'graylum'::"text"]))),
    CONSTRAINT "generation_jobs_status_check" CHECK (("status" = ANY (ARRAY['running'::"text", 'succeeded'::"text", 'failed'::"text"]))),
    CONSTRAINT "generation_jobs_visibility_check" CHECK (("visibility" = ANY (ARRAY['public'::"text", 'private'::"text"])))
);


ALTER TABLE "public"."generation_jobs" OWNER TO "postgres";


COMMENT ON COLUMN "public"."generation_jobs"."deleted_at" IS 'When the owner deleted this work (T41). Set only by delete_own_job; user-facing reads skip it.';



CREATE OR REPLACE FUNCTION "public"."confirm_job"("p_job_id" "uuid", "p_output_key" "text", "p_provider_usage" "jsonb" DEFAULT NULL::"jsonb", "p_cost_usd" numeric DEFAULT NULL::numeric, "p_kept_inputs" "text"[] DEFAULT NULL::"text"[]) RETURNS "public"."generation_jobs"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_job public.generation_jobs;
  v_prefix text;
  v_kept text[];
begin
  select * into v_job from public.generation_jobs where id = p_job_id for update;
  if not found then
    raise exception 'JOB_NOT_FOUND';
  end if;
  -- A repeat keeps the first settlement, usage, cost and kept inputs included.
  if v_job.status = 'succeeded' then
    return v_job;
  end if;
  if v_job.status = 'failed' then
    raise exception 'JOB_ALREADY_SETTLED';
  end if;
  if p_output_key is null or length(p_output_key) = 0 then
    raise exception 'INVALID_INPUT' using detail = 'output_key is required';
  end if;

  v_prefix := 'outputs/' || v_job.user_id::text || '/' || v_job.id::text || '-in-';
  select array_agg(k order by n) into v_kept
    from unnest(coalesce(p_kept_inputs, '{}'::text[])) with ordinality as t(k, n)
   where n <= 30 and k is not null and left(k, length(v_prefix)) = v_prefix and k not like '%/../%';

  update public.generation_jobs
     set status = 'succeeded', output_key = p_output_key, finished_at = now(),
         provider_usage = p_provider_usage, cost_usd = p_cost_usd,
         inputs = case when v_kept is null then inputs else inputs || jsonb_build_object('kept_inputs', to_jsonb(v_kept)) end
   where id = p_job_id
  returning * into v_job;
  return v_job;
end;
$$;


ALTER FUNCTION "public"."confirm_job"("p_job_id" "uuid", "p_output_key" "text", "p_provider_usage" "jsonb", "p_cost_usd" numeric, "p_kept_inputs" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_support_ticket"("p_user_id" "uuid", "p_type" "text", "p_body" "text", "p_payment_id" bigint, "p_job_id" "uuid", "p_ticket_id" "uuid" DEFAULT NULL::"uuid", "p_images" "jsonb" DEFAULT '[]'::"jsonb") RETURNS "public"."support_tickets"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_ticket public.support_tickets;
  v_message_id uuid;
begin
  perform 1 from public.profiles where id = p_user_id for update;
  if not found then
    raise exception 'PROFILE_NOT_FOUND';
  end if;

  if p_type is null or p_type not in ('feedback', 'image_issue', 'billing', 'refund', 'account', 'other') then
    raise exception 'INVALID_INPUT' using detail = 'unknown ticket type';
  end if;
  if p_body is null or char_length(btrim(p_body)) not between 1 and 2000 then
    raise exception 'INVALID_INPUT' using detail = 'body must be 1 to 2000 characters';
  end if;
  if p_type = 'refund' and p_payment_id is null then
    raise exception 'INVALID_INPUT' using detail = 'a refund request needs a payment';
  end if;
  if p_payment_id is not null and p_type not in ('billing', 'refund') then
    raise exception 'INVALID_INPUT' using detail = 'only billing and refund tickets take a payment';
  end if;
  if p_job_id is not null and p_type <> 'image_issue' then
    raise exception 'INVALID_INPUT' using detail = 'only image issues take a work';
  end if;

  -- Someone else's id reads the same as a missing one, so nothing leaks about other accounts.
  if p_payment_id is not null and not exists (
    select 1 from public.payments p where p.id = p_payment_id and p.user_id = p_user_id
  ) then
    raise exception 'PAYMENT_NOT_FOUND';
  end if;
  if p_job_id is not null and not exists (
    select 1 from public.generation_jobs j where j.id = p_job_id and j.user_id = p_user_id
  ) then
    raise exception 'JOB_NOT_FOUND';
  end if;

  if (select count(*) from public.support_tickets t
       where t.user_id = p_user_id and t.created_at > now() - interval '24 hours') >= 5 then
    raise exception 'RATE_LIMITED';
  end if;

  insert into public.support_tickets (id, user_id, type, payment_id, job_id)
  values (coalesce(p_ticket_id, gen_random_uuid()), p_user_id, p_type, p_payment_id, p_job_id)
  returning * into v_ticket;

  insert into public.support_ticket_messages (ticket_id, author, body)
  values (v_ticket.id, 'user', btrim(p_body))
  returning id into v_message_id;

  perform public.attach_ticket_images(v_ticket.id, p_user_id, v_message_id, p_images);
  return v_ticket;
end;
$$;


ALTER FUNCTION "public"."create_support_ticket"("p_user_id" "uuid", "p_type" "text", "p_body" "text", "p_payment_id" bigint, "p_job_id" "uuid", "p_ticket_id" "uuid", "p_images" "jsonb") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."template_requests" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "user_id" "uuid" NOT NULL,
    "description" "text" NOT NULL,
    "image_keys" "text"[] NOT NULL,
    "status" "text" DEFAULT 'pending'::"text" NOT NULL,
    "template_id" "text",
    "votes_count" integer DEFAULT 0 NOT NULL,
    "author_label" "text" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "reviewed_at" timestamp with time zone,
    CONSTRAINT "template_requests_author_label_check" CHECK (("author_label" ~ '^.\*\*\*$'::"text")),
    CONSTRAINT "template_requests_description_check" CHECK ((("char_length"("btrim"("description")) >= 1) AND ("char_length"("btrim"("description")) <= 300))),
    CONSTRAINT "template_requests_images" CHECK (
CASE
    WHEN ("status" = 'rejected'::"text") THEN ("cardinality"("image_keys") = 0)
    ELSE (("cardinality"("image_keys") >= 1) AND ("cardinality"("image_keys") <= 3))
END),
    CONSTRAINT "template_requests_reviewed" CHECK ((("status" = 'pending'::"text") = ("reviewed_at" IS NULL))),
    CONSTRAINT "template_requests_shipped_template" CHECK ((("status" = 'shipped'::"text") = ("template_id" IS NOT NULL))),
    CONSTRAINT "template_requests_status_check" CHECK (("status" = ANY (ARRAY['pending'::"text", 'live'::"text", 'shipped'::"text", 'rejected'::"text"]))),
    CONSTRAINT "template_requests_votes_count_check" CHECK (("votes_count" >= 0))
);


ALTER TABLE "public"."template_requests" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_template_request"("p_user_id" "uuid", "p_description" "text", "p_image_keys" "text"[]) RETURNS "public"."template_requests"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  v_request public.template_requests;
  v_name text;
  v_key text;
begin
  perform 1 from public.profiles where id = p_user_id for update;
  if not found then
    raise exception 'PROFILE_NOT_FOUND';
  end if;

  if not public.wishlist_eligible(p_user_id) then
    raise exception 'WISHLIST_NOT_ELIGIBLE';
  end if;

  if cardinality(coalesce(p_image_keys, '{}')) not between 1 and 3 then
    raise exception 'INVALID_INPUT' using detail = '1 to 3 reference images';
  end if;
  foreach v_key in array p_image_keys loop
    if v_key is null or v_key !~ ('^requests/' || p_user_id::text || '/[0-9a-f-]{36}\.jpg$') then
      raise exception 'INVALID_INPUT' using detail = 'image key outside the author prefix';
    end if;
  end loop;

  if (select count(*) from public.template_requests r
       where r.user_id = p_user_id and r.created_at > now() - interval '24 hours') >= 5 then
    raise exception 'RATE_LIMITED';
  end if;

  -- Display name first (Google sign-ups), else the email; only its first letter leaves here.
  select coalesce(nullif(btrim(u.raw_user_meta_data ->> 'full_name'), ''),
                  nullif(btrim(u.raw_user_meta_data ->> 'name'), ''),
                  u.email,
                  '?')
    into v_name
    from auth.users u
   where u.id = p_user_id;

  insert into public.template_requests (user_id, description, image_keys, author_label)
  values (p_user_id, btrim(p_description), p_image_keys, upper(left(coalesce(v_name, '?'), 1)) || '***')
  returning * into v_request;
  return v_request;
end;
$_$;


ALTER FUNCTION "public"."create_template_request"("p_user_id" "uuid", "p_description" "text", "p_image_keys" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."current_tier"("p_user_id" "uuid") RETURNS "text"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_paid_until timestamptz;
  v_tier text;
begin
  select paid_until into v_paid_until from public.profiles where id = p_user_id;
  if v_paid_until is null or v_paid_until <= now() then
    return null;
  end if;

  select c.tier into v_tier
    from public.credit_ledger l join admin.catalog_products c on c.product_id=l.product_id
   where l.user_id = p_user_id
     and l.pool = 'paid'
     and l.delta > 0
     and l.product_id is not null
     and not starts_with(l.product_id,'pack_') and c.kind<>'pack'
     and not exists (
       select 1 from public.payments p
        where p.user_id = p_user_id
          and p.status in ('refunded', 'partially_refunded')
          and l.idempotency_key in ('purchase:' || p.stripe_session_id, 'renewal:' || p.stripe_invoice_id, 'purchase:' || p.waffo_payment_id)
     )
   order by l.created_at desc, l.id desc
   limit 1;

  return v_tier;
end;
$$;


ALTER FUNCTION "public"."current_tier"("p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."delete_own_job"("p_job_id" "uuid", "p_user_id" "uuid") RETURNS "public"."generation_jobs"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_job public.generation_jobs;
begin
  select * into v_job from public.generation_jobs
   where id = p_job_id and user_id = p_user_id
     for update;
  if not found then
    raise exception 'JOB_NOT_FOUND';
  end if;
  if v_job.deleted_at is not null then
    return v_job;
  end if;
  if v_job.status = 'running' then
    raise exception 'JOB_RUNNING';
  end if;

  update public.generation_jobs
     set deleted_at = now(), inputs = inputs - 'note' - 'copy' - 'instruction'
   where id = p_job_id
  returning * into v_job;
  return v_job;
end;
$$;


ALTER FUNCTION "public"."delete_own_job"("p_job_id" "uuid", "p_user_id" "uuid") OWNER TO "postgres";


