    (select s.value::text::integer from public.system_settings s where s.key = 'code_inviter_window_days'))
    || jsonb_build_object('rewards', (select value from public.system_settings where key = 'code_invite_rewards'));
$$;


ALTER FUNCTION "public"."my_invite_summary"("p_user" "uuid", "p_inviter_cap" integer, "p_cursor" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."my_invite_summary"("p_user" "uuid", "p_inviter_cap" integer, "p_cursor" "jsonb", "p_reward_window_days" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  v_code text;
  v_result jsonb;
begin
  if p_inviter_cap is null or p_inviter_cap < 0 or p_reward_window_days is null or p_reward_window_days <= 0 then raise exception 'INVALID_INPUT'; end if;
  v_code := public.get_or_create_invite_code(p_user);
  with invited as materialized (
    select r.id, r.user_id, r.created_at,
      exists(select 1 from public.payments p where p.user_id = r.user_id and p.created_at >= r.created_at) as purchased
    from public.code_redemptions r where r.inviter_user_id = p_user and r.status = 'ok'
  ),
  page as (
    select i.id, i.created_at, pr.created_at as registered_at, i.purchased
    from invited i join public.profiles pr on pr.id = i.user_id
    where p_cursor is null or (i.created_at,i.id) < ((p_cursor->>'created_at')::timestamptz,(p_cursor->>'id')::uuid)
    order by i.created_at desc, i.id desc limit 30
  ),
  rewards as (
    select coalesce(sum(l.delta),0) as earned,
      count(*) filter (where l.created_at > now() - make_interval(days => p_reward_window_days)) as used
    from public.credit_ledger l where l.user_id = p_user and l.kind = 'invite_reward'
  )
  select jsonb_build_object('code', v_code, 'invited', count(*),
    'purchasers', count(*) filter (where i.purchased), 'earned', (select earned from rewards),
    'reward_window_days', p_reward_window_days,
    'rewards_left', greatest(0, p_inviter_cap - (select used from rewards)),
    'friends', coalesce((select jsonb_agg(to_jsonb(p) order by p.created_at desc, p.id desc) from page p), '[]'::jsonb))
  into v_result from invited i;
  return v_result;
end;
$$;


ALTER FUNCTION "public"."my_invite_summary"("p_user" "uuid", "p_inviter_cap" integer, "p_cursor" "jsonb", "p_reward_window_days" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."open_payment_dispute"("p_dispute_id" "text", "p_charge_id" "text", "p_amount" integer, "p_currency" "text", "p_reason" "text", "p_due_by" timestamp with time zone, "p_managed_default" boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_row public.payment_disputes;
  v_payment public.payments;
  v_managed boolean;
  v_profile public.profiles;
  v_claw jsonb;
begin
  if p_dispute_id is null or p_charge_id is null or p_amount is null or p_currency is null
     or p_reason is null or p_managed_default is null then
    raise exception 'INVALID_INPUT' using detail = 'dispute id, charge id, amount, currency, reason and the default are required';
  end if;

  select * into v_row from public.payment_disputes where stripe_dispute_id = p_dispute_id;
  if found then
    return public._payment_dispute_answer(v_row, false);
  end if;

  -- Locked first: every T71 path locks the payment before the profile (and before other
  -- disputes of it), so a refund and a dispute arriving together cannot deadlock.
  select * into v_payment from public.payments where stripe_charge_id = p_charge_id for update;
  v_managed := case
    when v_payment.id is null then p_managed_default
    when v_payment.method = 'cn_card' then false
    when v_payment.method = 'card' then coalesce(
      v_payment.managed_payments,
      (select p.managed_payments from public.payments p
        where p.user_id = v_payment.user_id and p.product_id = v_payment.product_id
          and p.channel = 'stripe' and p.stripe_session_id is not null
          and p.created_at <= v_payment.created_at
        order by p.created_at desc limit 1),
      p_managed_default)
    else p_managed_default
  end;

  insert into public.payment_disputes
    (stripe_dispute_id, stripe_charge_id, payment_id, user_id, amount, currency, reason, responder, due_by)
  values
    (p_dispute_id, p_charge_id, v_payment.id, v_payment.user_id, p_amount, lower(p_currency), p_reason,
     case when v_managed then 'stripe' else 'shotviva' end, p_due_by)
  on conflict (stripe_dispute_id) do nothing
  returning * into v_row;
  if not found then
    -- A concurrent delivery inserted it first; that one bans and claws back.
    select * into v_row from public.payment_disputes where stripe_dispute_id = p_dispute_id;
    return public._payment_dispute_answer(v_row, false);
  end if;

  if v_row.user_id is not null then
    select * into v_profile from public.profiles where id = v_row.user_id for update;
    if found and v_profile.role <> 'admin' and v_profile.banned_at is null then
      perform public.admin_ban_user(v_row.user_id, '拒付');
      update public.payment_disputes set auto_banned_at = now()
       where stripe_dispute_id = p_dispute_id
      returning * into v_row;
    end if;
  end if;

  if v_row.payment_id is not null then
    -- record_payment_issue marks it first; set here too so the clawback asks for everything.
    update public.payments set status = 'disputed' where id = v_row.payment_id and status <> 'disputed';
    v_claw := public.clawback_payment_credits(v_row.payment_id, 'dispute:' || p_dispute_id, '拒付扣回 ' || p_dispute_id);
    update public.payment_disputes
       set credits_clawed_back = (v_claw ->> 'taken')::integer,
           clawback_shortfall = (v_claw ->> 'written_off')::integer
     where stripe_dispute_id = p_dispute_id
    returning * into v_row;
  end if;

  return public._payment_dispute_answer(v_row, true);
end;
$$;


ALTER FUNCTION "public"."open_payment_dispute"("p_dispute_id" "text", "p_charge_id" "text", "p_amount" integer, "p_currency" "text", "p_reason" "text", "p_due_by" timestamp with time zone, "p_managed_default" boolean) OWNER TO "postgres";


