CREATE OR REPLACE FUNCTION "public"."record_payment_context"("p_session_id" "text", "p_ip" "inet" DEFAULT NULL::"inet", "p_user_agent" "text" DEFAULT NULL::"text", "p_terms_accepted_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_managed_payments" boolean DEFAULT NULL::boolean) RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if p_session_id is null or p_session_id not like 'cs\_%' then
    raise exception 'INVALID_INPUT' using detail = 'a cs_ session id is required';
  end if;

  update public.payments
     set purchase_ip = coalesce(purchase_ip, p_ip),
         purchase_user_agent = coalesce(purchase_user_agent, nullif(left(p_user_agent, 500), '')),
         terms_accepted_at = coalesce(terms_accepted_at, p_terms_accepted_at),
         managed_payments = coalesce(managed_payments, p_managed_payments)
   where stripe_session_id = p_session_id;
  return found;
end;
$$;


ALTER FUNCTION "public"."record_payment_context"("p_session_id" "text", "p_ip" "inet", "p_user_agent" "text", "p_terms_accepted_at" timestamp with time zone, "p_managed_payments" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_payment_issue"("p_charge_id" "text", "p_kind" "text", "p_amount_refunded" integer DEFAULT NULL::integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_payment public.payments;
  v_membership boolean := false;
  v_paid_until timestamptz;
begin
  if p_charge_id is null or p_kind is null or p_kind not in ('refunded', 'disputed') then
    raise exception 'INVALID_INPUT' using detail = 'charge id and kind (refunded / disputed) are required';
  end if;
  if p_kind = 'refunded' and (p_amount_refunded is null or p_amount_refunded < 0) then
    raise exception 'INVALID_INPUT' using detail = 'refund needs the refunded amount';
  end if;

  if p_kind = 'refunded' then
    update public.payments
       set amount_refunded = least(amount_total, greatest(amount_refunded, p_amount_refunded)),
           status = case
             when status = 'disputed' then status
             when least(amount_total, greatest(amount_refunded, p_amount_refunded)) >= amount_total then 'refunded'
             when greatest(amount_refunded, p_amount_refunded) > 0 then 'partially_refunded'
             else status
           end
     where stripe_charge_id = p_charge_id
    returning * into v_payment;
  else
    update public.payments
       set status = case
             when exists (select 1 from public.payment_disputes d where d.stripe_charge_id = p_charge_id)
              and not exists (select 1 from public.payment_disputes d where d.stripe_charge_id = p_charge_id and d.closed_at is null)
             then status
             else 'disputed'
           end
     where stripe_charge_id = p_charge_id
    returning * into v_payment;
  end if;

  if not found then
    return null;
  end if;

  if p_kind = 'disputed' then
    return jsonb_build_object(
      'payment_id', v_payment.id,
      'user_id', v_payment.user_id,
      'product_id', v_payment.product_id,
      'status', v_payment.status,
      'amount_total', v_payment.amount_total,
      'amount_refunded', v_payment.amount_refunded,
      'currency', v_payment.currency
    );
  end if;

  if v_payment.amount_refunded > 0 then
    perform public.clawback_payment_credits(
      v_payment.id, 'refund:' || p_charge_id || ':' || v_payment.amount_refunded, '退款扣回 ' || p_charge_id);
    if exists (select 1 from public.products where id = v_payment.product_id and days is not null) then
      v_membership := public._end_membership_after_refund(v_payment.user_id, v_payment);
    end if;
    select * into v_payment from public.payments where id = v_payment.id;
    select paid_until into v_paid_until from public.profiles where id = v_payment.user_id;
  end if;

  return jsonb_build_object(
    'payment_id', v_payment.id,
    'user_id', v_payment.user_id,
    'product_id', v_payment.product_id,
    'status', v_payment.status,
    'amount_total', v_payment.amount_total,
    'amount_refunded', v_payment.amount_refunded,
    'currency', v_payment.currency,
    'credits_clawed_back', v_payment.credits_clawed_back,
    'clawback_shortfall', v_payment.clawback_shortfall,
    'membership_ended', v_membership,
    'paid_until', v_paid_until,
    'stripe_session_id', v_payment.stripe_session_id,
    'stripe_invoice_id', v_payment.stripe_invoice_id
  );
end;
$$;


ALTER FUNCTION "public"."record_payment_issue"("p_charge_id" "text", "p_kind" "text", "p_amount_refunded" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_waffo_refund"("p_payment_id" "text", "p_refund_ref" "text", "p_amount" integer DEFAULT NULL::integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_payment public.payments;
  v_amount integer;
  v_membership boolean;
  v_paid_until timestamptz;
begin
  if p_payment_id is null or p_refund_ref is null or length(p_refund_ref) = 0 or p_amount < 0 then
    raise exception 'INVALID_INPUT' using detail = 'payment id and refund ref are required';
  end if;

  select * into v_payment from public.payments where waffo_payment_id = p_payment_id for update;
  if not found then
    return null;
  end if;

  v_amount := least(coalesce(p_amount, v_payment.amount_total - v_payment.amount_refunded), v_payment.amount_total);
  insert into public.payment_refunds (refund_ref, payment_id, amount)
  values (p_refund_ref, v_payment.id, v_amount)
  on conflict (refund_ref) do nothing;
  if found then
    update public.payments
       set amount_refunded = least(amount_total, amount_refunded + v_amount),
           status = case
             when status = 'disputed' then status
             when least(amount_total, amount_refunded + v_amount) >= amount_total then 'refunded'
             when amount_refunded + v_amount > 0 then 'partially_refunded'
             else status
           end
     where id = v_payment.id
    returning * into v_payment;
  end if;

  v_membership := false;
  if v_payment.amount_refunded > 0 then
    perform public.clawback_payment_credits(v_payment.id, 'refund:' || p_refund_ref, '退款扣回 ' || p_refund_ref);
    if exists (select 1 from public.products where id = v_payment.product_id and days is not null) then
      v_membership := public._end_membership_after_refund(v_payment.user_id, v_payment);
    end if;
    select * into v_payment from public.payments where id = v_payment.id;
    select paid_until into v_paid_until from public.profiles where id = v_payment.user_id;
  end if;

  return jsonb_build_object(
    'payment_id', v_payment.id,
    'user_id', v_payment.user_id,
    'product_id', v_payment.product_id,
    'status', v_payment.status,
    'amount_total', v_payment.amount_total,
    'amount_refunded', v_payment.amount_refunded,
    'currency', v_payment.currency,
    'credits_clawed_back', v_payment.credits_clawed_back,
    'clawback_shortfall', v_payment.clawback_shortfall,
    'membership_ended', v_membership,
    'paid_until', v_paid_until,
    'waffo_order_id', v_payment.waffo_order_id
  );
end;
$$;


ALTER FUNCTION "public"."record_waffo_refund"("p_payment_id" "text", "p_refund_ref" "text", "p_amount" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_work_auto_moderation"("p_job_id" "uuid", "p_flagged" boolean, "p_categories" "text"[]) RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_auto boolean;
  v_status text;
begin
  if p_job_id is null or p_flagged is null then
    raise exception 'INVALID_INPUT' using detail = 'job and verdict are required';
  end if;
  select coalesce((select s.value = 'true'::jsonb from public.system_settings s where s.key = 'gallery_auto_approve'), false)
    into v_auto;

  update public.generation_jobs j
     set auto_moderated_at = now(),
         moderation_categories = coalesce(p_categories, '{}'),
         moderation_status = case
           when j.moderation_status <> 'pending' then j.moderation_status
           when p_flagged then 'rejected'
           when v_auto then 'approved'
           else 'pending' end,
         moderation_reason = case
           when j.moderation_status = 'pending' and p_flagged then 'auto' else j.moderation_reason end,
         moderated_at = case
           when j.moderation_status = 'pending' and (p_flagged or v_auto) then now() else j.moderated_at end
   where j.id = p_job_id and j.status = 'succeeded' and j.visibility = 'public' and j.deleted_at is null
  returning j.moderation_status into v_status;
  return v_status;
end;
$$;


ALTER FUNCTION "public"."record_work_auto_moderation"("p_job_id" "uuid", "p_flagged" boolean, "p_categories" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."redeem_code"("p_user" "uuid", "p_code" "text", "p_context" "text", "p_invitee_credits" integer, "p_invite_window_days" integer, "p_replace" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  offer record;
  profile record;
  inviter record;
  pending record;
  owner_id uuid;
  redemption_id uuid := gen_random_uuid();
  checked_at timestamptz;
  deadline timestamptz;
  grant_pool text;
  credits int;
  outcome text := 'ok';
  replaced boolean := false;
begin
  if p_context is null or p_context not in ('signup','account','paywall')
     or p_invite_window_days is null or p_invite_window_days <= 0 then
    raise exception 'INVALID_INPUT';
  end if;

  if p_code is null or p_code collate "C" !~ '^[A-Za-z0-9]{4,20}$' then
    return jsonb_build_object('status', 'not_found');
  end if;
  select owner_user_id into owner_id from public.codes where code = upper(p_code);
  if not found then return jsonb_build_object('status', 'not_found'); end if;
  -- Lock participants in a consistent order before the code. A reciprocal pair of invites
  -- also touches both profiles via FKs and the existing balance helper's FOR UPDATE.
  perform 1 from public.profiles where id in (p_user, owner_id) order by id for no key update;
  select banned_at, signup_ip, created_at into profile from public.profiles where id = p_user;
  if not found then raise exception 'PROFILE_NOT_FOUND'; end if;
  select id, kind, owner_user_id, invitee_credits, invitee_pool, active, starts_at, expires_at,
         max_redemptions, redemption_count, new_users_only, discount_percent, discount_products,
         discount_valid_days
    into offer from public.codes where code = upper(p_code) for no key update;
  if not found or offer.owner_user_id is distinct from owner_id then
    return jsonb_build_object('status', 'not_found');
  end if;

  checked_at := clock_timestamp();
  if profile.banned_at is not null then outcome := 'banned';
  elsif not offer.active or offer.starts_at > checked_at or offer.expires_at <= checked_at then outcome := 'expired';
  elsif offer.owner_user_id = p_user then outcome := 'own';
  elsif exists (select 1 from public.code_redemptions where code_id = offer.id and user_id = p_user) then outcome := 'used';
  elsif offer.redemption_count >= offer.max_redemptions then outcome := 'full';
  elsif (offer.new_users_only or offer.kind = 'invite')
    and profile.created_at + make_interval(days => p_invite_window_days) <= checked_at then outcome := 'new_users_only';
  elsif offer.kind = 'invite' then
    select signup_ip, banned_at into inviter from public.profiles where id = offer.owner_user_id;
    if inviter.banned_at is not null then outcome := 'expired';
    elsif exists (select 1 from public.code_redemptions where user_id = p_user and kind = 'invite') then outcome := 'already_invited';
    elsif exists (select 1 from public.payments where user_id = p_user) then outcome := 'new_users_only';
    elsif inviter.signup_ip = profile.signup_ip then outcome := 'blocked_same_ip';
    elsif not exists (select 1 from public.credit_ledger l
      where l.idempotency_key = 'signup:' || p_user and l.user_id = p_user and l.kind = 'grant' and l.pool = 'free') then
      outcome := 'blocked_no_signup_grant';
    end if;
  end if;

  if outcome <> 'ok' then
    if outcome in ('blocked_same_ip', 'blocked_no_signup_grant') then
      insert into public.code_redemptions(code_id, kind, user_id, inviter_user_id, context, status)
        values (offer.id, offer.kind, p_user, offer.owner_user_id, p_context, outcome);
    end if;
    return jsonb_build_object('kind', offer.kind, 'status', outcome);
  end if;

  if offer.discount_percent is not null then
    -- The user lock serializes simultaneous claims of different offers. An old Stripe
    -- session may still be payable after its campaign was paused or its offer expired.
    select r.id, c.code, c.active, c.starts_at, c.expires_at, r.discount_expires_at, r.checkout_expires_at
      into pending from public.code_redemptions r join public.codes c on c.id = r.code_id
      where r.user_id = p_user and r.discount_used_payment_id is null and r.discount_void_at is null
        and r.status = 'ok' and c.discount_percent is not null;
    if found then
      if pending.checkout_expires_at > checked_at then
        return jsonb_build_object('kind', offer.kind, 'status', 'checkout_in_progress');
      end if;
      replaced := pending.active and (pending.starts_at is null or pending.starts_at <= checked_at)
        and (pending.expires_at is null or pending.expires_at > checked_at)
        and (pending.discount_expires_at is null or pending.discount_expires_at > checked_at);
      if replaced and p_replace is not true then
        return jsonb_build_object('kind', offer.kind, 'status', 'needs_confirm', 'current_code', pending.code);
      end if;
      -- Void even a dormant offer so reactivating its campaign cannot resurrect two discounts.
      update public.code_redemptions set discount_void_at = checked_at where id = pending.id;
    end if;
    deadline := least(offer.expires_at, checked_at + make_interval(days => offer.discount_valid_days));
  end if;

  credits := case when offer.kind = 'invite' then
    (select (value->>'inviteeCredits')::integer from public.system_settings where key = 'code_invite_rewards')
    else coalesce(offer.invitee_credits, 0) end;
  grant_pool := case when offer.kind = 'invite' then 'free' else offer.invitee_pool end;
  insert into public.code_redemptions
    (id, code_id, kind, user_id, inviter_user_id, context, status, credits_granted, discount_expires_at)
    values (redemption_id, offer.id, offer.kind, p_user, offer.owner_user_id, p_context, 'ok', credits, deadline);
  update public.codes set redemption_count = redemption_count + 1 where id = offer.id;
  if credits > 0 then
    perform public._apply_credit_change(p_user, grant_pool, 'code_grant', credits, 'Code redemption', 'code:' || redemption_id);
  end if;
  return jsonb_build_object('status', 'ok', 'kind', offer.kind, 'credits_granted', credits, 'pool', grant_pool,
    'discount_percent', offer.discount_percent, 'discount_products', offer.discount_products,
    'discount_expires_at', deadline, 'replaced', replaced);
end;
$_$;


ALTER FUNCTION "public"."redeem_code"("p_user" "uuid", "p_code" "text", "p_context" "text", "p_invitee_credits" integer, "p_invite_window_days" integer, "p_replace" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."redeem_limited_code"("p_user" "uuid", "p_code" "text", "p_context" "text", "p_invitee_credits" integer, "p_invite_window_days" integer, "p_replace" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  checked_at timestamptz;
  attempts timestamptz[];
  result jsonb;
begin
  if p_user is null or p_context is null or p_context not in ('account','paywall') then
    raise exception 'INVALID_INPUT';
  end if;
  -- Serialize this quota without taking a profile lock ahead of redeem_code: reciprocal
  -- invites lock both profiles in sorted order, which must remain the first profile locks.
  perform pg_advisory_xact_lock(hashtextextended('shotviva.code_redeem:' || p_user::text, 0));
  checked_at := clock_timestamp();
  select array(select t from unnest(p.code_redeem_attempts) as a(t)
                where t > checked_at - interval '1 hour')
    into attempts from public.profiles p where id = p_user;
  if not found then raise exception 'PROFILE_NOT_FOUND'; end if;
  if cardinality(attempts) >= 10 then return jsonb_build_object('status', 'rate_limited'); end if;

  if p_code is null or p_code !~ '^[A-Za-z0-9]{4,20}$' then
    result := jsonb_build_object('status', 'invalid_input');
  else
    result := public.redeem_code(p_user,p_code,p_context,p_invitee_credits,p_invite_window_days,p_replace);
  end if;
  update public.profiles set code_redeem_attempts = array_append(attempts, checked_at) where id = p_user;
  return result;
end;
$_$;


ALTER FUNCTION "public"."redeem_limited_code"("p_user" "uuid", "p_code" "text", "p_context" "text", "p_invitee_credits" integer, "p_invite_window_days" integer, "p_replace" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."refund_eligibility"("p_payment_id" bigint, "p_asked_at" timestamp with time zone) RETURNS TABLE("first_purchase" boolean, "within_7_days" boolean, "no_credits_used" boolean, "suggested_cents" integer)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_payment public.payments;
begin
  select * into v_payment from public.payments p where p.id = p_payment_id;
  if not found then
    raise exception 'PAYMENT_NOT_FOUND';
  end if;

  first_purchase := not exists (
    select 1 from public.payments q
     where q.user_id = v_payment.user_id
       and q.id < v_payment.id
       and (q.product_id like 'pack\_%') = (v_payment.product_id like 'pack\_%')
  );
  within_7_days := coalesce(p_asked_at, now()) - v_payment.created_at <= interval '7 days';
  no_credits_used := not exists (
    select 1 from public.credit_ledger l
     where l.user_id = v_payment.user_id and l.kind = 'reserve' and l.created_at > v_payment.created_at
  );
  suggested_cents := greatest(0, least(
    round((v_payment.amount_total - v_payment.amount_tax) * 0.94)::integer + v_payment.amount_tax,
    v_payment.amount_total - v_payment.amount_refunded
  ));
  return next;
end;
$$;


ALTER FUNCTION "public"."refund_eligibility"("p_payment_id" bigint, "p_asked_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."refund_job"("p_job_id" "uuid", "p_error_code" "text", "p_provider_usage" "jsonb" DEFAULT NULL::"jsonb", "p_cost_usd" numeric DEFAULT NULL::numeric) RETURNS "public"."generation_jobs"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_user_id uuid;
  v_job public.generation_jobs;
begin
  select user_id into v_user_id from public.generation_jobs where id = p_job_id;
  if not found then
    raise exception 'JOB_NOT_FOUND';
  end if;

  -- Same lock order as reserve_credits (profile, then job) so the two cannot deadlock.
  perform 1 from public.profiles where id = v_user_id for update;
  select * into v_job from public.generation_jobs where id = p_job_id for update;

  if v_job.status = 'failed' then
    return v_job;
  end if;
  if v_job.status = 'succeeded' then
    raise exception 'JOB_ALREADY_SETTLED';
  end if;

  perform public._apply_credit_change(
    v_user_id, v_job.credit_pool, 'refund', v_job.credits_cost, 'generation refund',
    'job:' || p_job_id::text || ':refund', p_job_id
  );

  update public.generation_jobs
     set status = 'failed', error_code = coalesce(nullif(p_error_code, ''), 'UNKNOWN'), finished_at = now(),
         provider_usage = p_provider_usage, cost_usd = p_cost_usd
   where id = p_job_id
  returning * into v_job;
  return v_job;
end;
$$;


ALTER FUNCTION "public"."refund_job"("p_job_id" "uuid", "p_error_code" "text", "p_provider_usage" "jsonb", "p_cost_usd" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."release_batch_zip"("p_user_id" "uuid", "p_batch_id" "uuid", "p_token" "uuid") RETURNS "void"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  update admin.batch_zip_requests set active_batches=active_batches-p_batch_id::text
   where user_id=p_user_id and active_batches->p_batch_id::text->>'token'=p_token::text;
$$;


ALTER FUNCTION "public"."release_batch_zip"("p_user_id" "uuid", "p_batch_id" "uuid", "p_token" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."release_checkout_discount"("p_user" "uuid", "p_token" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  perform 1 from public.profiles where id = p_user for no key update;
  update public.code_redemptions set checkout_token = null, checkout_expires_at = null, checkout_prepared = false
   where user_id = p_user and discount_used_payment_id is null and discount_void_at is null
     and checkout_token = p_token;
  return found;
end;
$$;


ALTER FUNCTION "public"."release_checkout_discount"("p_user" "uuid", "p_token" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."report_work"("p_job_id" "uuid", "p_reporter" "uuid", "p_reason" "text", "p_note" "text") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_note text := nullif(btrim(coalesce(p_note, '')), '');
begin
  if p_job_id is null or p_reporter is null then
    raise exception 'INVALID_INPUT' using detail = 'job and reporter are required';
  end if;
  if p_reason is null or p_reason not in ('sexual', 'violence', 'hate', 'minor', 'privacy', 'ip', 'spam', 'other') then
    raise exception 'INVALID_INPUT' using detail = 'unknown reason';
  end if;
  if v_note is not null and length(v_note) > 500 then
    raise exception 'INVALID_INPUT' using detail = 'note is at most 500 characters';
  end if;
  if not exists (select 1 from public.profiles p where p.id = p_reporter and p.banned_at is null) then
    raise exception 'FORBIDDEN';
  end if;
  if not exists (
      select 1 from public.generation_jobs j
       where j.id = p_job_id and j.status = 'succeeded' and j.visibility = 'public' and j.moderation_status = 'approved'
         and j.deleted_at is null and j.source = 'web' and j.template_id <> 'freeform') then
    raise exception 'NOT_FOUND';
  end if;
  if exists (select 1 from public.work_reports r where r.job_id = p_job_id and r.reporter_id = p_reporter) then
    return 'duplicate';
  end if;
  -- Serialise one reporter's reports so two at once cannot both pass the daily cap.
  perform pg_advisory_xact_lock(hashtextextended('report_work:' || p_reporter::text, 0));
  if (select count(*) from public.work_reports r
       where r.reporter_id = p_reporter and r.created_at > now() - interval '1 day') >= 20 then
    return 'limited';
  end if;
  insert into public.work_reports (job_id, reporter_id, reason, note)
  values (p_job_id, p_reporter, p_reason, v_note)
  on conflict on constraint work_reports_once_per_reporter do nothing;
  return case when found then 'reported' else 'duplicate' end;
end;
$$;


ALTER FUNCTION "public"."report_work"("p_job_id" "uuid", "p_reporter" "uuid", "p_reason" "text", "p_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reserve_batch_cell"("p_job_id" "uuid", "p_user_id" "uuid", "p_module" "text", "p_template_id" "text", "p_credits_cost" integer, "p_inputs" "jsonb", "p_provider" "text", "p_visibility" "text") RETURNS "public"."generation_jobs"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  job public.generation_jobs;
  batch uuid := (p_inputs->>'batch_id')::uuid;
  position_in_batch integer := (p_inputs->>'batch_position')::integer;
begin
  job := public.reserve_credits(p_job_id,p_user_id,p_module,p_template_id,p_credits_cost,'web',
    p_inputs,p_provider,null,p_visibility,null);
  if job.inputs->>'attempt_id' is distinct from p_inputs->>'attempt_id' then return job; end if;
  if job.credit_pool <> 'paid' then raise exception 'CREDITS_INSUFFICIENT'; end if;
  -- Legacy single-template batch clients do not have a preflight ID.
  if batch is null then return job; end if;
  if position_in_batch is null then raise exception 'INVALID_INPUT'; end if;
  if job.credits_cost is distinct from p_credits_cost then raise exception 'TEMPLATE_QUOTE_CHANGED'; end if;
  if (p_inputs->>'batch_templates')::integer > 1 and public.current_tier(p_user_id) is distinct from 'max' then
    raise exception 'BATCH_MAX_REQUIRED';
  end if;
  if exists (
    select 1 from public.generation_jobs j where j.user_id=p_user_id and j.batch_id=batch
      and j.status<>'failed' and (j.inputs->>'batch_position')::integer=position_in_batch and j.id<>p_job_id
  ) then raise exception 'IDEMPOTENCY_CONFLICT'; end if;
  update public.generation_jobs set batch_id=batch where id=p_job_id returning * into job;
  return job;
end;
$$;


ALTER FUNCTION "public"."reserve_batch_cell"("p_job_id" "uuid", "p_user_id" "uuid", "p_module" "text", "p_template_id" "text", "p_credits_cost" integer, "p_inputs" "jsonb", "p_provider" "text", "p_visibility" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reserve_checkout_discount"("p_user" "uuid", "p_product_id" "text", "p_token" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_discount jsonb;
  v_token uuid;
  v_deadline timestamptz;
  v_now timestamptz;
  v_prepared boolean;
begin
  if p_token is null then raise exception 'INVALID_INPUT'; end if;
  perform 1 from public.profiles where id = p_user and banned_at is null for no key update;
  if not found then raise exception 'CODE_CHECKOUT_FORBIDDEN'; end if;
  v_discount := public.checkout_discount(p_user, p_product_id);
  if v_discount is null then return null; end if;

  select checkout_token, checkout_expires_at, checkout_prepared into v_token, v_deadline, v_prepared
    from public.code_redemptions where id = (v_discount->>'redemption_id')::uuid;
  v_now := clock_timestamp();
  if v_deadline > v_now and v_token <> p_token then
    return jsonb_build_object('status', 'in_use', 'expires_at', extract(epoch from v_deadline)::bigint);
  end if;
  if v_token = p_token and v_deadline <= v_now then
    return jsonb_build_object('status', 'expired');
  end if;
  if v_token is distinct from p_token then
    -- A crash before preparing a request cannot strand the discount for 30 minutes.
    v_deadline := to_timestamp(ceil(extract(epoch from v_now))) + interval '60 seconds';
    v_prepared := false;
    update public.code_redemptions set checkout_token = p_token, checkout_expires_at = v_deadline, checkout_prepared = false
      where id = (v_discount->>'redemption_id')::uuid;
  end if;
  return v_discount || jsonb_build_object('status', 'reserved', 'prepared', v_prepared, 'expires_at', extract(epoch from v_deadline)::bigint);
end;
$$;


ALTER FUNCTION "public"."reserve_checkout_discount"("p_user" "uuid", "p_product_id" "text", "p_token" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reserve_credits"("p_job_id" "uuid", "p_user_id" "uuid", "p_module" "text", "p_template_id" "text", "p_credits_cost" integer, "p_source" "text", "p_inputs" "jsonb" DEFAULT '{}'::"jsonb", "p_provider" "text" DEFAULT NULL::"text", "p_idempotency_key" "text" DEFAULT NULL::"text", "p_visibility" "text" DEFAULT NULL::"text", "p_parent_job_id" "uuid" DEFAULT NULL::"uuid") RETURNS "public"."generation_jobs"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_profile public.profiles;
  v_job public.generation_jobs;
  v_pool text;
  v_resolution text := coalesce(p_inputs ->> 'resolution', '1k');
  v_cost integer;
  v_v2 boolean;
  v_template public.templates;
begin
  perform pg_advisory_xact_lock_shared(hashtextextended('shotviva.template_catalog',0));
  if v_resolution not in ('1k', '2k', '3k') then
    raise exception 'INVALID_INPUT' using detail = 'resolution must be 1k, 2k or 3k';
  end if;
  -- The `edit` template is only for edits, and an edit only runs on it.
  if (p_template_id = 'edit') <> (p_parent_job_id is not null) then
    raise exception 'INVALID_INPUT' using detail = 'an edit runs on the edit template with a parent job';
  end if;

  -- Lock the profile first so concurrent reserves for one user run one at a time: the pool
  -- choice below always sees the balances the previous reserve left.
  select * into v_profile from public.profiles where id = p_user_id for update;
  if not found then
    raise exception 'PROFILE_NOT_FOUND';
  end if;

  select * into v_job from public.generation_jobs where id = p_job_id;
  if found then
    if v_job.user_id <> p_user_id then
      raise exception 'IDEMPOTENCY_CONFLICT';
    end if;
    return v_job;
  end if;

  if p_idempotency_key is not null then
    select * into v_job from public.generation_jobs
     where user_id = p_user_id and idempotency_key = p_idempotency_key;
    if found then
      return v_job;
    end if;
  end if;

  if v_profile.banned_at is not null then
    raise exception 'USER_BANNED';
  end if;

  -- Someone else's work, a failed, running or deleted one, or a missing one all look the same.
  if p_parent_job_id is not null then
    perform 1 from public.generation_jobs
     where id = p_parent_job_id and user_id = p_user_id and status = 'succeeded' and deleted_at is null;
    if not found then
      raise exception 'PARENT_JOB_NOT_FOUND';
    end if;
  end if;

  v_v2 := admin.is_template_catalog_v2();
  select t.* into v_template from public.templates t where t.id=p_template_id for share;
  v_cost := (v_template.credits_cost->>v_resolution)::integer;
  if not found then
    raise exception 'TEMPLATE_NOT_FOUND';
  end if;

  if v_v2 then
    if not v_template.is_active or (p_template_id<>'edit' and not
        (case when p_source='graylum' then 'partner' else 'web' end=any(v_template.visible_in))) then
      raise exception 'TEMPLATE_NOT_FOUND';
    end if;
    if p_credits_cost is distinct from v_cost then raise exception 'TEMPLATE_QUOTE_CHANGED'; end if;
  end if;
  -- Price the route selected by the server against the locked template before any debit.
  -- Check the persisted binding as well, covering older callers and concurrent rebinding.
  if p_inputs ? 'quality' and p_inputs->>'quality' is distinct from v_template.quality then
    raise exception 'TEMPLATE_QUOTE_CHANGED';
  end if;
  if not admin.reservation_route_allowed(v_template,p_provider,v_resolution,v_cost,
      coalesce(p_inputs->>'fallback_route'='true',false),v_v2) then
    raise exception 'TEMPLATE_UNAVAILABLE';
  end if;
  if v_profile.credits >= v_cost then
    v_pool := 'paid';
  elsif v_profile.free_credits >= v_cost then
    v_pool := 'free';
  else
    raise exception 'CREDITS_INSUFFICIENT';
  end if;

  perform public._apply_credit_change(
    p_user_id, v_pool, 'reserve', -v_cost, 'generation reserve',
    'job:' || p_job_id::text || ':reserve', p_job_id
  );

  insert into public.generation_jobs
    (id, user_id, module, template_id, inputs, provider, source, idempotency_key,
     credit_pool, visibility, credits_cost, parent_job_id)
  values
    (p_job_id, p_user_id, p_module, p_template_id,
     (coalesce(p_inputs, '{}'::jsonb)-'pricing_catalog_version') || jsonb_build_object('resolution',v_resolution)
       || case when v_v2 then '{"pricing_catalog_version":"v2"}'::jsonb else '{}'::jsonb end,
     p_provider, p_source,
     p_idempotency_key,
     v_pool,
     -- Free works are always public (ARCHITECTURE §9); paid works default to private.
     case when v_pool = 'paid' then coalesce(p_visibility, 'private') else 'public' end,
     v_cost,
     p_parent_job_id)
  returning * into v_job;

  return v_job;
end;
$$;


ALTER FUNCTION "public"."reserve_credits"("p_job_id" "uuid", "p_user_id" "uuid", "p_module" "text", "p_template_id" "text", "p_credits_cost" integer, "p_source" "text", "p_inputs" "jsonb", "p_provider" "text", "p_idempotency_key" "text", "p_visibility" "text", "p_parent_job_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."resume_catalog_checkout"("p_user" "uuid", "p_token" "uuid", "p_hash" "text", "p_channel" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare a admin.catalog_checkout_attempts;
begin
  select * into a from admin.catalog_checkout_attempts where token=p_token;
  if not found then return null; end if;
  if (a.user_id,a.request_hash,a.channel) is distinct from (p_user,p_hash,p_channel)
    or a.expires_at<=now() then raise exception 'IDEMPOTENCY_CONFLICT'; end if;
  return jsonb_build_object('params',a.params,'session_id',a.session_id,'session_url',a.session_url);
end
$$;


ALTER FUNCTION "public"."resume_catalog_checkout"("p_user" "uuid", "p_token" "uuid", "p_hash" "text", "p_channel" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_job_visibility"("p_job_id" "uuid", "p_user_id" "uuid", "p_visibility" "text") RETURNS "public"."generation_jobs"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_job public.generation_jobs;
begin
  if p_visibility is null or p_visibility not in ('public', 'private') then
    raise exception 'INVALID_INPUT' using detail = 'visibility must be public or private';
  end if;

  select * into v_job from public.generation_jobs
   where id = p_job_id and user_id = p_user_id and deleted_at is null
     for update;
  if not found then
    raise exception 'JOB_NOT_FOUND';
  end if;

  if v_job.credit_pool = 'free' and p_visibility = 'private' then
    raise exception 'FREE_WORK_PUBLIC';
  end if;

  update public.generation_jobs set visibility = p_visibility where id = p_job_id
  returning * into v_job;
  return v_job;
end;
$$;


