CREATE OR REPLACE FUNCTION "public"."templates_sync_category"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
begin
  if new.category_key is not null and (tg_op = 'INSERT' or new.category_key is distinct from old.category_key) then
    -- The key was written: the name follows it below.
    null;
  elsif tg_op = 'INSERT' or new.category is distinct from old.category then
    -- Only the name was written. A rename of the template's own category keeps its key.
    if tg_op = 'INSERT' or not exists (
      select 1 from public.template_categories c
      where c.key = new.category_key
        and (c.key = btrim(new.category) or lower(c.name_en) = lower(btrim(new.category)) or c.name_zh = btrim(new.category))
    ) then
      new.category_key := public.template_category_for(new.category);
    end if;
  end if;
  -- An unknown key keeps a non-null name, so the foreign key (not NOT NULL) is what refuses it.
  new.category := coalesce((select c.name_en from public.template_categories c where c.key = new.category_key), new.category, new.category_key);
  return new;
end;
$$;


ALTER FUNCTION "public"."templates_sync_category"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."toggle_template_request_vote"("p_request_id" "uuid", "p_user_id" "uuid") RETURNS TABLE("voted" boolean, "votes_count" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_status text;
  v_weight smallint;
begin
  if not public.wishlist_eligible(p_user_id) then
    raise exception 'WISHLIST_NOT_ELIGIBLE';
  end if;

  select r.status into v_status from public.template_requests r where r.id = p_request_id for update;
  if not found then
    raise exception 'REQUEST_NOT_FOUND';
  end if;
  if v_status <> 'live' then
    raise exception 'REQUEST_NOT_LIVE';
  end if;

  delete from public.template_request_votes v
   where v.request_id = p_request_id and v.user_id = p_user_id;
  if found then
    voted := false;
  else
    v_weight := case when public.current_tier(p_user_id) = 'max' then 3 else 1 end;
    insert into public.template_request_votes (request_id, user_id, weight)
    values (p_request_id, p_user_id, v_weight);
    voted := true;
  end if;

  select r.votes_count into votes_count from public.template_requests r where r.id = p_request_id;
  return next;
end;
$$;


ALTER FUNCTION "public"."toggle_template_request_vote"("p_request_id" "uuid", "p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."unavailable_batch_template"("p_routes" "jsonb") RETURNS "text"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare candidate record; t public.templates;
begin
  if jsonb_typeof(p_routes) is distinct from 'array' or jsonb_array_length(p_routes) not between 1 and 30
    then raise exception 'INVALID_INPUT'; end if;
  for candidate in select * from jsonb_to_recordset(p_routes)
    as r(template_id text,resolution text,provider text,expected_credits integer,fallback_route boolean)
  loop
    if candidate.template_id is null then raise exception 'INVALID_INPUT'; end if;
    select * into t from public.web_generation_template(candidate.template_id);
    if not found or not admin.template_route_allowed(t,candidate.provider,candidate.resolution,
        candidate.expected_credits,coalesce(candidate.fallback_route,false)) then return candidate.template_id; end if;
  end loop;
  return null;
end $$;


ALTER FUNCTION "public"."unavailable_batch_template"("p_routes" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."web_generation_template"("p_template_id" "text") RETURNS SETOF "public"."templates"
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  select t.* from public.templates t join admin.published_web_members m using(id) where m.id=p_template_id
$$;


ALTER FUNCTION "public"."web_generation_template"("p_template_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."web_templates"("p_series_id" "uuid" DEFAULT NULL::"uuid", "p_template_id" "text" DEFAULT NULL::"text", "p_include_members" boolean DEFAULT false) RETURNS SETOF "public"."templates"
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  select t.* from public.web_template_members m join public.templates t on t.id=m.id
  where (p_series_id is null and p_template_id is null and (m.standalone or p_include_members)) or m.series_id=p_series_id or m.id=p_template_id
$$;


ALTER FUNCTION "public"."web_templates"("p_series_id" "uuid", "p_template_id" "text", "p_include_members" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."wishlist_eligible"("p_user_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select exists (
           select 1 from public.generation_jobs j
            where j.user_id = p_user_id and j.status = 'succeeded'
         )
     and exists (
           select 1 from public.profiles p
            where p.id = p_user_id and p.banned_at is null
         );
$$;


ALTER FUNCTION "public"."wishlist_eligible"("p_user_id" "uuid") OWNER TO "postgres";


