GRANT SELECT,INSERT,DELETE ON TABLE "public"."template_favorites" TO "authenticated";



GRANT SELECT ON TABLE "public"."template_prompt_versions" TO "service_role";



GRANT SELECT ON TABLE "public"."template_request_notices" TO "authenticated";
GRANT SELECT,INSERT ON TABLE "public"."template_request_notices" TO "service_role";



GRANT UPDATE("seen_at") ON TABLE "public"."template_request_notices" TO "authenticated";
GRANT UPDATE("seen_at") ON TABLE "public"."template_request_notices" TO "service_role";



GRANT SELECT,REFERENCES,TRIGGER,TRUNCATE,MAINTAIN ON TABLE "public"."template_request_votes" TO "service_role";
GRANT SELECT ON TABLE "public"."template_request_votes" TO "authenticated";



GRANT SELECT ON TABLE "public"."template_sale_approvals" TO "service_role";



GRANT SELECT,INSERT ON TABLE "public"."template_sync_history" TO "service_role";



GRANT SELECT,REFERENCES,TRIGGER,TRUNCATE,MAINTAIN ON TABLE "public"."work_reports" TO "service_role";



GRANT UPDATE ON SEQUENCE "public"."work_reports_id_seq" TO "anon";
GRANT UPDATE ON SEQUENCE "public"."work_reports_id_seq" TO "authenticated";
GRANT UPDATE ON SEQUENCE "public"."work_reports_id_seq" TO "service_role";



ALTER DEFAULT PRIVILEGES FOR ROLE "postgres" IN SCHEMA "public" GRANT ALL ON SEQUENCES TO "postgres";
ALTER DEFAULT PRIVILEGES FOR ROLE "postgres" IN SCHEMA "public" GRANT UPDATE ON SEQUENCES TO "anon";
ALTER DEFAULT PRIVILEGES FOR ROLE "postgres" IN SCHEMA "public" GRANT UPDATE ON SEQUENCES TO "authenticated";
ALTER DEFAULT PRIVILEGES FOR ROLE "postgres" IN SCHEMA "public" GRANT UPDATE ON SEQUENCES TO "service_role";






ALTER DEFAULT PRIVILEGES FOR ROLE "postgres" IN SCHEMA "public" GRANT ALL ON FUNCTIONS TO "postgres";






ALTER DEFAULT PRIVILEGES FOR ROLE "postgres" IN SCHEMA "public" GRANT ALL ON TABLES TO "postgres";
ALTER DEFAULT PRIVILEGES FOR ROLE "postgres" IN SCHEMA "public" GRANT REFERENCES,TRIGGER,TRUNCATE,MAINTAIN ON TABLES TO "anon";
ALTER DEFAULT PRIVILEGES FOR ROLE "postgres" IN SCHEMA "public" GRANT REFERENCES,TRIGGER,TRUNCATE,MAINTAIN ON TABLES TO "authenticated";
ALTER DEFAULT PRIVILEGES FOR ROLE "postgres" IN SCHEMA "public" GRANT REFERENCES,TRIGGER,TRUNCATE,MAINTAIN ON TABLES TO "service_role";

-- Triggers on tables outside public that call public functions.

CREATE TRIGGER affiliate_accept_invite AFTER UPDATE OF email_confirmed_at ON auth.users FOR EACH ROW WHEN (((old.email_confirmed_at IS NULL) AND (new.email_confirmed_at IS NOT NULL) AND (new.invited_at IS NOT NULL))) EXECUTE FUNCTION public._affiliate_accept_invite();

CREATE TRIGGER on_auth_user_created AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.handle_new_user();
